window.JASTROW_CHUNKS[10]={"4000":{"h":"בֵּיבַאי","r":"B00543","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּיבַי\">בֵּיבַי</a></div>","alt":[]},"4001":{"h":"ביבון","r":"B00544","html":"<div class=\"sense\"> pr. n. m. <span class=\"citation\">Y. Gitt. VII, 48ᵈ</span> <span dir=\"rtl\">ר׳ ב׳</span>, read as Y. B. Bath. VIII, 16ᶜ top, <a href=\"#\" data-headword=\"בִּין\">בּוּן</a>.</div>","alt":[]},"4002":{"h":"בִּיבֵי","r":"B00545","html":"<div class=\"sense\"> (vive) <i>long live!</i> <span class=\"citation\">Lam. R. to I, 5</span> ב׳ דומינו וכ׳ Ar. (read <span dir=\"rtl\">דומיני</span>, vive domine imperator) long live my lord the Emperor. [Ed. <span dir=\"rtl\">וביבא מארי אפלטור</span>, Syriac, corr. <span dir=\"rtl\">ביבי</span>.]</div>","alt":[]},"4003":{"h":"בֵּיבַי","r":"B00546","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> , 11; <span class=\"citation\">Neh. VII, 16</span>) <i>Bebai.</i> <span class=\"citation\">Shek. V, 1</span> <span dir=\"rtl\">בן בבי</span>; <span class=\"citation\">Yoma 23ᵃ</span> <a href=\"#\" data-headword=\"בִּרְיְתָא\">בי׳</a>. <span class=\"citation\">Ib. 34ᵇ</span> רב ב׳ R. B., an Amora. <span class=\"citation\">B. Bath. 36ᵇ</span>; a. e.—[<span class=\"citation\">Y. Maasr. V, 52ᵃ</span> <span dir=\"rtl\">בעל ביבי</span>, read <a href=\"#\" data-headword=\"בְּכִי I\">בֶּכִי</a> q. v.]</div>","alt":["בֵּיבַאי","בֵּבַי"]},"4004":{"h":"*בֵּיבַנִּי","r":"B00547","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">בי בני</span>, v. <a href=\"#\" data-headword=\"בַּאנִּי\">בַּנִּי</a>) <i>bath-house</i>. Y. Ter. VIII, end, 46ᶜ; (<span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">בי בני</span>). Y. Sabb. VIII, end, 11ᶜ <span dir=\"rtl\">גו ב׳</span> in (the water of) the bath house.</div>","alt":[]},"4005":{"h":"בִּיבָר","r":"B00548","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (vivarium, βιβάριον) <i>vivarium</i>, an enclosure in which live game, fish &amp;c. (also wild beasts) are kept. <span class=\"citation\">Snh. 39ᵃ</span> <span dir=\"rtl\">לשדיוה לב׳</span> must be thrown into the vivarium. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שדיוה וכ׳</span> they threw him &amp;c. but they (the beasts) did not eat him. <span class=\"citation\">Bets. 24ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">בִּיבָרִים</span>, <span dir=\"rtl\">בִּיבָרִין</span>. <span class=\"citation\">Ib. III, 1</span>; a. fr. v. <a href=\"#\" data-headword=\"בִּיבָרְיָא\">בִּיבָרְיָא</a>.</div>","alt":[]},"4006":{"h":"ביברי","r":"B00549","html":"<div class=\"sense\">, <span class=\"citation\">Ḥull. 127ᵃ</span>, read <span dir=\"rtl\">בי ברי</span>, v. <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a></div>","alt":[]},"4007":{"h":"בִּיבָרְיָא","r":"B00550","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (pl. of vivarium, v. <a href=\"#\" data-headword=\"בִּיבָר\">בִּיבָר</a>) <i>animals kept in the vivarium, game</i>. <span class=\"citation\">Pesik. R. s. 16</span>; Pesik. Eth Korb. p. 58ᵇ; Yalk. Num. 777; Kings 176; <span class=\"citation\">Koh. R. to II, 7</span> (corrupted <span dir=\"rtl\">ציב׳</span>, <span dir=\"rtl\">ברב׳</span> &amp;c.; expl. <span dir=\"rtl\">בַּרְבֻּרִים אֲבֻסִים</span> <span class=\"citation\">I Kings V, 3</span> <i>chosen, fattened</i>) <span dir=\"rtl\">מיני ב׳</span> various kinds of game (deer &amp;c.) from the vivarium. V. <a href=\"#\" data-headword=\"בַּרְבַּרְיָא\">בַּרְבַּרְיָא</a>, end.</div>","alt":["בִּיבָרְיָיא"]},"4008":{"h":"בִּידְ־","r":"B00551","html":"<div class=\"sense\">, v. <span dir=\"rtl\">בִּדְ־</span></div>","alt":[]},"4009":{"h":"בִּידָּא","r":"B00552","html":"<div class=\"sense\">, Pi. of <a href=\"#\" data-headword=\"בָּדָא\">בָּדָא</a>.</div>","alt":[]},"4010":{"h":"בִּידָּא ²","r":"B00553","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (בְּדִי I; cmp. <a href=\"#\" data-headword=\"בִּדִּין\">בִּדִּין</a>) <i>fiction, false report, information</i>. <span class=\"citation\">Y. Sot. IX, 23ᶜ</span> bot.; <span class=\"citation\">Y. Yeb. XVI, 15ᶜ</span> <span dir=\"rtl\">ואתצידו כולהון מן ב׳</span> and they were all taken prisoners owing to the information against them. [Rabad Seder hak-Kabb. a. other chroniclers have erroneously <span dir=\"rtl\">ונתלה ר׳ שרירא מידו אחת</span>, read … <span dir=\"rtl\">מן בידה</span> or <a href=\"#\" data-headword=\"בִּידָּא ²\">בידו</a>.]</div>","alt":["בִּידּוּ"]},"4011":{"h":"בִּידּוּר","r":"B00554","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּדּוּר\">בִּדּוּר</a></div>","alt":["בִּידּוּרָא"]},"4012":{"h":"בִּידִּין","r":"B00555","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּדִּין\">בִּדִּין</a></div>","alt":[]},"4013":{"h":"בִּיהוּלְתָּא","r":"B00556","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"בֶּהָלָה\">בֶּהָלָה</a>. <span class=\"citation\">Targ. O. Lev. XXVI, 16</span>; a. e. (ed. also <a href=\"#\" data-headword=\"בַּהוּלְתָּא\">בַּהוּלְתָּא</a>).</div>","alt":[]},"4014":{"h":"בִּיהוּתָא","r":"B00557","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּהַת\">בהת</a>) <i>shame</i>. <span class=\"citation\">Targ. II Chr. XXXII, 21</span>, constr. <span dir=\"rtl\">בִּיהוּת</span>; v. <a href=\"#\" data-headword=\"בַּהֲתָא\">בַּהֲתָא</a>.</div>","alt":[]},"4015":{"h":"ביוכא","r":"B00558","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּיְיכָא\">בַּיְיכָא</a></div>","alt":[]},"4016":{"h":"בִּיּוּנָא","r":"B00559","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בין</span>) = <a href=\"#\" data-headword=\"בִּינָא I\">בֹּינָא</a> <i>understanding</i>. <span class=\"citation\">Targ. Prov. II, 3</span>; a. fr.</div>","alt":["בִּיּוּנָנוּתָא","בִּיּוּנְתָּא","בְּיוּ׳"]},"4017":{"h":"בִּיזָּא I","r":"B00560","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (בזי II) </div><div class=\"sense\"><b>1)</b> <i>rent, cleft</i>. <span class=\"citation\">Lev. R. s. 19</span> Ar. [<a href=\"#\" data-headword=\"לֹא\">לא</a>] <span dir=\"rtl\">דמי הדין ריסא להדין ב׳</span> (ed., v. <a href=\"#\" data-headword=\"*אָלִיס\">אָלִיס</a> a. <a href=\"#\" data-headword=\"בִּיזְעָא\">בִּיזְעָא</a>).—Pl. <span dir=\"rtl\">בִּיזֵּי</span>. <span class=\"citation\">B. Bath. 74ᵃ</span>; <span class=\"citation\">Snh. 110ᵃ</span> אחוי ליה תרי ב׳ Ar. he showed him two clefts in the ground (ed. <span dir=\"rtl\">חזאי תרי ביזעי</span>); Ar. ed. pr. Var. … <span dir=\"rtl\">חזאי ביזתא דסליק תננא מינה</span> (Ms. R. <a href=\"#\" data-headword=\"כַּוָּוא\">כוותא</a>, v. Rabb. D. S. a. l. note) I saw a cleft out of which smoke rose.</div><div class=\"sense\"><b>—2)</b> <i>ruin, destruction</i>. <span class=\"citation\">Targ. Is. LX, 18</span> (h. text <span dir=\"rtl\">שׁד̇</span>); v. <a href=\"#\" data-headword=\"בִּיזָּא\">next w.</a></div>","alt":["בִּזָּא","בִּיזְתָא"]},"4018":{"h":"בִּיזָּא","r":"B00561","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"בִּזָּה\">בִּזָּה</a> <i>dividing; plunder, spoil.</i> <span class=\"citation\">Nah. III, 1</span>. <span class=\"citation\">Targ. O. Ex. XV, 9</span>; a. fr.—<span class=\"citation\">Lam. R. to II, 13</span> <span dir=\"rtl\">בערביא וכ׳</span> in Arabia they call spoil (<span dir=\"rtl\">ביזתא</span>) ăditha (with ref. to <span dir=\"rtl\">אעידך</span> ib.). Cmp. <span dir=\"rtl\">עֲדוּדָה</span>. [<span class=\"citation\">Targ. Is. LX, 16</span> (h. text <span dir=\"rtl\">שׁד̇</span>); v. <a href=\"#\" data-headword=\"בִּיזָּא I\">preced.</a> w.]—Trnsf. <a href=\"#\" data-headword=\"בּוּזְתָא\">בִּיזְתָא</a> <i>robbed</i> woman. <span class=\"citation\">Midr. Till. to Ps. I, 2</span> <span dir=\"rtl\">הא ב׳ עלובתא</span> this poor robbed woman; <span class=\"citation\">Yalk. Num. 750</span> (incorr. vers.).</div>","alt":["בִּזָּא II","בִּיזְתָא","בִּזְּתָא"]},"4019":{"h":"בִּיזָּא III","r":"B00562","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בּוּזְתָא\">בִּיזְתָא</a> f.) (<a href=\"#\" data-headword=\"בָּזַז\">בזז</a>, cmp. <a href=\"#\" data-headword=\"*בְּזִיזִי\">בְּזִיזֵי</a>; cmp. <span dir=\"rtl\">שׁד̇</span>, <a href=\"#\" data-headword=\"שַׁד\">שַׁד</a>) <i>feeder</i>, whence <i>pap, breast</i>. <span class=\"citation\">Targ. Y. Num. XI, 8</span> (<i>brisket</i>, v. <a href=\"#\" data-headword=\"*בִּיזִּיאָה\">ביזיאה</a>; h. text <span dir=\"rtl\">לְשַׁד</span>, cmp. <a href=\"#\" data-headword=\"שַׁד\">שַׁד</a>).—Y. Kil. I, 27ᵇ top <span dir=\"rtl\">ליט ב׳ וכ׳</span> cursed be the breast which nursed such a man.—Pl. <a href=\"#\" data-headword=\"*בִּיזְיָא\">בִּיזַּיָּא</a>. <span class=\"citation\">Targ. Job XXI, 24</span> <span dir=\"rtl\">בִּיזוֹי</span> (Var. <span dir=\"rtl\">תדיוהי</span>).—<span class=\"citation\">Gen. R. s. 5</span> <span dir=\"rtl\">לייטין ב׳ וכ׳</span>, v. supra; Pesik. Zakh. p. 23ᵇ (Ar. sing.). <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> bot.</div>","alt":[]},"4020":{"h":"בִּיזְגָּא","r":"B00563","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּזְגָּא\">בַּזְגָּא</a></div>","alt":[]},"4021":{"h":"בִּיזָּה","r":"B00564","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>spoil.</i> <span class=\"citation\">Num. R. s. 13</span>, end <span dir=\"rtl\">בִּיזַּת הים</span> spoil made at the Red Sea, <span dir=\"rtl\">ב׳ מצרים</span> made in Egypt; a. e.—Pl. <span dir=\"rtl\">בִּיזּוֹת</span>. <span class=\"citation\">Lam. R. to II, 13</span> (ref. to <span dir=\"rtl\">אעידך</span> ib.; cmp. <a href=\"#\" data-headword=\"בִּיזְּתָא\">בִּיזְּתָא</a> s. v. <a href=\"#\" data-headword=\"בִּיזָּא I\"><span dir=\"rtl\">בִּיזָּא</span> II</a>) <span dir=\"rtl\">כמה ב׳ וכ׳</span> how often did I give you the spoils of your enemies.</div>","alt":[]},"4022":{"h":"בִּיזּוּעַ","r":"B00565","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּזַע\">בזע</a>) <i>rending, rent</i>. <span class=\"citation\">Targ. Joel II, 13</span>.—[<span dir=\"rtl\">ביזועותא</span>, v. <a href=\"#\" data-headword=\"בִּיזְעָא\">בִּיזְעָא</a>.]</div>","alt":["בִּזּ׳"]},"4023":{"h":"*בִּיזְיָא","r":"B00566","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (בזי II) <i>rag, wreck</i>. <span class=\"citation\">Gen. R. s. 30</span> <span dir=\"rtl\">ב׳ סבא</span> old rag (contemptuous designation of an old man).</div>","alt":["בִּזְיָא"]},"4024":{"h":"*בִּיזִּיאָה","r":"B00567","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בִּיזָּא III\"><span dir=\"rtl\">ביזא</span> III</a>) <i>brisket</i>. <span class=\"citation\">Gen. R. s. 34</span> Ar. <span dir=\"rtl\">וכבדו ב׳ דיסקוס נאה</span> (ed. <span dir=\"rtl\">דורון נאה</span>, which is the interpret. of our w. in Ar.).—[The orig. vers. prob. read <span dir=\"rtl\">בביזא נאה על דיסקוס נאה</span> with a fine brisket on a fine plate; v. <span class=\"citation\">Yalk. Gen. 60</span>; Ps. 697.]</div>","alt":[]},"4025":{"h":"בִּיזָּיוֹן","r":"B00568","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּיזּוּעַ\">בִּזָּ׳</a></div>","alt":[]},"4026":{"h":"ביזיונא","r":"B00569","html":"<div class=\"sense\">, v. <span dir=\"rtl\">בזיו׳</span></div>","alt":[]},"4027":{"h":"בִּיזְלֵי","r":"B00570","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (בזי II, <a href=\"#\" data-headword=\"ל\">ל</a> format.) <i>cuts, rents</i>, whence <i>disconnected outskirts</i> of a community. <span class=\"citation\">B. Bath. 68ᵇ</span> (expl. <span dir=\"rtl\">שייריה</span>) <a href=\"#\" data-headword=\"בִּיזְלֵי\">ביזלי</a>. What is bizlé? <span dir=\"rtl\">פיסקי בגי</span>, v. <a href=\"#\" data-headword=\"בָּאגָא\">בָּאגָא</a>; Y. ib. IV, 14ᶜ bot. <span dir=\"rtl\">שוריה בזייה</span> (read <span dir=\"rtl\">שְׁיָרֶיהָ</span>).</div>","alt":["בְּזַיָּיה"]},"4028":{"h":"בִּיזְעָא","r":"B00571","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּזַע\">בזע</a>) <i>rent, split, cleft</i>. <span class=\"citation\">Ab. Zar. 70ᵃ</span> <span dir=\"rtl\">הוה ב׳ בדשא</span> there was a crack in the door. <span class=\"citation\">Cant. R. to IV, 14</span> (<span class=\"citation\">Koh. R. to X, 18</span> <a href=\"#\" data-headword=\"בְּקִיעָה\">בקיעה</a>), v. <a href=\"#\" data-headword=\"*אָלִיס\">אָלִיס</a>; <span class=\"citation\">Lev. R. s. 19</span>, v. <a href=\"#\" data-headword=\"בִּיזָּא I\"><span dir=\"rtl\">בִּיזָּא</span> I</a>.—Pl. <a href=\"#\" data-headword=\"בִּיזְלֵי\">בִּיזְעֵי</a>. <span class=\"citation\">Taan. 21ᵇ</span> דאית ביה ב׳ ב׳ Ar. s. v. <span dir=\"rtl\">כסילתא</span> (ed. <span dir=\"rtl\">קרנא דהוה בזיע</span>, Ms. M. v. Rabb. D. S. a. l.), v. <a href=\"#\" data-headword=\"כּוֹסֵילְתָּא\">כּוֹסִילְתָּא</a>. <span class=\"citation\">Num. R. s. 18</span> <span dir=\"rtl\">אזלי וחזאי תרי ב׳</span>; <span class=\"citation\">Snh. 110ᵃ</span>, v. <a href=\"#\" data-headword=\"בִּיזָּא I\"><span dir=\"rtl\">בִּיזָּא</span> I</a>.</div>","alt":["(בִּיזְעָה)"]},"4029":{"h":"בִּיזְרָא","r":"B00572","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּזְרָא\">בִּזְרָ׳</a></div>","alt":["בִּיזְרָנָא"]},"4030":{"h":"בִּיזְּתָא","r":"B00573","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּיזָּא\">בִּיזָּא</a></div>","alt":[]},"4031":{"h":"*בֵּיזְתָא","r":"B00574","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Bez’tha</i> (contr. of <span dir=\"rtl\">בי זיתא</span> Olive-town), near Pumbeditha. <span class=\"citation\">Erub. 52ᵃ</span> <span dir=\"rtl\">תהא שביתתי</span> [<a href=\"#\" data-headword=\"ב\">ב</a>]ב׳ Ar. (ed. <span dir=\"rtl\">בצינתא</span>; Ms. M. <span dir=\"rtl\">בני זיתא</span> read <span dir=\"rtl\">בבי</span>; Ms. O. <span dir=\"rtl\">בזיתא</span>; v. Rabb. D. S. a. l.) my central point for Sabbath distances be in B.</div>","alt":[]},"4032":{"h":"*בִּיחוּשָׁא","r":"B00575","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּחֲשָׁא\">בַּחֲשָׁא</a></div>","alt":[]},"4033":{"h":"בִּיחֵיל","r":"B00576","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּחַל I\">בָּחַל</a></div>","alt":[]},"4034":{"h":"ביט","r":"B00577","html":"<div class=\"sense\">, <span class=\"citation\">Y. Shebu. III, 34ᵈ</span> bot., read <a href=\"#\" data-headword=\"בֵּיעָא\">בֵּיעָא</a>.</div>","alt":["ביטא"]},"4035":{"h":"בֵּיטָא I","r":"B00578","html":"<div class=\"sense\"> (βῆτα) <i>Beta</i>, second letter of the Greek Alphabet. <span class=\"citation\">Shek. III, 2</span>. Y. ed. (Bab. <a href=\"#\" data-headword=\"בי\">בי&quot;תא</a> corr. acc.).</div>","alt":[]},"4036":{"h":"בִּיטּוּי","r":"B00579","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בטי\">בטי</a>) <i>vain, useless talk</i>, ref. to vows and oaths which neither benefit nor injure anybody; <span dir=\"rtl\">שבועת ב׳</span> a useless oath, contrad. to <span dir=\"rtl\">ש׳ שוא</span> a false oath or one asserting something impossible. <span class=\"citation\">Shebu. III, 9</span> sq. <span class=\"citation\">Ib. 49ᵇ</span>; <span class=\"citation\">B. Mets. 36ᵃ</span> an oath imposed in court <span dir=\"rtl\">אין בה משום שבועת ב׳</span> does not come under the law of vain oaths (as to sacrifices). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ב׳ שפתים</span> erroneous statement without legal consequences, oppos. to <span dir=\"rtl\">כפירת ממון</span> whereby somebody lost money. [Y. Naz. I, beg. 51ᵃ <span dir=\"rtl\">שביטוי שבועה</span>, read <span dir=\"rtl\">שכִּינּוּיֵי</span>.]</div>","alt":["בִּטּוּי"]},"4037":{"h":"בִּיטּוּל","r":"B00580","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּטֵל I\">בטל</a>) <i>interruption, loss of time; abrogation; relinquishment, renunciation</i>. <span class=\"citation\">Kidd. 33ᵃ</span> <span dir=\"rtl\">קימה שאין בה ב׳</span> rising (in honor of an elder &amp;c.) which causes no interruption of labor.—<span dir=\"rtl\">ב׳ תורה</span> neglect of the study of the Law. <span class=\"citation\">Sabb. 32ᵇ</span>; a. fr.—<span class=\"citation\">Men. 99ᵃ</span> sq. <span dir=\"rtl\">פעמים שבִּיטוּלָהּ וכ׳</span> sometimes the neglect of the Law is its establishing. <span class=\"citation\">Sabb. XVI, 1</span> <span dir=\"rtl\">ב׳ בה&quot;מ</span> neglect of lectures (through reading at home). <span class=\"citation\">Y. Peah IV, 18ᵇ</span>, a. e. <span dir=\"rtl\">ב׳ עניים</span> loss of time to the poor (when compelled to wait for their share in the crop).—<span class=\"citation\">Erub. 66ᵇ</span> <span dir=\"rtl\">ב׳ רשות</span>, v. <a href=\"#\" data-headword=\"בָּטֵל I\">בָּטֵל</a> Pi.—<span class=\"citation\">Y. Gitt. IV, 46ᵃ</span> top, a. fr. <span dir=\"rtl\">ב׳ פריה ורביה</span> neglect of marital life.—Y. Ab. Zar. III, 43ᵈ bot. <span dir=\"rtl\">יש לה ב׳</span> can be cancelled, v. ib. IV, 4 s. v. <a href=\"#\" data-headword=\"בָּטֵל I\">בָּטֵל</a> Pi.—<span class=\"citation\">Pes. 4ᵇ</span> <span dir=\"rtl\">בב׳ בעלמא וכ׳</span> a mere relinquishment of possession would be sufficient.; a. v. fr.</div>","alt":["בִּטּ׳"]},"4038":{"h":"בִּיטּוּלָא","r":"B00581","html":"<div class=\"sense\"><span class=\"citation\">Targ. Prov. XV, 22</span>.—<span class=\"citation\">Ab. Zar. 53ᵇ</span></div>","alt":["בִּטּ׳"]},"4039":{"h":"בִּיטָּחוֹן","r":"B00582","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּטָּחוֹן\">בִּטָּחוֹן</a></div>","alt":[]},"4040":{"h":"בִּיטִי","r":"B00583","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּטִי\">בְּטִי</a></div>","alt":[]},"4041":{"h":"בִּיטִיתָא","r":"B00584","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּטִּיתָא\">בּוּטִּיתָא</a></div>","alt":[]},"4042":{"h":"בִּיטְנָתָא","r":"B00585","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בטן</span>) <i>pregnancy, growth of the embryo</i>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד מאת׳ 6) <span dir=\"rtl\">אילין ירחי דב׳ דילידתא</span> (strike out one of the two terms).</div>","alt":[]},"4043":{"h":"בִּיטְשָׁא","r":"B00586","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּטַשׁ\">בטש</a>) <i>stamping, fulling</i>. <span class=\"citation\">B. Kam. 99ᵃ</span> <span dir=\"rtl\">ב׳ ב׳ וכ׳</span> (<a href=\"#\" data-headword=\"בִּיטּוּל\">בִּט׳</a>) for every stamping manipulation one M’ah.—Pl. <span dir=\"rtl\">בִּיטְשֵׁי</span> <span class=\"citation\">Ib.</span> (Var. <span dir=\"rtl\">לבטושי</span>), v. <a href=\"#\" data-headword=\"בְּטַשׁ\">בְּטַשׁ</a>.</div>","alt":["בּוּטְשָׁא"]},"4044":{"h":"בַּיִי","r":"B00587","html":"<div class=\"sense\">, = <a href=\"#\" data-headword=\"בַּיִת\">בַּיִת</a>, v. <a href=\"#\" data-headword=\"*בַּרְבַּיִי\">בַּרְבַּיִי</a></div>","alt":[]},"4045":{"h":"בִּיָיא I","r":"B00588","html":"<div class=\"sense\"> (via), v. <a href=\"#\" data-headword=\"בִּיָּא\">בִּיָּא</a></div>","alt":[]},"4046":{"h":"בִּיָיא II","r":"B00589","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (βία) </div><div class=\"sense\"><b>1)</b> <i>force, act of violence, extortion, wrong</i>. <span class=\"citation\">Gen. R. s. 93</span> (play on <i>bi</i>, <span class=\"citation\">Gen. XLIV, 18</span>) <span dir=\"rtl\">ב׳ אתה מעביר עלינו</span> thou passest violence over us (thou treatest us unjustly). <span class=\"citation\">Ex. R. s. 20</span> <span dir=\"rtl\">שמא … ב׳ וכ׳</span> do I ever wrong any creature? <span class=\"citation\">Deut. R. s. 2</span> (play on <span dir=\"rtl\">בבאה</span> <span class=\"citation\">Ez. VIII, 5</span>) <span dir=\"rtl\">הא ב׳ רבא לעלמא וכ׳</span> Oh, this great wrong in this world, v. infra. *<span class=\"citation\">Y. Ned. III, 38ᵃ</span> <span dir=\"rtl\">כן … כורוסתי בייה</span> that is the way one says to his neighbor (read <span dir=\"rtl\">כריזסתי</span> χαρίζεσθαι βίᾳ) to do a favor perforce (ref. to an invitation accompanied with a vow in case of refusal).</div><div class=\"sense\"><b>—2)</b>  interj. (= h. <a href=\"#\" data-headword=\"וַי\">וי</a>) <i>woe! help!</i> <span class=\"citation\">Yoma 69ᵇ</span> <span dir=\"rtl\">ב׳ ב׳ וכ׳</span> woe, woe, it is this (the tempter) that destroyed the Temple &amp;c. <span class=\"citation\">Yeb. 97ᵇ</span> <span dir=\"rtl\">ב׳ ב׳ מאה וכ׳</span> woe, woe over the brother who is &amp;c. <span class=\"citation\">Lev. R. s. 17</span>, end (play on <span dir=\"rtl\">בבאה</span>, v. supra) <span dir=\"rtl\">ב׳ ב׳ תותבא וכ׳</span> woe, woe, that the stranger dislodges the owner (idolatry in the Temple).</div>","alt":["בִּיָיה"]},"4047":{"h":"בייבא","r":"B00590","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּיְיכָא\">בַּיְיכָא</a></div>","alt":[]},"4048":{"h":"בייבין","r":"B00591","html":"<div class=\"sense\">, read <span dir=\"rtl\">בייכין</span>, v. <a href=\"#\" data-headword=\"בּוּךְ\">בּוּךְ</a></div>","alt":[]},"4049":{"h":"בַּיְידָּא","r":"B00592","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּדָּאָה\">בַּדָּאָה</a></div>","alt":[]},"4050":{"h":"בִּיָיה","r":"B00593","html":"<div class=\"sense\"><b>1)</b> <i>road</i>, v. <a href=\"#\" data-headword=\"בִּיָּא\">בִּיָּא</a>; </div><div class=\"sense\"><b>2)</b> <i>wrong</i>, v. <a href=\"#\" data-headword=\"בִּיָּא\">בִּיָיא</a>.</div>","alt":[]},"4051":{"h":"בָּיֵיךְ","r":"B00594","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּךְ\">בּוּךְ</a></div>","alt":[]},"4052":{"h":"בַּיְיכָא","r":"B00595","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בּוּךְ\">בוך</a>; cmp. <a href=\"#\" data-headword=\"סְבָכָה\">סְבָכָה</a>, <a href=\"#\" data-headword=\"סְבַכְתָּא\">סְבַכְתָּא</a>) <i>net, head-dress</i>. <span class=\"citation\">B. Bath. 146ᵃ</span> ‘small presents’, <span dir=\"rtl\">תרגמה רבא בייכא וסבכתא</span> Ar. s. v. <a href=\"#\" data-headword=\"ייכא\">ייכא</a> (ed. <a href=\"#\" data-headword=\"בייבא\">בייבא</a>, Ms. M. <span dir=\"rtl\">ביוב׳</span>, Ms. H. <a href=\"#\" data-headword=\"ביוכא\">ביוכא</a>, cmp. comment. <span dir=\"rtl\">כגון ב׳</span>; v. Koh. Ar. Compl. s. v.) said R., This means e.g. a net or a cap.</div>","alt":[]},"4053":{"h":"בָּיֵיל","r":"B00596","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּיל\">בִּיל</a></div>","alt":[]},"4054":{"h":"ביילין","r":"B00597","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. B. Mets. IX, 14</span>, v. <a href=\"#\" data-headword=\"כַּיָּיל\">כַּיָּיל</a></div>","alt":[]},"4055":{"h":"בַּיֵּין","r":"B00598","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּין\">בִּין</a> ch.</div>","alt":[]},"4056":{"h":"בִּיֵּיר","r":"B00599","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּר I\"><span dir=\"rtl\">בּוּר</span> I</a> h. a. ch.</div>","alt":["בַּיֵּיר","בָּיֵיר"]},"4057":{"h":"בַּיָּיר","r":"B00600","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"בֵּיר\">בֵּיר</a> or <a href=\"#\" data-headword=\"בֹּור\">בֹּור</a>, cmp. <a href=\"#\" data-headword=\"בּוּר\">בּוּר</a> Pi. 2) <i>superintendent of the well</i> in rural communities. <span class=\"citation\">Shebi. VIII, 5</span> <span dir=\"rtl\">אין נותנין לא לב׳ וכ׳</span> (out of the money realized from the fruits of the Sabbath year) you must not pay the well-master &amp;c.; <span dir=\"rtl\">אבל נותן הוא לב׳ לשתות</span> but you may pay the well-master a fee for giving you water to drink. <span class=\"citation\">Tosef. B. Mets. IX, 14</span> <span dir=\"rtl\">הב׳ והבלן וכ׳</span> (Y. ib. beg. 12ᵃ ed. Krot. <a href=\"#\" data-headword=\"הֵיכְדֵין\">הכ׳</a>, corr. acc.) the well-master, the bather &amp;c. when collecting their fees from the owner (individually), may attach only the owner’s share in the produces. Ib. VIII, 11ᵈ top <span dir=\"rtl\">שאלה מן הב׳</span>; [Bab. ib. 97ᵇ <span dir=\"rtl\">למישאל מידי מחבריה</span>, read <span dir=\"rtl\">מבַּיָּירָא</span> ch.].</div>","alt":[]},"4058":{"h":"בַּיִּיר","r":"B00601","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בּוּר\">בּוּר</a>) <i>untilled, waste ground</i>. <span class=\"citation\">Targ. Deut. XXI, 4</span> (virgin land, h. text <a href=\"#\" data-headword=\"אֵיתָן\">אֵיתָן</a>).—<span class=\"citation\">Targ. Is. XXVIII, 25</span>. <span class=\"citation\">Targ. Jer. XII, 13</span> <a href=\"#\" data-headword=\"בְּאַר\">בְּיַר</a>(!).—<span class=\"citation\">Lev. R. s. 1</span>, beg., v. <a href=\"#\" data-headword=\"בּוּר\">בּוּר</a> ch.</div>","alt":["בַּיָּר"]},"4059":{"h":"בַּיְישֹׁונִי","r":"B00602","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּישָׁנִי\">בֵּישָׁנִי</a></div>","alt":[]},"4060":{"h":"ביישיא","r":"B00603","html":"<div class=\"sense\">, <span class=\"citation\">Y. Bets. I, 60ᶜ</span> bot., read <span dir=\"rtl\">בִּישַׁיָּיא</span>.</div>","alt":[]},"4061":{"h":"בַּיְישָׁן","r":"B00604","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  (<a href=\"#\" data-headword=\"בּוֹשׁ\">בּוּשׁ</a>) <i>bashful, chaste; chaste person, bashful man</i>. <span class=\"citation\">Ned. 20ᵃ</span> <span dir=\"rtl\">סימן יפה באדם שהוא ב׳</span> it is a favorable indication in a man that he is bashful. <span class=\"citation\">Ab. II, 5</span>. <span dir=\"rtl\">הב׳</span> he who is ashamed (to ask questions at school); a. e.—Pl. <a href=\"#\" data-headword=\"בַּיְישַׁנָּאָה\">בַּיְישָׁנִים</a>, <a href=\"#\" data-headword=\"בַּיְישַׁנָּאָה\">בַּיְישָׁנִין</a>. <span class=\"citation\">Yeb. 79ᵃ</span>. <span class=\"citation\">Y. Snh. VI, 23ᵈ</span> <span dir=\"rtl\">בויישנין</span>(?); <span class=\"citation\">Num. R. s. 8</span>; Midr. Sam. ch. XXVIII; <span class=\"citation\">Midr. Till. to Ps. I</span>.</div><div class=\"sense\"><b>—2)</b>  v. <a href=\"#\" data-headword=\"בֵּישָׁן\">בֵּישָׁן</a></div>","alt":[]},"4062":{"h":"בַּיְישַׁנָּאָה","r":"B00605","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּישָׁנִי\">בּישָׁנִי</a></div>","alt":["בַּיְישָׁנִי"]},"4063":{"h":"בַּיְיתָא","r":"B00606","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּיתָא I\"><span dir=\"rtl\">בֵּיתָא</span> I</a></div>","alt":[]},"4064":{"h":"בַּיְיתוֹס","r":"B00607","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּיְתוֹס\">בַּיְתוֹס</a></div>","alt":[]},"4065":{"h":"בַּיָיתוֹת","r":"B00608","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"בַּיִת\">בַּיִת</a>) <i>animals lodged</i> (at certain seasons) <i>in sheds within town-limits</i>. <span class=\"citation\">Bets. V, 7</span> (<span class=\"citation\">40ᵃ</span>, Ms. M. <span dir=\"rtl\">ביאתות</span>); <span class=\"citation\">Sabb. 45ᵇ</span>; a. e.</div>","alt":[]},"4066":{"h":"*בִּיכַאי","r":"B00609","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*בּוּכְיָא\">בּוּכְיָא</a>) name of <i>a spider</i>. <span class=\"citation\">Tosef. Par. IX</span> (<span class=\"citation\">VIII), 6</span> ed. Zuck. (Var. <span dir=\"rtl\">מובאי</span> corrupt, R. S. to <span class=\"citation\">Toh. IX, 2</span> <a href=\"#\" data-headword=\"כובאי\">כובאי</a>).</div>","alt":[]},"4067":{"h":"בִּיכּוּרָה","r":"B00610","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּכּוּרָה\">בִּכּוּרָה</a></div>","alt":[]},"4068":{"h":"*בּיל","r":"B00611","html":"<div class=\"sense\"> Hif. <a href=\"#\" data-headword=\"יָבַל I\">הוֹבִיל</a> <i>to mix</i>, v. <a href=\"#\" data-headword=\"בִּיל\">next w.</a></div>","alt":[]},"4069":{"h":"בִּיל","r":"B00612","html":"<div class=\"sense\">(cmp. b. h. <a href=\"#\" data-headword=\"בָּלַל\">בָּלַל</a>) <i>to mix, knead;</i> trnsf. (cmp. <a href=\"#\" data-headword=\"גָּרַס\">גרס</a>, <span dir=\"rtl\">דרש</span>) <i>to study thoroughly</i>. <span class=\"citation\">Men. 65ᵃ</span> (play on <span dir=\"rtl\">בלשן</span>, <span class=\"citation\">Neh. VII, 7</span>; cmp. <span dir=\"rtl\">בלשׁ</span>) <span dir=\"rtl\">הוה בָּיֵיל … ודריש</span> he studied languages and explained them.</div><div class=\"sense\"><b>*. בַּיֵּיל</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"*בּיל\">same</a>; trnsf. <i>to discuss</i>. Y. Ab. Zar. III, 43ᵃ <span dir=\"rtl\">מאן דתני אוֹבִיל נייבל</span> (read <span dir=\"rtl\">נְבַיֵּיל</span>) he who reads in the Mish. (III, 5; v. <a href=\"#\" data-headword=\"בִּין\">בִּין</a> Hif.) <i>obil</i>, means, Let us discuss the subject.</div></div>","alt":["בּוּל"]},"4070":{"h":"בִּילְגָּה","r":"B00613","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Bilgah</i>, chief of a priests’ division; whence, fem. (sub. <span dir=\"rtl\">משפחת</span>) name of a priests’ division, v. <a href=\"#\" data-headword=\"מִשְׁמָר\">מִשְׁמָר</a>. <span class=\"citation\">Succ. V, 8</span> <span dir=\"rtl\">ב׳ לעולם וכ׳</span> the Bilgah division at all times distributes its shares of the show-bread in the Southern part of the Temple courts. <span class=\"citation\">Ib. 56ᵇ</span>; <span class=\"citation\">Tosef. ib. IV, 28</span> <a href=\"#\" data-headword=\"בִּילְגָּה\">בִּילְגָּא</a> ed. Zuck.</div>","alt":["בִּלְגָּה"]},"4071":{"h":"בילדין","r":"B00614","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. II, Num. XII, 7</span>, v. <a href=\"#\" data-headword=\"לִבְלָר\">לַבְלָר</a></div>","alt":[]},"4072":{"h":"בִּילָה","r":"B00615","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"בְּלִילָה\">בְּלִילָה</a>, fr. <a href=\"#\" data-headword=\"בָּלַל\">בלל</a>, cmp. <a href=\"#\" data-headword=\"נִידָּה\">נִידָה</a> <span class=\"citation\">Lam. I, 8</span>; <a href=\"#\" data-headword=\"עִילָה\">עִילָה</a> a. <a href=\"#\" data-headword=\"עֲלִילָה\">עֲלִילָה</a>) <i>thorough mixture, even distribution of mixed objects</i>. <span class=\"citation\">Zeb. 80ᵃ</span> <span dir=\"rtl\">יש ב׳</span> a mixture is considered evenly distributed in all its parts. <span class=\"citation\">R. Hash. 13ᵇ</span> <span dir=\"rtl\">לכל אין ב׳</span> none of the mixtures named is a real mixture (of even distribution), except wine and oil (being liquid). <span class=\"citation\">Ḥull. 83ᵇ</span>, a. fr. <span dir=\"rtl\">כל הראוי לב׳ וכ׳</span> wherever from the proportions and properties of the mixture a perfect fusion is possible, the real act of mixing thoroughly is not indispensable.</div>","alt":[]},"4073":{"h":"בילוות","r":"B00616","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Job XXXVIII, 37</span>, v. <a href=\"#\" data-headword=\"כִּילָוַות\">כילוות</a></div>","alt":[]},"4074":{"h":"בִּילוֹן","r":"B00617","html":"<div class=\"sense\">, <span class=\"citation\">Bekh. VII, 1</span>, v. <a href=\"#\" data-headword=\"כִּילוֹן\">כִּילוֹן</a></div>","alt":[]},"4075":{"h":"בילוניא","r":"B00618","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בִּלְיוֹנָא\">בִּלְיוֹנָא</a></div>","alt":[]},"4076":{"h":"*בילוס","r":"B00619","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. VII, 10ᵇ</span> bot. <span dir=\"rtl\">משיח ב׳</span> (Var. <a href=\"#\" data-headword=\"כ׳\">כ׳</a>), read <span dir=\"rtl\">חייב משום לש</span>. [Read the passage as follows: <span dir=\"rtl\">ההן דאגין גירקררין שרי זיפות שרי משרין חייב משום לש</span>—all of which belongs to line 26 fr. bottom]</div>","alt":["כילוס"]},"4077":{"h":"בילמי","r":"B00620","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 21</span>, read <span dir=\"rtl\">צַלְמִי</span>, v. <a href=\"#\" data-headword=\"צֶלֶם\">צֶלֶם</a>. [Read: <span dir=\"rtl\">הא בריית לך חברותך את וחברך בדמותי וצלמי</span></div>","alt":[]},"4078":{"h":"בילן","r":"B00621","html":"<div class=\"sense\">, <span class=\"citation\">Bekh. 43ᵇ</span> Ar., v. <a href=\"#\" data-headword=\"כִּילוֹן\">כִּילוֹן</a>; <span class=\"citation\">Kel. XX, 6</span> Ar., v. <a href=\"#\" data-headword=\"וִילוֹן\">וִילוֹן</a>; <span class=\"citation\">Targ. Y. Gen. XXV, 25</span> Ms., Lev. a. oth., v. <a href=\"#\" data-headword=\"כִּילַן\">כִּילַן</a>.</div>","alt":[]},"4079":{"h":"בילני","r":"B00622","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלְנֵי\">בַּלְנֵי</a></div>","alt":[]},"4080":{"h":"בילפט","r":"B00623","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּלְשָׁפָט\">בֵּלְשָׁפָט</a></div>","alt":[]},"4081":{"h":"*בִּילָּק","r":"B00624","html":"<div class=\"sense\"> (בִּלָּק Ar.) pr. n. m. <i>Billak</i>, in conjunction with <a href=\"#\" data-headword=\"חִילָּק\">חִילָּק</a>, <a href=\"#\" data-headword=\"חִלָּק\">חִלָּק</a>, fictitious names for <i>any men</i> (similar to our ‘Tom, Dick &amp; Harry’). <span class=\"citation\">Ḥull. 19ᵃ</span> אנא לא ח׳ וכ׳ I know no Ḥillak and no Billak (I know of no authorities or individual opinions), I only know a tradition. <span class=\"citation\">Snh. 98ᵇ</span> <span dir=\"rtl\">ח׳ וב׳ אכלי להו</span> (margin in Ms. M. <span dir=\"rtl\">חלק בלק</span>) shall Ḥ. a. B. (any persons indiscriminately) enjoy it?</div>","alt":[]},"4082":{"h":"בילקאות","r":"B00625","html":"<div class=\"sense\">, <span class=\"citation\">Sifré Deut. 36</span>, read <span dir=\"rtl\">בסילקאות</span>, v. <a href=\"#\" data-headword=\"בָּסִילְקִי\">בָּסִילְקִי</a></div>","alt":[]},"4083":{"h":"בילרין","r":"B00626","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוֹלְרִין\">בֹּולְרִין</a></div>","alt":[]},"4084":{"h":"בִּילְתִּין","r":"B00627","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלְתִּי\">בַּלְתִּין</a></div>","alt":[]},"4085":{"h":"בִּימָא","r":"B00628","html":"<div class=\"sense\">, <span class=\"citation\">Ab. Zar. 16ᵇ</span>, = <a href=\"#\" data-headword=\"בִּימָה\">next w.</a></div>","alt":[]},"4086":{"h":"בִּימָה","r":"B00629","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בָּמָה\">בָּמָה</a>) <i>elevated stand for public meetings</i> (for speakers, readers, holding court &amp;c.). <span class=\"citation\">Sot. VII, 8</span>. <span class=\"citation\">Succ. 51ᵇ</span>. <span class=\"citation\">Ab. Zar. I, 7</span> (<span class=\"citation\">ib. 16ᵇ</span> <a href=\"#\" data-headword=\"בִּימָא\">בימא</a>). <span class=\"citation\">Gen. R. s. 76</span> as if seated <span dir=\"rtl\">על ב׳ ודן</span> upon the platform and holding court. <span class=\"citation\">Lev. R. s. 13</span> <span dir=\"rtl\">ונראית כאילו מצעת ב׳</span> and gives itself the appearance as if holding court (giving the form of legality to robberies). <span class=\"citation\">Gen. R. s. 37</span> <span dir=\"rtl\">ב׳ של רשע</span> the court of injustice (Rome).—<span class=\"citation\">Koh. R. to I, 8</span> (<span class=\"citation\">Ab. Zar. 16ᵇ</span> <span dir=\"rtl\">גרדום</span>; <span class=\"citation\">Tosef. Ḥull. II, 24</span> <a href=\"#\" data-headword=\"בָּמָה\">במה</a>); a. fr.—Pl. (of <a href=\"#\" data-headword=\"בִּימָא\">בימא</a>) <a href=\"#\" data-headword=\"בִּימָס\">בִּימָאוֹת</a>. Pesik. B’shall. p. 84ᵃ (Ms. O. <span dir=\"rtl\">כסאות</span>; Tanḥ. ed. Bub. <span class=\"citation\">B’shall. 5</span> <span dir=\"rtl\">מגדלים</span>) (wooden) platforms.—<span dir=\"rtl\">בִּימוֹת</span>. <span class=\"citation\">Meg. 32ᵃ</span> <span dir=\"rtl\">הלוחות והב׳</span> (Ms. M. <span dir=\"rtl\">והבמות</span>; Y. ib. III, 73ᵈ bot. <span dir=\"rtl\">בימה ולווחין</span>) the tablets (in Synagogues, prob. used for announcements) and the raised seats (for readers or distinguished persons to speak from). [Ar. s. v. <span dir=\"rtl\">במות</span>, ref. to Meg. l. c., explains, <span dir=\"rtl\">לוחות</span> <i>the board-covers of books</i>, <span dir=\"rtl\">במות</span> <i>wooden stands</i> (<a href=\"#\" data-headword=\"עַמּוּד\">עמוד</a>) for exhibiting the Torah scrolls during the services; another opinion quot. in Ar.: <span dir=\"rtl\">לוחות</span> the blank margins between the columns of the scroll, <span dir=\"rtl\">במות</span> the upper and lower as well as the front and back margins; cmp. <span dir=\"rtl\">אריח</span> a. <span dir=\"rtl\">לבנה</span>.] [A derivation of our w. fr. βῆμα is excluded, because the sing., in that case, would be <a href=\"#\" data-headword=\"בִּימָא\">בימא</a> or <span dir=\"rtl\">בימטא</span> a. the pl. <span dir=\"rtl\">בימטין</span> or <span dir=\"rtl\">בימטאות</span>.]</div>","alt":[]},"4087":{"h":"בִּימוּס","r":"B00630","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (an adaptation of βωμός, treated in inflection as a cacophemism = <span dir=\"rtl\">בי מיאוס</span>, v. <span class=\"citation\">Tosef. Ab. Zar. V, 6</span>, quot. bel., cmp. <span dir=\"rtl\">איצטריא</span>; Syr. <span dir=\"rtl\">בומסא</span>, Ch. <a href=\"#\" data-headword=\"*בָּמָסָא\">בַּמְסָא</a>, <a href=\"#\" data-headword=\"בִּימְסָא\">בִּימְסָא</a>, <a href=\"#\" data-headword=\"בָּמוֹסָא\">בָּמוֹסָא</a>) <i>pedestal of idolatrous statuary</i>. <span class=\"citation\">Ab. Zar. III, 7</span> a stone originally hewn <span dir=\"rtl\">לב׳</span> for an idol’s pedestal. <span class=\"citation\">Tosef. ib. V</span> (<span class=\"citation\">VI), 8</span> <span dir=\"rtl\">ב׳ שנפגם</span> a broken bomos, (contrad. to <a href=\"#\" data-headword=\"מִזְבֵּחַ\">מזבח</a>); Bab. <span class=\"citation\">ib. 53ᵇ</span> bot. <span dir=\"rtl\">ב׳ אבן וכ׳</span> a bomos is made of one stone, an altar of several. <span class=\"citation\">Tosef. ib. VI, 10</span>; a. fr.—[<span class=\"citation\">Y. B. Mets. X, end, 12ᶜ</span> <span dir=\"rtl\">העלה על גבי ב׳</span>, read <a href=\"#\" data-headword=\"דִּימוֹס I\">דִּימוֹס</a>.]—Pl. <span dir=\"rtl\">בִּימוּסָאוֹת</span>, <a href=\"#\" data-headword=\"בִּימָס\">בִּימוּסְיָאוֹת</a>, <span dir=\"rtl\">בִּימוֹסִיֹּות</span>, <span dir=\"rtl\">בִּימְס׳</span>. <span class=\"citation\">Ab. Zar. IV, 6</span> (<span class=\"citation\">53ᵇ</span>) <span dir=\"rtl\">ב׳ של מלכים</span> (v. Rabb. D. S. a. l., Mish. N. <span dir=\"rtl\">בומסיות</span>) pedestals temporarily put up for the reception of princes (governors). Ib. 54ᵃ בימסיאות בשעת השמד Ms. M. (v. Rabb. D. S. a. l. note) idolatrous pedestals (or altars) erected during (the Hadrianic) persecution, <span dir=\"rtl\">אע&quot;פ שהשמד בטל אותן הב׳ לא ביטלו</span> although the persecution has been repealed, they (the Romans) have not cancelled these altars; v. <a href=\"#\" data-headword=\"בָּטֵל I\">בָּטֵל</a> Pi.—<span class=\"citation\">Gen. R. s. 53</span>, a. e. (some ed. <a href=\"#\" data-headword=\"בִּימָס\">בִּימָסוֹת</a>) altars. <span class=\"citation\">Tosef. Ab. Zar. V</span> (<span class=\"citation\">VI), 6</span> <span dir=\"rtl\">בֵּי מוּסְיָיאוֹת</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"בִּימָס\">בימסיות</a>). [<span class=\"citation\">Ab. Zar. I, 7</span> (<span class=\"citation\">16ᵃ</span>) <span dir=\"rtl\">בימוסיאות</span>, <a href=\"#\" data-headword=\"בִּימָס\">בימסיות</a>, read with Ms. M. a. Ar. <a href=\"#\" data-headword=\"דִּימוֹסִיּוֹת\">דִּימוֹסְיָאוֹת</a>.]</div>","alt":["בִּימָס"]},"4088":{"h":"בִּימִי","r":"B00631","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Bimi</i> = <a href=\"#\" data-headword=\"אַבִּימִי\">אַבִּימִי</a>. <span class=\"citation\">Y. Ber. IX, 14ᵃ</span> top <span dir=\"rtl\">אדא ור׳ ב׳</span> read: <span dir=\"rtl\">אדא בר ב׳</span>; <span class=\"citation\">Y. Taan. I, 64ᵇ</span> top <span dir=\"rtl\"><span dir=\"rtl\">בר איבומ׳</span> (איכומ׳</span>); v. Frank. M’bo p. 62ᵃ</div>","alt":[]},"4089":{"h":"בימין","r":"B00632","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Ps. 670</span>, v. <a href=\"#\" data-headword=\"*בָּאיָין\">בָּאיָין</a></div>","alt":[]},"4090":{"h":"בִּימָס","r":"B00633","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּימוּס\">בִּימוֹס</a></div>","alt":["בִּימָסוֹת","בִּימַסְיָאוֹת","בִּימַסְיוֹת"]},"4091":{"h":"בִּימְסָא","r":"B00634","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"בִּימוּס\">בִּימוֹס</a>. <span class=\"citation\">Ab. Zar. 53ᵇ</span></div>","alt":[]},"4092":{"h":"בִּין","r":"B00635","html":"<div class=\"sense\"> , v. <a href=\"#\" data-headword=\"בּוֹא\">בוא</a>) <i>to pierce, split, penetrate;</i> whence, <i>to discern, understand;</i> v. Hif.</div><div class=\"sense\"><b>*. בֹּונֵן</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בֵּין\">בֵּין</a>) <i>to cause to penetrate, to saturate</i>. Sifra Vayikra, N’dab., Par. 12, ch. XIV (ref. to <span class=\"citation\">Lev. II, 13</span>) <span dir=\"rtl\">יכול תְּבוֹנֵּהוּ</span> from <i>bammelaḥ</i> I might judge, ‘thou must thoroughly saturate it, <span dir=\"rtl\">ת&quot;ל תמלח</span> therefore it says, ‘timlaḥ’ (thou shalt strew). <span class=\"citation\">Men. 21ᵃ</span> (quoting Sifra l. c.) <span dir=\"rtl\">מאי תבונהו</span> what does the word <i>t’bonnehu</i> mean? Said R. b. U. <span dir=\"rtl\">ה&quot;ק יכול יִתְבֹּונֶנּוּ כתבן</span> (taking <a href=\"#\" data-headword=\"ת\">ת</a> as radical, as if imperat. of a verb <span dir=\"rtl\">תבן</span>, denom. of <a href=\"#\" data-headword=\"תֶּבֶן\">תֶּבֶן</a>) it means, I might suppose, he must mix it up like straw in clay (v. infra). Said A. to him <span dir=\"rtl\">א&quot;ה יתבוננו מיבעי ליה</span> if so, then it ought to read (in the Sifra) <i>yithbonennu</i> (third person). But said A. (taking it fr. <a href=\"#\" data-headword=\"בני\">בנה</a>) <span dir=\"rtl\">יכול יעשנו כבניין</span> I might suppose, he shall heap the salt upon it like a building (a pile). Said R. to him, <span dir=\"rtl\">א&quot;ה יבננו מיבעי ליה</span> then it ought to read <i>yibnennu</i>. But said R. (you must correct the Sifra so as to read) <span dir=\"rtl\">יכול תבוניהו</span> (corr. <span dir=\"rtl\">תָּבִינֵיהוּ</span>) thou shalt make it savory … <span dir=\"rtl\">יתן בו טעם כבינה</span> he shall put a taste into it as does understanding into a man, v. <a href=\"#\" data-headword=\"טַעַם\">טַעַם</a>. [<span class=\"citation\">Yalk. Lev. 454</span>: <span dir=\"rtl\">מאי יתבנהו … יכול יתבלנו כתבן וטיט … תבלנו מ&quot;ל … יכול יעשנו כבנין … א&quot;ה</span> .<span dir=\"rtl\">יבנהו מ&quot;ל … יכול תבינהו … יכול יתן בו טעם בבינה</span>—Ar. ed. Koh.: <span dir=\"rtl\"><span dir=\"rtl\">יכול תבניהו … מאי תבניהו … יכול יתבלנו</span> (<span dir=\"rtl\">הרבה במלח</span>) <span dir=\"rtl\">כתבן בטיט … יכול יתן בו טעם</span></span>, correct: <span dir=\"rtl\">יכול תבינהו יתן וכ׳</span>.]</div></div><div class=\"sense\"><b>Hif. הוֹבִין</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"הוֹבִיר\">הוֹבִיר</a>, s. v. <a href=\"#\" data-headword=\"בּוּר\">בּוּר</a>) (denomin. of <a href=\"#\" data-headword=\"בֵּין\">בֵּין</a>) <i>to mediate, to be interpreter</i>. <span class=\"citation\">Ab. Zar. III, 5</span> (<span class=\"citation\">45ᵃ</span>) <span dir=\"rtl\">אני אוֹבִין לפניך</span> (v. Rabb. D. S. a. l. note 8) let me be thy interpreter (let me explain what you mean) <span dir=\"rtl\">כל מקום וכ׳</span> (the words <span dir=\"rtl\">על ההרים וכ׳</span>, <span class=\"citation\">Deut. XII, 2</span>, are explanatory) wherever thou findest a high mountain &amp;c., know there must be an idol. [In the version <span dir=\"rtl\">אני אהיה אובין וכ׳</span>, <span dir=\"rtl\">אוֹבֵין</span> is used as a part. of a verb <span dir=\"rtl\">אָבֵין</span>, denomin. of <a href=\"#\" data-headword=\"בֵּין\">בֵּין</a>, to act as a mediator or interpreter.] 2) <span dir=\"rtl\">הֵבִין</span> (b. h.) <i>to perceive, make intelligible</i>, esp. <i>to find analogies</i> (between two cases). <span dir=\"rtl\">ה׳ דבר מתוך דבר</span> prop. to bring out one thing from between another, i.e. <i>to form a conclusion by analogy</i>. <span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">הֵבַנְתָּה וכ׳</span> hast thou cultivated thy mind to conclude &amp;c. (ref. to <a href=\"#\" data-headword=\"דַּעַת\">דעת</a> <span class=\"citation\">Is. XXXIII, 6</span>). <span class=\"citation\">Snh. 93ᵇ</span>; a. fr. <span class=\"citation\">Ḥag. II, 1</span> (<span class=\"citation\">11ᵇ</span>) <span dir=\"rtl\">חכם מֵבִין מדעתו</span> (not <span dir=\"rtl\">ומבין</span>, v. Rabb. D. S. a. l. note) a student able to speculate by himself, a thinker.—Ib. 13ᵃ bot. <span dir=\"rtl\">היה מֵבִין בהשמל</span> speculated over the ḥashmal (<span class=\"citation\">Ezek. I, 27</span>); a. fr.</div></div><div class=\"sense\"><b>Hithpo. a. Nithpo. הִתְבֹּונֵן  נִתְבֹּונָן</b> <div class=\"sense\"><i>to understand one’s self, to be careful, to reflect</i>. <span class=\"citation\">B. Kam. 27ᵇ</span> <span dir=\"rtl\">להתבונן בדרכים</span> to look around on roads (to be prepared for something in their way against which they might strike). <span class=\"citation\">Gen. R. s. 34</span> <span dir=\"rtl\">ויבן כתי׳ נתבונן</span> the word <span dir=\"rtl\">ויבן</span> (he built, <span class=\"citation\">Gen. VIII, 20</span>) may be read <i>vayaben</i>, i.e. he reflected, argued.</div></div>","alt":["בּוּן"]},"4093":{"h":"בִּין ²","r":"B00636","html":"<div class=\"sense\">; v. infra.—<i>Pa.</i> <a href=\"#\" data-headword=\"בַּיֵּין\">בַּיֵּין</a>, <a href=\"#\" data-headword=\"בַּיֵּין\">בַּיֵּן</a> <i>to teach, make wise</i>. <span class=\"citation\">Targ. Ps. CXIX, 27</span>. <span class=\"citation\">Targ. Job XXXII, 8</span>. Ib. v. 9 <span dir=\"rtl\">יְבַיְּנוּן דינא</span> explain the law (ed. Vienn. <span dir=\"rtl\">יְבִינוּן</span>, Pe., <i>understand</i>).</div><div class=\"sense\"><b>Ithpe. אִתְבְּיַן</b> <div class=\"sense\"><i>to reflect upon, to understand</i>. <span class=\"citation\">Targ. Job XXXII, 12</span>. <span class=\"citation\">Ib. XXVIII, 23</span>; a. fr. </div></div><div class=\"sense\"><b>Ithpol. אִתְבּוֹנַן</b> <div class=\"sense\"><i>to be considerate, cautious</i>. <span class=\"citation\">Lam. R. to I, 16</span>, beg., v. <a href=\"#\" data-headword=\"*בְּחִי\">בְּחִי</a>.</div></div>","alt":["בּוּן"]},"4094":{"h":"בַּיִן","r":"B00637","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, only in constr. <a href=\"#\" data-headword=\"בֵּין\">בֵּין</a>, <a href=\"#\" data-headword=\"בֵּינָת\">בינת־</a> (b. h.; <a href=\"#\" data-headword=\"בִּין ²\">preced.</a>, cmp. <span dir=\"rtl\">ביין</span>, <a href=\"#\" data-headword=\"*בָּאיָין\">באיין</a>) <i>something split</i>, or <i>placed between;</i> prep. <i>between, among</i>.—<span dir=\"rtl\">אין בין … ל</span> there is no difference betw. … and … <span class=\"citation\">Meg. I, 5</span>; a. fr.—<span dir=\"rtl\">בין השמשות</span> (abbr. <span dir=\"rtl\">בה&quot;ש</span>) <i>at twilight, dusk;</i> v. <a href=\"#\" data-headword=\"בֵּי\">בֵּי</a>. <span class=\"citation\">Ab. V, 6</span>; a. fr.—… ב׳ … ב׳ <i>both … as well as</i> … <span class=\"citation\">B. Kam. IV, 3</span>; a. fr.—<span class=\"citation\">Yeb. 23ᵃ</span> <span dir=\"rtl\">ב׳ אומרים לו וכ׳</span> whether the law says to thy father …, or &amp;c. <span class=\"citation\">Koh. R. to VII, 11</span> <span dir=\"rtl\">בין ווי לוה וכ׳</span> owing to the difference between <i>vay</i> (woe) and <i>vah</i> (ah), R. J. escaped.—<span dir=\"rtl\">דברים שֶׁבֵּינוֹ לְבֵינָהּ</span> private affairs concerning him (the husband) and her (the wife). <span class=\"citation\">Ned. 79ᵇ</span>; a. fr.—<i>Du.</i> <a href=\"#\" data-headword=\"בֵּינַיִין\">בֵּינַיִים</a>, <a href=\"#\" data-headword=\"בֵּנַיִים\">בֵּנַיִים</a>, <a href=\"#\" data-headword=\"בֵּינְתַּיִם\">בֵּינְתַּיִים</a>, <a href=\"#\" data-headword=\"בֵּינְתַּיִם\">בֵּנְתַּיִם</a> (for <span dir=\"rtl\">בֵּינוֹתַיִם</span>) <i>between two, among, amid</i>. <span class=\"citation\">Gen. R. s. 4</span> <span dir=\"rtl\">ביניים ובינתיים</span> in the very centre. <span class=\"citation\">Y. Ber. II, 5ᵇ</span> top. <span class=\"citation\">Y. Maasr. I, beg. 48ᶜ</span> <span dir=\"rtl\">טול מבנת׳</span> take from what is between the two, i.e. qualifications common to both; a. fr.—Constr. <span dir=\"rtl\">בֵּינֵי־</span>. <span class=\"citation\">Nidd. 67ᵇ</span> <span dir=\"rtl\">מפסקת בֵּינֵיהֶן</span> intervening between; a. fr.</div>","alt":[]},"4095":{"h":"בֵּין","r":"B00638","html":"<div class=\"sense\"> usu. pl. <a href=\"#\" data-headword=\"בֵּינֵי\">בֵּינֵי</a> ch. same. <span class=\"citation\">Targ. Gen. I, 6</span>; a. fr.—<span class=\"citation\">Ḥull. 114ᵃ</span>; <span class=\"citation\">Sabb. 132ᵇ</span> <span dir=\"rtl\">אתיא מִבֵּינַיָּיא</span> from between the two (from both cases combined) it may be concluded.—<span dir=\"rtl\">מאי בֵינַיְיהוּ</span> (abbr. <span dir=\"rtl\">מ&quot;ב</span>) wherein do they differ? <span dir=\"rtl\">איכא בינייהו</span> (abbr. <span dir=\"rtl\">א&quot;ב</span>) they differ as to … <span class=\"citation\">B. Mets. 15ᵇ</span>; a. v. fr.—<span dir=\"rtl\">ביני וביני</span> a) <i>in the meantime</i>. <span class=\"citation\">Yeb. 71ᵇ</span>; a. fr.—b) <i>the difference between</i> (these and other goods). <span class=\"citation\">Bets. 7ᵃ</span>; a. fr.—<span class=\"citation\">Ḥull. 47ᵃ</span> <span dir=\"rtl\">ההוא ב׳ וב׳</span> a case (of an abnormal lobe) between the normal lungs. [<span class=\"citation\">Targ. Am. IX, 9</span> <span dir=\"rtl\">מִבֵּינָהּ</span>, Var. <a href=\"#\" data-headword=\"מְבִינָא\">מבינא</a>, read <span dir=\"rtl\">מִבֵּינֵיה</span> from between its meshes.]</div>","alt":[]},"4096":{"h":"בִּינָא I","r":"B00639","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"בִּינָה\">בִּינָה</a>. <span class=\"citation\">Targ. Ps. XLIX, 4</span>. <span class=\"citation\">Targ. Job XII, 12</span>; <span class=\"citation\">13</span>; v. <a href=\"#\" data-headword=\"בִּיּוּנָא\">בִּיּוּנָא</a></div>","alt":["בִּינָתָא"]},"4097":{"h":"*בִּינָא II","r":"B00640","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. P. Sm. 519) <i>tamarisk</i>, (comment.: <i>willow</i>). <span class=\"citation\">Gitt. 68ᵇ</span> <span dir=\"rtl\">שורבינא וב׳</span> (perh. a tautography of <a href=\"#\" data-headword=\"שׁוּרְבִּינָא\">שורבינא</a>?).</div>","alt":[]},"4098":{"h":"בִּינָא III","r":"B00641","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בִּין\">בִּין</a>, cmp. <a href=\"#\" data-headword=\"בַּיִן\">בַּיִן</a>) <i>a thin thing, hair;</i> <span dir=\"rtl\">ב׳ דמיא</span> (cmp. <a href=\"#\" data-headword=\"נִימָא\">נִימָא</a>) <i>leech.</i> Pl. <a href=\"#\" data-headword=\"בִּינֵי\">בִּינֵי</a>. <span class=\"citation\">Gitt. 69ᵇ</span>. [<span class=\"citation\">Sabb. 67ᵃ</span>, v. <a href=\"#\" data-headword=\"בִּינְתָא I\">בִּינְתָא</a> I a. II.] Cmp. <a href=\"#\" data-headword=\"בִּינִיתָא\">בִּינִיתָא</a>.</div>","alt":[]},"4099":{"h":"בִּינָה","r":"B00642","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>intelligence, wisdom</i>. <span class=\"citation\">Nidd. 45ᵇ</span> (play on <span dir=\"rtl\">ויבן</span>, v. <a href=\"#\" data-headword=\"בִּין\">בִּין</a> Hithpa.) the Lord has given to woman <span dir=\"rtl\">ב׳ יתירה</span> greater (earlier maturity of) judgment. <span class=\"citation\">Ber. 10ᵃ</span> <span dir=\"rtl\">במקום ב׳</span> at the place of understanding (near the heart); a. fr.</div>","alt":[]},"4100":{"h":"בֵּינוֹנִי","r":"B00643","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בין</span>) <i>central, mean</i> (between extremes), <i>average</i>. <span class=\"citation\">Y. Sabb. I, 2ᵈ</span> bot. <span dir=\"rtl\">לא לח וכ׳</span> neither wet, nor dry, but between the two (moist). <span dir=\"rtl\">אדם ב׳</span> a man of average strength. <span class=\"citation\">Y. Ber. I, 2ᶜ</span> bot.; a. fr.—<span class=\"citation\">Sot. 42ᵇ</span> <span dir=\"rtl\">ב׳ שבאחיו</span> the middle betw. his brothers (the third of five).—Pl. <a href=\"#\" data-headword=\"בֵּינוֹנִי\">בֵּינוֹנִים</a>, <span dir=\"rtl\">בֵּינוֹנִיִּים</span>. <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">בֵּינוֹנֵי המדינה</span> people of the middle class, opp. <span dir=\"rtl\">גדולי</span>; <span class=\"citation\">Koh. R. to IX, 7</span> <span dir=\"rtl\">הבינונים</span>; Tanḥ. Emor 22 <span dir=\"rtl\">בריוני</span> (corr. acc.). <span class=\"citation\">R. Hash. 16ᵇ</span> <a href=\"#\" data-headword=\"ב׳\">ב׳</a> those between the very good and the very bad; a. fr.—Fem. <a href=\"#\" data-headword=\"בֵּינוֹנִי\">בֵּינוֹנִית</a>. <span class=\"citation\">Gitt. V, 1</span>, a. fr. (sub. <span dir=\"rtl\">שדה</span>) <i>a field of average fertility;</i> betw. <a href=\"#\" data-headword=\"עִידִּית\">עידית</a> a. <a href=\"#\" data-headword=\"זִיבּוּרִית\">זיבורית</a>.—<span class=\"citation\">Y. Taan. I, 64ᵃ</span> bot. <span dir=\"rtl\">הב׳</span> the intermediate rainy season.—<span class=\"citation\">Y. Ber. V, 9ᶜ</span> bot. there are three things of which too much or too little is obnoxious <span dir=\"rtl\">ובֵינוֹנִיתָן יפה</span> but a reasonable quantity good. <span class=\"citation\">Kel. XVII, 7</span>; a. fr.—Pl. <span dir=\"rtl\">בֵּינוֹנִיּוֹת</span>. <span class=\"citation\">Ib. 10</span> <span dir=\"rtl\">היו ב׳</span> were mean cubits; <span class=\"citation\">Y. Shek. VI, 49ᵈ</span> top <span dir=\"rtl\">הוא כבניינות</span>; <span class=\"citation\">Y. Sot. VIII, 22ᶜ</span> bot. <span dir=\"rtl\">בבינויות</span> (corr. acc.).</div>","alt":[]},"4101":{"h":"בִּינוּתָא","r":"B00644","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"בִּינָא I\"><span dir=\"rtl\">בִּינָא</span> I</a>. Targ. II Esth. I, 2, beg. <span dir=\"rtl\">בינות ליבא</span>.</div>","alt":[]},"4102":{"h":"בִּינְזָא","r":"B00645","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Binza</i>. <span class=\"citation\">Bets. 28ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"בִּיסְנָא\">ביסנא</a>; v. Rabb. D. S. a. l. note).</div>","alt":[]},"4103":{"h":"בֵּינֵי","r":"B00646","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּין\">בֵּין</a> ch.</div>","alt":[]},"4104":{"h":"בִּינֵי","r":"B00647","html":"<div class=\"sense\"> pl. of <a href=\"#\" data-headword=\"בִּינָא III\"><span dir=\"rtl\">בִּינָא</span> III</a>, a. of <a href=\"#\" data-headword=\"בִּינְתָא I\">בִּינְתָא</a>.</div>","alt":[]},"4105":{"h":"בֵּינַיִין","r":"B00648","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">בין</span>) <i>intervals</i>, empty spaces between the rows of vine. <span class=\"citation\">Y. Kil. IV, 29ᶜ</span> top (R. S. to <span class=\"citation\">Kil. IV, 5</span> <a href=\"#\" data-headword=\"בֵּינַיִין\">בינים</a>). Ib. beg. 29ᵃ, v. <a href=\"#\" data-headword=\"*כַּרְמון\">כַּרְמוֹן</a>. Cmp. <a href=\"#\" data-headword=\"*בַּתְוָא\">בַּתְוָותָא</a>.</div>","alt":["בֵּינַיִן","בֵּינַיִם"]},"4106":{"h":"בִּינְיָין","r":"B00649","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּנְיָן\">בִּנְיָן</a></div>","alt":["בִּינְיָן"]},"4107":{"h":"בִּינִיתָא","r":"B00650","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בִּינָא III\"><span dir=\"rtl\">בִּינָא</span> III</a>; P. Sm. 520) <i>binitha;</i></div><div class=\"sense\"><b>1)</b> <i>a small fish</i> (collect.). <span class=\"citation\">B. Kam. 19ᵇ</span> <span dir=\"rtl\">חמרא דאכל ב׳</span> an ass that swallowed fish (something unusual). <span class=\"citation\">B. Mets. 79ᵇ</span> bot. <span dir=\"rtl\">ב׳ אכרסה תקלא</span> according to the size of its belly is the weight of fish (if you buy by weight, have the belly first removed; diff. in Ar.). Ib. 59ᵇ bot. (prov.) if one has a hanged one in his family, say not in his presence <span dir=\"rtl\">זקוף בי׳</span> hang the fish up; <span class=\"citation\">Yalk. Ex. 349</span> <a href=\"#\" data-headword=\"בִּינְתָא I\">בינתא</a> (corr. acc.); ib. Lev. 617 <span dir=\"rtl\">בֵּנִיתָא</span>. <span class=\"citation\">Gitt. 69ᵇ</span> (masc.!) <span dir=\"rtl\">ניתי ב׳ וכ׳</span> let him take fish and roast it in the smithy.—<span class=\"citation\">Bets. 28ᵃ</span> <span dir=\"rtl\">שב בֵּנִיתָא</span> (Var. <a href=\"#\" data-headword=\"בִּנְיָיתָא\">בִּינְיָיתָא</a> pl., <span dir=\"rtl\">נוניתא</span>, v. Rabb. D. S. a. l. note 9).</div><div class=\"sense\"><b>—2)</b>  name of a worm. <span class=\"citation\">Macc. 16ᵇ</span> <span dir=\"rtl\">ב׳ דבי כרבא</span> (Ms. M. <span dir=\"rtl\">מניתא</span>) a worm found between cabbage. [<span class=\"citation\">Sabb. 139ᵇ</span> <a href=\"#\" data-headword=\"ב׳\">ב׳</a> some ed., v. <a href=\"#\" data-headword=\"צִינְּיָיתָא\">צינייתא</a>.]</div><div class=\"sense\"><b>—3)</b> <i>hair;</i> v. <a href=\"#\" data-headword=\"בִּינְתָא II\"><span dir=\"rtl\">בִּינְתָא</span> II</a>.</div>","alt":[]},"4108":{"h":"*בִּינְכָא","r":"B00651","html":"<div class=\"sense\"> transp. of <span dir=\"rtl\">בִּיכְנָא</span> = <span dir=\"rtl\">בֵּי כַנָּא</span>, v. <a href=\"#\" data-headword=\"כַּנָּא\">כַּנָּא</a> a. <a href=\"#\" data-headword=\"*כַּנְהָא\"><a href=\"#\" data-headword=\"*כַּנְהָא\">כַּנְהָא</a>.</a> Cmp. Syr. <a href=\"#\" data-headword=\"בּוּכָנָא\">בוכנא</a> = <span dir=\"rtl\">בונכא</span> P. Sm. 465; 471.</div>","alt":[]},"4109":{"h":"*בינכי","r":"B00652","html":"<div class=\"sense\">, <span class=\"citation\">Y. Taan. III, 66ᶜ</span> bot., read <span dir=\"rtl\">בֵּינָנָא</span>(?).</div>","alt":[]},"4110":{"h":"בֵּינָת","r":"B00653","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּיִן\">בַּיִן</a>, <a href=\"#\" data-headword=\"בֵּין\"><a href=\"#\" data-headword=\"בֵּין\">בֵּין</a>.</a></div>","alt":["בֵּינַת"]},"4111":{"h":"בִּינָתָא","r":"B00654","html":"<div class=\"sense\"><i>understanding</i>, v. <a href=\"#\" data-headword=\"בִּינָא I\"><span dir=\"rtl\">בִּינָא</span> I</a>.</div>","alt":[]},"4112":{"h":"בִּינְתָא I","r":"B00655","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> collect. noun, or <a href=\"#\" data-headword=\"בִּינָתָא\">בִּינָתָא</a> pl. (v. <a href=\"#\" data-headword=\"בֵּינָת\">בֵּינָת</a>) <i>the inside part</i>, whence <i>the kernel</i> of seeds. <span class=\"citation\">B. Bath. 18ᵇ</span> bot. <span dir=\"rtl\">אי בב׳</span> as to the grains (of mustard). <span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">ניזדהר מב׳</span> let him guard against swallowing the seeds. <span class=\"citation\">Sabb. 67ᵃ</span> בִּינֵי כמונא Ms. M. (ed. <a href=\"#\" data-headword=\"בּוּנִי\">בוני</a>) cumin seeds.</div>","alt":[]},"4113":{"h":"בִּינְתָא II","r":"B00656","html":"<div class=\"sense\"> (בִּינִיתָא Ar. s. v. <span dir=\"rtl\">בין</span></div><div class=\"sense\"><b>2)</b>  f. (v. <a href=\"#\" data-headword=\"בִּינָא III\"><span dir=\"rtl\">בִּינָא</span> III</a>) <i>thread, a single hair</i>, (collect.) <i>hair</i>. <span class=\"citation\">Targ. Jud. XX, 16</span> <span dir=\"rtl\">בֵּינַת שערא</span>.—<span class=\"citation\">Sabb. 140ᵃ</span> <span dir=\"rtl\">מב׳ דראשי</span> from the hair of my head. <span class=\"citation\">Naz. 39ᵃ</span> <span dir=\"rtl\">עיקבא דב׳</span> the root of the hair, <span dir=\"rtl\">ריש׳ דב׳</span> the top of &amp;c.—<span class=\"citation\">Yoma 69ᵇ</span> <span dir=\"rtl\">אשתמיט ב׳ וכ׳</span> (Ms. M. <span dir=\"rtl\">בניתה</span>) a hair of his beard fell out. <span class=\"citation\">Ber. 8ᵃ</span> <span dir=\"rtl\">כמשחל ב׳ וכ׳</span> (ed. <span dir=\"rtl\">בניתא</span>) as easy as taking a hair out of the milk.—Pl. <a href=\"#\" data-headword=\"בִּינֵי\">בִּינֵי</a>. <span class=\"citation\">Sabb. 67ᵃ</span> seven cumin seeds (v. <a href=\"#\" data-headword=\"בִּינְתָא I\">preced.</a>) and <span dir=\"rtl\">ז׳ ב׳ מדיקנא</span> seven hairs from the beard.—<a href=\"#\" data-headword=\"בִּינָתָא\">בִּינָתָא</a>. <span class=\"citation\">Targ. Job IX, 17</span> <span dir=\"rtl\">חוטי ב׳</span> (h. text <a href=\"#\" data-headword=\"שַׂעֲרָה\">שְׂעָרָה</a>!).</div>","alt":[]},"4114":{"h":"בֵּינְתַּיִם","r":"B00657","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּיִן\">בַּיִן</a></div>","alt":[]},"4115":{"h":"בִּיסָא","r":"B00658","html":"<div class=\"sense\"> c. (= <span dir=\"rtl\">בֵּי עִיסָא</span>) <i>basin for kneading</i> the meat-offering. <span class=\"citation\">Men. 7ᵃ</span>; <span class=\"citation\">24ᵃ</span>; <span class=\"citation\">24ᵇ</span>. <span class=\"citation\">Ib. 57ᵇ</span> <span dir=\"rtl\">ב׳ למילש ביה</span> a basin in which to knead.</div>","alt":[]},"4116":{"h":"ביסא","r":"B00659","html":"<div class=\"sense\"> pr. n. m. <span class=\"citation\">Y. Gitt. IV, 46ᵃ</span> top, read <a href=\"#\" data-headword=\"נִיסָא\">נִיסָא</a>.</div>","alt":[]},"4117":{"h":"ביסי","r":"B00660","html":"<div class=\"sense\"><i>thorns</i> (Ar.), v. <a href=\"#\" data-headword=\"כֵּיסָא\">כֵּיסָא</a>.</div>","alt":[]},"4118":{"h":"*בִּיסַי","r":"B00661","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בּוּס\">בוס</a>, v. <a href=\"#\" data-headword=\"בְּסִיסַי\">בְּסִיסַי</a>) <i>tray for wine cups</i>. <span class=\"citation\">Lam. R. to III, 17</span> מן כל ב׳ וב׳ וכ׳ Ar. (ed. <a href=\"#\" data-headword=\"פַּטִּיס\">פטיס</a>) from each tray (which was handed around) one cup.</div>","alt":[]},"4119":{"h":"בִּיסֵּם","r":"B00662","html":"<div class=\"sense\"><i>Pi.</i> of <a href=\"#\" data-headword=\"בָּסֵם\">בָּסַם</a>. [Freq. incorr. for <a href=\"#\" data-headword=\"בָּסַס\">בִּיסֵּס</a>, v. <a href=\"#\" data-headword=\"בָּסַס\">בָּסַס</a>.]</div>","alt":[]},"4120":{"h":"בִּיסְמָן","r":"B00663","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּסְמָן\">בּוּסְמָן</a></div>","alt":[]},"4121":{"h":"בִּיסְנָא","r":"B00664","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Bisna.</i> <span class=\"citation\">Keth. 100ᵃ</span>; a. e. V. <a href=\"#\" data-headword=\"בִּינְזָא\">בינזא</a>.</div>","alt":[]},"4122":{"h":"בִּיסְתַּרְקָא","r":"B00665","html":"<div class=\"sense\"> c. (= <span dir=\"rtl\">בֵּי אִסְתַּרְקָא</span>, Ithpe. noun of <a href=\"#\" data-headword=\"סרק\">סרק</a>) <i>receptacle of hackled or hatcheled wool</i>, whence <i>mattress, cushion</i>. <span class=\"citation\">B. Kam. 117ᵃ</span> חד ב׳ Ms. R. (ed. <a href=\"#\" data-headword=\"חדא\">חדא</a> fem.).—<i>Pl</i>. <a href=\"#\" data-headword=\"בִּיסְתַּרְקָא\">בִּיסְתַּרְקֵי</a>, <a href=\"#\" data-headword=\"בִּיסְתַּרְקָא\">בִּסְ׳</a>. <span class=\"citation\">Targ. Y. Deut. XXXIV, 6</span> <span dir=\"rtl\">בב׳ מילת</span> (not <span dir=\"rtl\">כב׳</span>) with fine woolen mattresses.—B. Kam. l. c. <span class=\"citation\">Bekh. 8ᵇ</span>. <span class=\"citation\">Taan. 21ᵇ</span> bot. <span dir=\"rtl\">מאיך להו ב׳</span> Ar. (ed. <a href=\"#\" data-headword=\"מָךְ\">מך</a>) laid down before them mattresses (to sleep on). <span class=\"citation\">Yeb. 63ᵃ</span>. <span class=\"citation\">Snh. 95ᵃ</span>. <span class=\"citation\">B. Bath. 58ᵃ</span> (= <span dir=\"rtl\">חביתא דאודדא</span> in an enigma).</div>","alt":["בִּסְ׳"]},"4123":{"h":"בִּיעַ","r":"B00666","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>rejoicing;</i> v. <a href=\"#\" data-headword=\"בּוּעֲתָא II\"><span dir=\"rtl\">בּוּעֲתָא</span> II</a>. <span class=\"citation\">Targ. Is. XVI, 10</span>; a. e. (Var. <a href=\"#\" data-headword=\"בִּיעַ\">בְּיַע</a> incorr.).</div>","alt":[]},"4124":{"h":"בְּיָעָא","r":"B00667","html":"<div class=\"sense\">, part. f. of <a href=\"#\" data-headword=\"בּוּעַ\">בּוּעַ</a>.</div>","alt":["(בִּיעָא)"]},"4125":{"h":"בֵּיעָא","r":"B00668","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a>; <a href=\"#\" data-headword=\"בּוּעַ\">בוע</a>) <i>egg</i>. <span class=\"citation\">Targ. Job VI, 6</span>; a. fr.—<span class=\"citation\">Y. Ned. III, 38ᵃ</span> top (Y. Shebu. III, 34ᵈ bot. <span dir=\"rtl\">סגין</span>, corr. acc.) <span dir=\"rtl\">כגון ב׳ ומרגליתא</span> as e.g. one swearing of an egg that it was a pearl (as an instance of <span dir=\"rtl\">שבועת שקר</span>). <span class=\"citation\">Yoma 69ᵇ</span> <span dir=\"rtl\">ב׳ בת יומא</span> a fresh egg of the same day; a. fr.—Pl. <span dir=\"rtl\">בֵּיעִין</span>, <span dir=\"rtl\">בֵּיעַיָּא</span>, <span dir=\"rtl\">בֵּיעֵי</span>, <span dir=\"rtl\">בֵּע׳</span>. <span class=\"citation\">Targ. O. Deut. XXII, 6</span> (Y. <span dir=\"rtl\">ביעיין</span>); a. fr.—<span class=\"citation\">Keth. 61ᵃ</span> top. <span class=\"citation\">Bets. 6ᵇ</span> sq. <span dir=\"rtl\">ב׳ דפחיא</span> the eggs of a cackling hen, opp. those found in the killed hen. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ב׳ דדיכרא</span> eggs from a hen impregnated by a cock, opp. <span dir=\"rtl\">ב׳ דספנא מארעא</span> by friction on the ground. <span class=\"citation\">Ḥull. 93ᵃ</span> <span dir=\"rtl\">ב׳ חשילתא</span>, v. <a href=\"#\" data-headword=\"חֲשִׁילָא\">חֲשִׁילָא</a>. <span class=\"citation\">Sabb. 109ᵃ</span> <span dir=\"rtl\">פיעפועי ב׳</span> beaten eggs.—<span class=\"citation\">Lev. R. s. 16</span>; a. fr.—<span dir=\"rtl\">זבן בכל בֵּיעָתָא</span> to buy (the hen) with all the eggs, i.e. to do a thing thoroughly. <span class=\"citation\">Lev. R. s. 11</span>; Ruth R. (introd.) to I, 2; Esth. R. beg. <a href=\"#\" data-headword=\"בַּיְתָא\">ביתא</a> (corr. acc.); v. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a>.</div>","alt":["בֵּיעָה","בֵּיעֲתָא","בֵּעֲתָא"]},"4126":{"h":"בִּיעוּט","r":"B00669","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּעַט\">בעט</a>) <i>stamping, kick</i>. <span class=\"citation\">B. Kam. 19ᵃ</span>. [<span class=\"citation\">Targ. Is. LXIII, 3</span>, v. <a href=\"#\" data-headword=\"בְּעוֹט\">בְּעוֹט</a>.]</div>","alt":[]},"4127":{"h":"בִּיעוּר","r":"B00670","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּעַר I\">בער</a>) <i>removal.</i> <span class=\"citation\">Maas. Sh. V, 3</span>; <span class=\"citation\">Shebi. VII, 1</span>, a. fr. (removal of the fruits of the third and sixth years of the Sabbath period).—<span dir=\"rtl\">ב׳ חמץ</span>, v. <a href=\"#\" data-headword=\"בָּעַר\">בָּעַר</a> Pi.—Pl. <span dir=\"rtl\">בִּיעוּרִין</span>. <span class=\"citation\">Y. Ḥall. IV, 60ᵃ</span> bot. <span dir=\"rtl\">לב׳</span> as to laws of removal of fruits.</div>","alt":[]},"4128":{"h":"בִּיעוּרָא","r":"B00671","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"בִּיעוּר\">same</a>. <span class=\"citation\">Pes. 6ᵇ</span>.</div><div class=\"sense\"><b>—2)</b> <i>clearing, taking off the last olives</i>. <span class=\"citation\">Targ. Is. XVII, 6</span>; <span class=\"citation\">XXIV, 13</span> (h. <a href=\"#\" data-headword=\"נָקַף I\">נֹקֶף</a>).</div>","alt":[]},"4129":{"h":"בִּיעוּתָא","r":"B00672","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בִּיעֲתוּתָא\">בִּיעֲתוּתָא</a>) <i>fright</i>. <span class=\"citation\">Targ. Job VI, 4</span>; a, e.—Pl. <span dir=\"rtl\">בִּיעוּתִין</span>. <span class=\"citation\">Targ. Is. XXI, 4</span>; a. e.</div>","alt":[]},"4130":{"h":"בֵּיעֲתָא","r":"B00673","html":"<div class=\"sense\"><i>egg</i>, v. <a href=\"#\" data-headword=\"בֵּיעָא\">בֵּיעָא</a>.</div>","alt":["בִּיעֲתָא"]},"4131":{"h":"בִּיעֲתָא","r":"B00674","html":"<div class=\"sense\"><i>rejoicing</i>, v. <a href=\"#\" data-headword=\"בּוּעֲתָא II\"><span dir=\"rtl\">בּוּעֲתָא</span> II</a>. <span class=\"citation\">Targ. Ps. XXXII, 7</span>.</div>","alt":[]},"4132":{"h":"בִּיעֲתוּתָא","r":"B00675","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בעת</span>; = b. h. <span dir=\"rtl\">בְּעָתָה</span>) <i>fright</i>, v. <a href=\"#\" data-headword=\"בִּיעוּתָא\">בִּיעוּתָא</a>. <span class=\"citation\">Pes. 3ᵃ</span>; <span class=\"citation\">3ᵇ</span> <span dir=\"rtl\">ב׳ דגמלים</span> fear of falling down from the camel’s back; <span dir=\"rtl\">ב׳ דליליא</span> fear of the night. <span class=\"citation\">Sabb. 41ᵃ</span> <span dir=\"rtl\">ב׳ דנהרא</span> fear of being drowned. <span class=\"citation\">Gitt. 68ᵇ</span> <span dir=\"rtl\">הוה ליה ב׳ מיניה</span> he was afraid of him. <span class=\"citation\">Sot. 20ᵇ</span> fear (<a href=\"#\" data-headword=\"פַּחַד ²\">פחדא</a>) detains the blood (menstruation), <span dir=\"rtl\">ב׳ וכ׳</span> sudden fright loosens (produces menstruation). <span class=\"citation\">Nidd. 71ᵃ</span></div>","alt":[]},"4133":{"h":"*בִּיץ","r":"B00676","html":"<div class=\"sense\">, pl. <a href=\"#\" data-headword=\"בִּצִּים\">בִּיצִּים</a> Mus., v. <a href=\"#\" data-headword=\"נָצַץ\">הֵינֵץ</a>. Y. Kidd. I, 58ᵈ</div>","alt":[]},"4134":{"h":"בִּיצָּא","r":"B00677","html":"<div class=\"sense\"><i>, </i> pl. <a href=\"#\" data-headword=\"בִּיצִּית\">בִּיצִּין</a>, v. <a href=\"#\" data-headword=\"בִּצָּא\">בִּצָּא</a>.</div>","alt":[]},"4135":{"h":"בִּיצָּה","r":"B00678","html":"<div class=\"sense\"><i>swamp</i>, v. <a href=\"#\" data-headword=\"בִּצָּה\">בִּצָּה</a>.</div>","alt":[]},"4136":{"h":"בֵּיצָה","r":"B00679","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  [<i>the bubbling</i>,] <i>egg</i>. <span class=\"citation\">Bets. I, 1</span>; a. fr.—<span class=\"citation\">Sabb. VIII, 5</span> (<span class=\"citation\">80ᵇ</span>) <span dir=\"rtl\">ב׳ קלה</span> a light (easily boiling) egg.</div><div class=\"sense\"><b>—2)</b> <i>an egg-shaped object, ball, lump</i>. Ib. <span dir=\"rtl\">בֵּיצַת הגיר</span> Ar. (ed. <span dir=\"rtl\">הסיד</span>) cement (lime) in a lump; Tosef. ib. VIII (IX), 20 <span dir=\"rtl\">בזמן שביצה</span>, Var. <span dir=\"rtl\">שהיא כביצה</span>, when it is as compact as a ball, opp. <span dir=\"rtl\">חבוט</span>.—<span class=\"citation\">Par. V, 6</span>; <span class=\"citation\">Lev. R. s. 23</span>, end <span dir=\"rtl\">ביצת היוצרים</span> the potter’s lump of clay.</div><div class=\"sense\"><b>—3)</b>  trnsf. <i>germ, root</i>, esp. <span dir=\"rtl\">קעקע ב׳</span> to stamp out, <i>to exterminate</i> (the last germ). Y. Ab. Zar. IV, 44ᵃ top. <span class=\"citation\">Lev. R. s. 26</span>. <span class=\"citation\">Lev. R. s. 11</span>; Ruth R. (introd.) to I, 2; Esth. R. beg.; v. <a href=\"#\" data-headword=\"בֵּיעָא\">בֵּיעָא</a> pl.</div><div class=\"sense\"><b>—4)</b> <i>Betsah</i>, name of a Talmudic treatise, beginning with that word (in Tosefta <span dir=\"rtl\">יום טוב</span>).—Pl. <a href=\"#\" data-headword=\"בֵּצִים\">בֵּיצִים</a>, <a href=\"#\" data-headword=\"בֵּצִים\">בֵּצִים</a>, constr. <span dir=\"rtl\">בֵּיצֵי</span>. <span class=\"citation\">Sabb. VIII, 5</span>; a. fr.—<span class=\"citation\">Ab. Zar. 3ᵇ</span>; a. e. <span dir=\"rtl\">ביצי כנים</span>, v. <a href=\"#\" data-headword=\"כִּינָּה\">כִּינָּה</a>.—<span class=\"citation\">Y. Snh. XI, 30ᵇ</span> bot., [read as] <span class=\"citation\">Cant. R. to II, 5</span> <span dir=\"rtl\">פתפותי בצים הם כאן</span> scrambled eggs are here, i.e. confusion of persons. <span class=\"citation\">Y. Shebi. V, 35ᵈ</span> bot. <span dir=\"rtl\">עשה ביצים</span> a. <span dir=\"rtl\">עשה ביצה</span> if the leek has formed bulbs. Ib. VII, 37ᵇ bot. <span dir=\"rtl\">ביצי נץ חלב</span>, v. <a href=\"#\" data-headword=\"חַלְבֵּצִין\">חַלְבֵּצִין</a>.</div>","alt":[]},"4137":{"h":"בִּיצּוּעַ","r":"B00680","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּצַע\">בָּצַע</a>) <i>adjustment, compromise</i> (usually <a href=\"#\" data-headword=\"פְּשָׁרָה\">פְּשָׁרָה</a>). <span class=\"citation\">Snh. 6ᵃ</span>. Y. ib. I, 18ᵇ; a. e.—[Pl. <span dir=\"rtl\">בִּיצּוּעִין</span>, v. <a href=\"#\" data-headword=\"בִּצְעָה\">בִּצְעָה</a>.]</div>","alt":[]},"4138":{"h":"בִּיצּוּעָא","r":"B00681","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּצַע\">בְּצַע</a>) <i>piece, morsel, crumb.</i> <i>—</i> Pl. <span dir=\"rtl\">בִּיצּוּעִין</span>, <a href=\"#\" data-headword=\"בִּיצּוּעַ\">בִּיצּוּעֵי</a>, <a href=\"#\" data-headword=\"בִּיצְעֵי\">בִּיצְעֵי</a>. <span class=\"citation\">Targ. O. Lev. II, 6</span>; a. e.—<span class=\"citation\">Sabb. 140ᵇ</span> <span dir=\"rtl\">לא ליבצע ב׳</span> he must not eat it by morsels (but enough at a time). <span class=\"citation\">Succ. 26ᵃ</span> תרתי או תלת ביצעי Ms. M. (ed. <span dir=\"rtl\">ביעי</span>, v. Rashi a. l.) two or three morsels.</div>","alt":["בִּיצְעָא"]},"4139":{"h":"בִּיצּוּר","r":"B00682","html":"<div class=\"sense\"> (בָּצַר Pi.) <i>besieging</i>, trnsf. (by play on <a href=\"#\" data-headword=\"בְּצַר\">בַּצַּר</a> <span class=\"citation\">Ps. XVIII, 7</span>) <i>beseeching, entreaty</i>. <span class=\"citation\">Deut. R. s. 2</span>, beg. (in <span class=\"citation\">Yalk. Sam. 157</span> our w. omitted; <span class=\"citation\">Yalk. Deut. 811</span> <span dir=\"rtl\">בצר</span>).</div>","alt":[]},"4140":{"h":"בִּיצּוּרְתָּא","r":"B00683","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּיצּוּרְתָּא\">בַּצּוּרְתָּא</a> a. <a href=\"#\" data-headword=\"בְּצוּרְתָא\"><a href=\"#\" data-headword=\"בְּצוּרְתָא\">בְּצוֹרְתָא</a>.</a></div>","alt":[]},"4141":{"h":"בִּיצְיָאתָא","r":"B00684","html":"<div class=\"sense\"> pl. of <a href=\"#\" data-headword=\"בִּיצִּיתָא\">בִּיצִּיתָא</a>.</div>","alt":[]},"4142":{"h":"*בִּיצִירְתָּא","r":"B00685","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> of <a href=\"#\" data-headword=\"בְּצִיר\">בְּצִיר</a>, <i>the lowest</i>. <span class=\"citation\">Targ. Y. Ex. XI, 5</span>.</div>","alt":[]},"4143":{"h":"בִּיצִּית","r":"B00686","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בִּצָּה\">בִּצָּה</a>) <i>dyke-boat, lighting boat</i>, Babylonian name for Palestinean <a href=\"#\" data-headword=\"דּוּגִית\">דּוּגִית</a>. <span class=\"citation\">B. Bath. 73ᵃ</span>; <span class=\"citation\">Tosef. ib. IV, 1</span> <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בּוּ׳</a>; Y. ib. V, beg. 15ᵃ <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בו׳</a> (v. Rabb. D. S. to B. Bath. l. c., note 5).</div>","alt":["בּוּצִית"]},"4144":{"h":"בִּיצִּיתָא","r":"B00687","html":"<div class=\"sense\"> . <span class=\"citation\">B. Bath. 73ᵃ</span> ed. <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בו׳</a> (Ms. M. <a href=\"#\" data-headword=\"בִּרְיְתָא\">בי׳</a>, Ar. <span dir=\"rtl\">בוצייתא</span>); <span class=\"citation\">Sabb. 101ᵃ</span> <span dir=\"rtl\">בי׳ דמישן</span> the canal boats of Meshan.</div>","alt":["בּוּצִיתָא"]},"4145":{"h":"בִּיצְעָא","r":"B00688","html":"<div class=\"sense\">, pl. <a href=\"#\" data-headword=\"בִּיצְעֵי\">בִּיצְעֵי</a> <i>morsels</i>, v. <a href=\"#\" data-headword=\"בִּיצּוּעָא\">בִּיצּוּעָא</a>.</div>","alt":[]},"4146":{"h":"בִּיצְעֵי","r":"B00689","html":"<div class=\"sense\"><i>ditches</i>, v. <a href=\"#\" data-headword=\"בִּצְעָה\">בִּצְעָה</a>.</div>","alt":["בִּיצְעִין"]},"4147":{"h":"בִּיצַרְתָּא","r":"B00690","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בַּצּוֹרְתָא</a></div>","alt":[]},"4148":{"h":"*בִּיקָא","r":"B00691","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בקק</span>) <i>incisions in muddy ground</i>. <span class=\"citation\">Sabb. 147ᵃ</span> bot. Ar. s. v. <span dir=\"rtl\">פלם</span> (Ms. O. <a href=\"#\" data-headword=\"בּוּקָא\">בוקא</a>, ed. <a href=\"#\" data-headword=\"פִּיקָא\">פיקא</a>), v. <a href=\"#\" data-headword=\"*פִּילוֹמָא\">פילומא</a>.</div>","alt":[]},"4149":{"h":"בִּיקּוּעַ","r":"B00692","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בקע</span>) </div><div class=\"sense\"><b>1)</b> <i>splitting, chopping.</i> <span class=\"citation\">Kel. XIII, 3</span> <a href=\"#\" data-headword=\"בַּלְתִּי\">בית ב׳</a> that part of the spade (or shovel) which is used for chopping. <span class=\"citation\">Ib. XXIX, 7</span>; <span class=\"citation\">Y. Meg. I, 71ᵇ</span> top <span dir=\"rtl\">קרדום של ב׳</span> an axe for chopping, opp. <span dir=\"rtl\">של ניכוש</span> (a hoe) for weeding; <span class=\"citation\">Y. Ned. IV, beg. 38ᶜ</span> <span dir=\"rtl\">קורדום של בקעי</span> (corr. acc.).</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"בָּקַע\">בָּקַע</a>) <i>trimming the</i> (olive) <i>tree</i>. Sifra B’har, beg.</div>","alt":["בִּקּוּעַ"]},"4150":{"h":"בִּיקּוּר","r":"B00693","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּקַר\">בָּקַר</a>) </div><div class=\"sense\"><b>1)</b> <i>examination, investigation</i>. <span class=\"citation\">Pes. 96ᵃ</span>; <span class=\"citation\">Arakh. 13ᵇ</span>; <span class=\"citation\">Men. 49ᵇ</span> <span dir=\"rtl\">טעון ב׳</span> requires examination (as to physical defects). <span class=\"citation\">Ḥull. II, 3</span> (<span class=\"citation\">32ᵃ</span>) <span dir=\"rtl\">כדי ב׳</span> as much time as the examination (of the slaughtering knife) requires; ib. 9ᵃ; [ib. 32ᵃ <span dir=\"rtl\">ביקרו של חכם</span>, read <span dir=\"rtl\">ביקור חכם</span> or <span dir=\"rtl\">בִּיקּוּרוֹ של</span>]. <span class=\"citation\">Kerith. 11ᵃ</span> (ref. to <a href=\"#\" data-headword=\"בַּקְרַת\">בִּקֹּרֶת</a> <span class=\"citation\">Lev. XIX, 20</span>) <span dir=\"rtl\">בב׳ תהיה</span> she must first be examined (whether she can endure the punishment required by law).</div><div class=\"sense\"><b>—2)</b> <i>visiting</i> (the sick), <i>visit</i>. <span class=\"citation\">Ned. 39ᵇ</span> <span dir=\"rtl\">ב׳ חולים אין וכ׳</span> the duty of visiting the sick knows no limits (of time or rank). <span class=\"citation\">B. Mets. 30ᵇ</span>; a. fr.</div>","alt":[]},"4151":{"h":"בִּיקּוֹרֶת","r":"B00694","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"בִּיקּוּר\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>examination, assessment</i>. <span dir=\"rtl\">אגרת ב׳</span> a public announcement inviting buyers to examine the property assessed, i.e. <i>an announcement of public sale</i> = <a href=\"#\" data-headword=\"אַכְרָזָה\">אַכְרָזָה</a>. <span class=\"citation\">Keth. XI, 5</span> (<span class=\"citation\">99ᵇ</span>); a. fr.—V. <a href=\"#\" data-headword=\"אִגֶּרֶת\">אִגֶּרֶת</a>.</div><div class=\"sense\"><b>—2)</b> (b. h. <i>punishment</i>). <span class=\"citation\">Kerith. 11ᵃ</span> (ref. to <span class=\"citation\">Lev. XIX, 20</span>) <span dir=\"rtl\">ב׳ תהיה מלמד שהיא לוקה</span> there shall be <i>bikkoreth</i>, this teaches that she shall be lashed. <span dir=\"rtl\">ומיניין דהדין ב׳ לישנא וכ׳</span> how do we know that this bikkoreth has the sense of chastisement? Answ. <span dir=\"rtl\">תהא בקריאה …</span> Rashi (ed. <span dir=\"rtl\">בקראי</span>) she shall have the Bible verses read to her (as customary when chastising in court, v. <span class=\"citation\">Macc. III, 14</span>); oth. homilet. interpret. <span dir=\"rtl\">בביקור תהא</span>, v. <a href=\"#\" data-headword=\"בִּיקּוּר\">preced.</a> [<span class=\"citation\">Tosef. M. Kat. II, 11</span> <a href=\"#\" data-headword=\"בִּיקּוֹרֶת\">ביקורת</a> ed. Zuck., v. <a href=\"#\" data-headword=\"בַּקְרוּת\">בַּקְרוּת</a>.]</div>","alt":["בִּקּ׳"]},"4152":{"h":"בִּיקְיָא","r":"B00695","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (vicia, βίκιον) <i>vetch</i>. <span class=\"citation\">Y. Maasr. V, end, 52ᵃ</span>. <span class=\"citation\">Tosef. ib. III</span>, end <a href=\"#\" data-headword=\"בִּקְיָא\">בִּקְיָא</a>. Y. Ḥall. IV, 60ᵇ <a href=\"#\" data-headword=\"בִּקְיָא\">בִּקְיָיה</a>.</div>","alt":[]},"4153":{"h":"ביקעי","r":"B00696","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ned. IV, beg. 38ᶜ</span>, v. <a href=\"#\" data-headword=\"בִּיקּוּעַ\">בִּיקּוּעַ</a></div>","alt":[]},"4154":{"h":"ביקרא","r":"B00697","html":"<div class=\"sense\">, <span class=\"citation\">Ab. Zar. 28ᵇ</span>, v. <a href=\"#\" data-headword=\"בַּרְקָא II\"><span dir=\"rtl\">בַּרְקָא</span> II</a></div>","alt":[]},"4155":{"h":"בִּיקְתָא","r":"B00698","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּקְתָא\">בִּקְתָא</a></div>","alt":[]},"4156":{"h":"בִּיר","r":"B00699","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"בַּר\">בַּר</a>) <i>son</i>. <span class=\"citation\">Targ. Y. Ex. I, 15</span>; a. e—<span class=\"citation\">Ber. 5ᵇ</span>; <span class=\"citation\">B. Bath. 116ᵃ</span> this is the bone (tooth) <span dir=\"rtl\">דעשיראה ב׳</span> of the tenth son (that died).—Pl. constr. <span dir=\"rtl\">בִּירֵי</span>. <span class=\"citation\">Targ. Y. Num. XXXIII, 31</span> sq. <span dir=\"rtl\">ב׳ עקתא</span> (h. text. <span dir=\"rtl\">בני יעקן</span>!).</div>","alt":[]},"4157":{"h":"בֵּיר","r":"B00700","html":"<div class=\"sense\"> c. ch. </div><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"בְּאֵר\">בְּאֵר</a>. <span class=\"citation\">Targ. Gen. XVI, 14</span>; a. e. <span class=\"citation\">Ber. 56ᵃ</span>. <span dir=\"rtl\">מיבעי עסקך כי הני מידי דנפל לב׳</span> Ms. M., thy goods will be sought for like something fallen into a well (i.e. thy business will thrive; diff. vers. in ed. a. Mss., v. Rabb. D. S. a. l. note). <span class=\"citation\">Sabb. 66ᵇ</span> נפל פותא לב׳ Dyer’s Madder, as a remedy, has fallen into the pit (is not practiced). <span class=\"citation\">B. Kam. 92ᵇ</span> (prov.) <span dir=\"rtl\">ב׳ דשתית וכ׳</span> cast no stone into a well out of which thou once didst drink (never despise what once benefitted you).—<span class=\"citation\">Ḥull. 106ᵃ</span> <span dir=\"rtl\">בַּת בֵּירְתָא</span> a little gutter fed by a well.—Pl. <a href=\"#\" data-headword=\"בֵּירִית\">בֵּירִין</a>, <a href=\"#\" data-headword=\"בֵּירַי\">בֵּירֵי</a>. <span class=\"citation\">Targ. Gen. XXVI, 15</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  (= h. <a href=\"#\" data-headword=\"בּוּר\">בּוֹר</a>) <i>pit, hole</i>. <span class=\"citation\">B. Mets. 85ᵃ</span> <span dir=\"rtl\">ב׳ מליא וכ׳ …</span> the cavity (created by the taking out of a radish) stood full of water; [Ms. M. <span dir=\"rtl\">כי ב׳ דמיא</span> like a well; v. Rabb. D. S. a. l. note].—Pl. as above. <span class=\"citation\">Targ. Gen. XIV, 10</span> (h. text <span dir=\"rtl\">בֶּאֱרוֹת</span>); <span class=\"citation\">Gen. R. s. 42</span>.—<span class=\"citation\">Snh. 7ᵃ</span> (prov.) <span dir=\"rtl\">שב ב׳ וכ׳</span> seven pits are open for the righteous man (and he escapes), and one for the evil-doer (into which he falls). <span class=\"citation\">Sabb. 110ᵇ</span></div><div class=\"sense\"><b>—3)</b>  <a href=\"#\" data-headword=\"בֵּיר\">בֵּירָא</a> pr. n. pl. <i>Bera</i> (prob. ident. with <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a> 2, a), native place of R. Simlai. <span class=\"citation\">Y. Taan. II, 65ᵈ</span> bot. <span dir=\"rtl\">ר׳ ש׳ דיב׳</span>; <span class=\"citation\">Y. Meg. I, 72ᶜ</span> bot. <span dir=\"rtl\">דב׳</span>; <span class=\"citation\">Koh. R. to III, 14</span> <span dir=\"rtl\">דברויירא</span> (corr. acc.).</div>","alt":["בֵּירָא"]},"4158":{"h":"בֵּירָאָה","r":"B00701","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בֵּירַאי\">next w.</a>) <i>of Berai</i>, surname of Ulla. <span class=\"citation\">M. Kat. 26ᵃ</span>; a. fr.—<span class=\"citation\">Y. Meg. II, 73ᵇ</span>; <span class=\"citation\">Y. M. Kat. III, 83ᵇ</span> bot. <a href=\"#\" data-headword=\"בִּירְיָא I\">בֵּירָיָא</a>.</div>","alt":["בֵּירָיָיה"]},"4159":{"h":"בֵּירַאי","r":"B00702","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <span dir=\"rtl\">בַּיִר</span>, <a href=\"#\" data-headword=\"בְּאֵר\">בְּאֵר</a>) </div><div class=\"sense\"><b>1)</b> <i>watering station</i>, esp. in Palestine for Temple pilgrims.—Pl. <span dir=\"rtl\">בֵּירָאוֹת</span>, <span dir=\"rtl\">בֵּירָייוֹת</span>, <span dir=\"rtl\">בֵּירָיוֹת</span>. <span class=\"citation\">Erub. II, 1</span>; a. fr. Y. ib. 20ᵇ top <span dir=\"rtl\">לביריי׳ ולא לבירות</span> (read <span dir=\"rtl\">לבירייות ולא לבורות</span>) for watering stations but not for cisterns; v. Bab. <span class=\"citation\">ib. 18ᵃ</span></div><div class=\"sense\"><b>—2)</b>  pr. n. pl. <i>Berai</i> or <i>Beri;</i> a) in Galilee. <span class=\"citation\">Yeb. 83ᵇ</span>. <span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">בני בירי</span> the inhabitants of B. (Ms. M. <span dir=\"rtl\">בני בר מריון</span>). <span class=\"citation\">Y. Pes. IV, 30ᵈ</span> top. <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> top <span dir=\"rtl\">ביריי רבתא</span> (a border-town); (v., however, Hildesh. Beitr. z. Geogr. p. 21).—b) <i>B</i>. or <i>Be-B</i>. in Babylon, native place of Ulla, R. Dostai, a. oth. <span class=\"citation\">Ab. Zar. 40ᵃ</span>. <span class=\"citation\">Erub. 56ᵃ</span> <span dir=\"rtl\">מולייתא דבי ב׳ וכ׳</span> the ascents between Berai a. Narash. <span class=\"citation\">Sot. 10ᵃ</span> <span dir=\"rtl\">בי בארי</span>. <span class=\"citation\">Erub. 45ᵃ</span> <span dir=\"rtl\">בירי</span>. [<span class=\"citation\">Ḥull. 127ᵃ</span> <span dir=\"rtl\">ביברי דנרש</span>, read <span dir=\"rtl\">בי בירי ונרש</span>.]</div>","alt":["בֵּירַיי","בֵּירַי"]},"4160":{"h":"בירבלין","r":"B00703","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"כּוֹרַבְלִין\">כּוֹרַבְלִין</a>.</div>","alt":[]},"4161":{"h":"בִּירָה","r":"B00704","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>cut off, surrounded</i>, whence </div><div class=\"sense\"><b>1)</b> <i>castle, fort</i>. <span class=\"citation\">Gen. R. s. 39</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>a group of buildings forming one residence</i>. <span class=\"citation\">B. Bath. 61ᵇ</span> <span dir=\"rtl\">בית בב׳ גדולה</span> a house in a large residence (court). <span class=\"citation\">Bets. 25ᵃ</span> <span dir=\"rtl\">בטפיחין ובב׳</span>; (ib. 24ᵃ <span dir=\"rtl\">בט׳ בבירות</span>); v. <a href=\"#\" data-headword=\"טְפִיחַ I\"><span dir=\"rtl\">טפיח</span> I</a>, 2.</div><div class=\"sense\"><b>—3)</b>  (= <span dir=\"rtl\">בית הבחירה</span>, <span class=\"citation\">I Chr. XXIX, 1</span>; <span class=\"citation\">19</span>) <i>the chosen Divine residence, Temple</i>. <span class=\"citation\">Zeb. 119ᵃ</span> <span dir=\"rtl\">והא בעי ב׳</span> does it not require a chosen residence (<span class=\"citation\">Deut. XII, 18</span>)? Y. Pes. II, 35ᵃ top <span dir=\"rtl\">כל הר וכ׳</span> the whole Temple mount is named Birah; <span class=\"citation\">Pesik. R. s. 14</span>. <span class=\"citation\">Zeb. XII, 5</span> (<span class=\"citation\">104ᵇ</span>) <span dir=\"rtl\">בבית הב׳</span>; v. Ib. a. l.—<span class=\"citation\">Yoma 9ᵇ</span> <span dir=\"rtl\">עידיכם הב׳</span> your witness is the Second Temple (which has not been rebuilt; Y. ib. I, 38ᶜ bot. <span dir=\"rtl\">הבחירה</span>). <span class=\"citation\">Eduy. VII, 3</span> <span dir=\"rtl\">בִּירַת הפליא</span> (Ms. M. <span dir=\"rtl\">הפליי׳</span>) Fort Haflaya(?).—Pl. <span dir=\"rtl\">בִּירוֹת</span>. <span class=\"citation\">Bets. 24ᵃ</span>, v. supra. <span class=\"citation\">Zeb. 119ᵃ</span> <span dir=\"rtl\">שלש ב׳ וכ׳</span> there are three Divine residences, Shiloh &amp;c. Ch. <a href=\"#\" data-headword=\"בֵּירְתָא\">בִּירְתָא</a>.—Denom. <a href=\"#\" data-headword=\"בִּרְיוֹן\">בִּרְיוֹן</a>.</div>","alt":[]},"4162":{"h":"בירן","r":"B00705","html":"<div class=\"sense\">, <span class=\"citation\">Y. Pes. IV, 30ᵈ</span> top, read <a href=\"#\" data-headword=\"בֵּירַי\">בֵּירַי</a>, v. <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a></div>","alt":[]},"4163":{"h":"בִּירוָון","r":"B00706","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><i>cypress trees;</i> sing. <a href=\"#\" data-headword=\"בְּרוֹתָא\">בְּרוֹתָא</a>, v. <a href=\"#\" data-headword=\"בְּרָתָא\">בְּרָתָא</a>.</div>","alt":["בִּרְוָן"]},"4164":{"h":"בֵּירוּלִין","r":"B00707","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (βηρύλλιον) <i>beryll</i>, a precious stone. <span class=\"citation\">Targ. Job XXVIII, 16</span>. <span class=\"citation\">Ib. 18</span> (some ed. <a href=\"#\" data-headword=\"*בִּירוּצִין\">בִּירוּצִין</a> q. v., Ms. Var. <a href=\"#\" data-headword=\"פִּירוּצִין\">פִּירוּצִין</a>). <span class=\"citation\">Targ. Y. II, Ex. XXVIII, 19</span> <a href=\"#\" data-headword=\"בירזלין\">בירזלין</a> (corr. acc.). V. <a href=\"#\" data-headword=\"בִּירְלָא\">בִּירְלָא</a>.</div>","alt":[]},"4165":{"h":"בִּירוֹס","r":"B00708","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (birrus, βίρρος) <i>birrus</i>, a travelling cloak, v. <a href=\"#\" data-headword=\"בִּרְסִין\">בִּרְסִין</a>. Tosef. Meg. IV (III), 30 <a href=\"#\" data-headword=\"כידום\">כידום</a>, <a href=\"#\" data-headword=\"כידוס\">כידוס</a> (corr. acc.).</div>","alt":[]},"4166":{"h":"בֵּירוּץ","r":"B00709","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ברץ</span>) <i>heaping, crowding.</i> Pl. <span dir=\"rtl\">בֵּירוּצִים</span>, <a href=\"#\" data-headword=\"*בִּירוּצִין\">בֵּירוּצִין</a>, <span dir=\"rtl\">בֵּר׳</span>. <span class=\"citation\">Men. 88ᵃ</span> <a href=\"#\" data-headword=\"ב׳\">ב׳</a> or <span dir=\"rtl\">בֵּירוּצֵי המדות</span> the quantities which remain, when filling from a brimful measure into smaller ones. <span class=\"citation\">Y. Shek. IV, 48ᵃ</span> bot. <span dir=\"rtl\">לב׳</span> goes to the collection of &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בירוצי לח</span> the remnants of the overflow of liquids, <span dir=\"rtl\">ב׳יבש</span> those of dry things emptied over.</div>","alt":["בֵּרוּץ"]},"4167":{"h":"*בִּירוּצִין","r":"B00710","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(Æthiop. <span dir=\"rtl\">אבן ברד</span>, v. Ges. H. Dict. s. v. <a href=\"#\" data-headword=\"גָּדוּשׁ\">גָּבִישׁ</a>) <i>chrystal</i>. <span class=\"citation\">Targ. Job XXVIII, 18</span>; v. <a href=\"#\" data-headword=\"בֵּירוּלִין\">בֵּירוּלִין</a>.</div>","alt":[]},"4168":{"h":"בֵּירוּר","r":"B00711","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ברר</span>) </div><div class=\"sense\"><b>1)</b> <i>clearness, correct sense</i>. <span class=\"citation\">Yalk. Ps. 658</span> <span dir=\"rtl\">ב׳ של הלכה</span> (cmp. <a href=\"#\" data-headword=\"בּוֹרִי\">בּוֹרִי</a>) the true sense of the law.</div><div class=\"sense\"><b>—2)</b> Pl. <a href=\"#\" data-headword=\"בֵּירוּלִין\">בֵּירוּרִין</a>, <span dir=\"rtl\">בֵּר׳</span> <i>arbitration</i>. <span class=\"citation\">B. Mets. I, 8</span>, a. e. <span dir=\"rtl\">שטרי ב׳</span> documents referring to the choice of arbiters, v. <a href=\"#\" data-headword=\"קוֹמְפְּרוֹמִיסִין\">קוֹמְפְּרוֹמִיסִין</a>; [anoth. opin. <span class=\"citation\">ib. 20ᵃ</span> <span dir=\"rtl\">שטרי טענתא</span> records of evidences, minutes of court proceedings].</div><div class=\"sense\"><b>—3)</b>  בֵּרוּרֵי המדות <i>exact account of wine measures</i>, whence, <i>the surplus in the shopkeeper’s wine account</i> arising from measuring quickly and not allowing the wine to settle in the measures. <span class=\"citation\">Bets. III, 8</span> (<span class=\"citation\">29ᵃ</span>) ed. (properly omitted in Ms. M., v. Rashi a. l.; Var. in Rashi Ms. <span dir=\"rtl\">בֵּרוּצֵי</span>). Ib. 29ᵃ three hundred <i>gereb</i> (v. <a href=\"#\" data-headword=\"גָּרָב I\">גרב</a>) of wine <span dir=\"rtl\">מב׳ המ׳</span> from the surplus found in his account.</div>","alt":["בֵּרוּר"]},"4169":{"h":"בירזלין","r":"B00712","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּירוּלִין\">בֵּירוּלִין</a></div>","alt":[]},"4170":{"h":"בֵּירַי","r":"B00713","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a>—[<span dir=\"rtl\">בירי</span>, <span class=\"citation\">Ḥull. 139ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּירִי I\"><span dir=\"rtl\">כִּירִי</span> I</a>.]</div>","alt":[]},"4171":{"h":"בִּירְיָא I","r":"B00714","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"בִּרְיְתָא\">בִּרְיְתָא</a> a. <a href=\"#\" data-headword=\"בִּירְיָה\"><a href=\"#\" data-headword=\"בִּירְיָה\">בִּירְיָה</a>.</a></div>","alt":[]},"4172":{"h":"בִּירְיָא II","r":"B00715","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (βίῤῥια, pl. of βίῤῥιον) <i>birrus</i>, a kind of cloak, v. <a href=\"#\" data-headword=\"בִּרְסִין\">בִּרְסִין</a>. <span class=\"citation\">Y. Kil. IX, 32ᵈ</span> top quoted in R. S. to <span class=\"citation\">Kil. IX, 7</span> (ed. <a href=\"#\" data-headword=\"*בריה\">בריה</a>, corr. acc.).</div>","alt":[]},"4173":{"h":"ביריאתא","r":"B00716","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּרִירוּתָא\">בְּרִירוּתָא</a></div>","alt":[]},"4174":{"h":"בִּירְיָה","r":"B00717","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>creature</i>, v. <a href=\"#\" data-headword=\"בִּרְיָה\">בִּרְיָה</a>.</div>","alt":["בִּירְיָא"]},"4175":{"h":"בִּירְיוֹן","r":"B00718","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>palace-guard</i>, v. <span dir=\"rtl\">בִּרְ׳</span>.</div>","alt":["בִּירְיוֹנָא"]},"4176":{"h":"בֵּירַיי","r":"B00719","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a></div>","alt":[]},"4177":{"h":"בִּירְיִי","r":"B00720","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Biryi</i>, an Amora. <span class=\"citation\">Y. Ter. X, 47ᵇ</span> bot. (<span class=\"citation\">Ḥull. 98ᵃ</span> <a href=\"#\" data-headword=\"בִּירְיָים\">ביריים</a>). <span class=\"citation\">Y. Pes. II, end, 29ᶜ</span> (Asheri to <span class=\"citation\">Pes. I</span>I, s. 13, quotes <span dir=\"rtl\">פדאי</span>).</div>","alt":[]},"4178":{"h":"בֵּירָיָיה","r":"B00721","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּירָאָה\">בֵּירָאָה</a></div>","alt":[]},"4179":{"h":"בִּירְיָים","r":"B00722","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּירְיִי\">בִּירְיִי</a></div>","alt":[]},"4180":{"h":"בירייתכון","r":"B00723","html":"<div class=\"sense\">, <span class=\"citation\">Y. Snh. II, 20ᵃ</span> top, read <span dir=\"rtl\">בּוֹרְיֵיכוֹן</span>, v. <a href=\"#\" data-headword=\"בָּרְיָיא\">בָּרְיָיא</a></div>","alt":[]},"4181":{"h":"בֵּירֵישָׁא","r":"B00724","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Beresha</i> (prob. Baris), in the territory of Ruben. <span class=\"citation\">Targ. Y. Num. XXXII, 37</span> (h. text <span dir=\"rtl\">קריתים</span>).</div>","alt":[]},"4182":{"h":"בֵּירִית","r":"B00725","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּרָה\">בָּרָה</a>, cmp. <a href=\"#\" data-headword=\"בְּרִית\">בְּרִית</a>) <i>something cut out; ring, hoop</i>. <span class=\"citation\">Tosef. Kel. B. Mets. V, 7</span> <span dir=\"rtl\">כל הבורית טהורה בֵּרִית מחרישה טמאה</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"בֵּירִית\">בירית</a>, <a href=\"#\" data-headword=\"בּוֹרוּת\">בורות</a>) every thing cut in circular form is clean (not susceptible of levitical uncleanness), except the hoop of the plough (cmp. <a href=\"#\" data-headword=\"חֲתִיכָה\">חתיכה</a> ibid.).—Esp. <i>knee-band, garter</i>. <span class=\"citation\">Sabb. VI, 4</span>. <span class=\"citation\">Ib. 63ᵇ</span> <a href=\"#\" data-headword=\"ב׳\">ב׳</a> of the Mishnah is the Biblical <a href=\"#\" data-headword=\"אֶצְעָדָה\">אצעדה</a>. Y. ib. VI, 8ᵇ <span dir=\"rtl\">בי׳ כל שהיא וכ׳</span> it is called <i>birith</i> when single, <i>k’balim</i>, when the two bands are coupled with a chain. [Ar. ed. Koh. <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בו׳</a>, oth. ed. <a href=\"#\" data-headword=\"בֵּרִית\">בֵּרִית</a>. Cmp. Assyr. <i>birîtu</i> chain, Schr. KAT 542.]</div>","alt":["בּוּרִית"]},"4183":{"h":"בִּירְכָא","r":"B00726","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּרְכָא\">בִּרְכָא</a>, <a href=\"#\" data-headword=\"בִּירְכָא\"><a href=\"#\" data-headword=\"בִּירְכָא\">בִּרְכְּתָא</a>.</a></div>","alt":["בִּירְכְּתָא"]},"4184":{"h":"בִּירְכָּא","r":"B00727","html":"<div class=\"sense\"><i>knee, shoot</i>, v. <a href=\"#\" data-headword=\"בֶּרֶךְ\">בֶּרֶךְ</a>.</div>","alt":[]},"4185":{"h":"בִּירְלָא","r":"B00728","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (βήρυλλος) <i>beryll</i>, a precious stone, prob. the <i>Chrysoberyll</i> or <i>yellow emerald</i> (h. <span dir=\"rtl\">שֹׁהַם</span>). <span class=\"citation\">Targ. O. Ex. XXVIII, 9</span>; <span class=\"citation\">20</span>; a. e.—<span class=\"citation\">Targ. Cant. V, 14</span> (some ed. <a href=\"#\" data-headword=\"בִּירְלָא\">בִּרְלָא</a>).—Pl. <a href=\"#\" data-headword=\"בּוּרְנִין\">בּוּרְלִין</a>. <span class=\"citation\">Targ. Esth. I, 4</span>.—V. <a href=\"#\" data-headword=\"בֵּירוּלִין\">בֵּירוּלִין</a>.—<span class=\"citation\">Targ. Y. Ex. XXXIX, 13</span> <span dir=\"rtl\">בּוּרְלַת חַלָּא</span> sand-colored beryll. Ib. (I) XXVIII, 20 <span dir=\"rtl\">ובירליות חלא</span>, prob. to be read <span dir=\"rtl\">בירולין דחלא</span>; Ib. (II) <a href=\"#\" data-headword=\"בְּדוּלְחָא\">בדולחא</a> (corr. acc.). [<span class=\"citation\">Ex. R. s. 38</span>, end <a href=\"#\" data-headword=\"*פָּרָאלַוְקִין\">פראלוקין</a>, prob. a corrupt. of our w., cmp. LXX].</div>","alt":["בּוּרְלָא"]},"4186":{"h":"בִּירָם","r":"B00729","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Biram</i>, also called <i>Beth Baltin</i>. <span class=\"citation\">R. Hash. 23ᵃ</span>; <span class=\"citation\">23ᵇ</span>, a signal station for announcing the New Moon (betw. Syria and Mesopotamia, Neub. Géogr. p. 354). <span class=\"citation\">Kidd. 72ᵃ</span>.—<span class=\"citation\">Snh. 108ᵃ</span> ועינא רבתי דב׳ Ms. M. (ed. <span dir=\"rtl\">ועיניה</span>, corr. acc.) the Great (hot) Spring of B.; v. Hildesh. Beitr. z. Geogr. p. 29, note 206.</div>","alt":[]},"4187":{"h":"בִּירְנִין","r":"B00730","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּירַנְתָּא\">בִּירַנְתָּא</a></div>","alt":[]},"4188":{"h":"בִּירָנִית","r":"B00731","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>castle, palace</i>. <span class=\"citation\">Pes. 118ᵇ</span> (Ms. M. 2 <a href=\"#\" data-headword=\"בִּירָה\">בירה</a>).—Pl. <span dir=\"rtl\">בִּירָנִיֹּות</span> <span class=\"citation\">Ibid.</span> (description of Rome; v. Rabb. D. S. a. l. for Var. Lect.).</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"בִּרְיוֹן\">בִּרְיוֹן</a>) <i>a palace-woman, court-lady.</i> <i>—</i> Pl. as supra. <span class=\"citation\">Lev. R. s. 19</span> <span dir=\"rtl\">הושיב ב׳ וכ׳</span> (<span class=\"citation\">Yalk. Kings 249</span> <span dir=\"rtl\">נשים ב׳</span>) he placed court ladies in Jerusalem (forced them to leave home and serve at the palace); <span dir=\"rtl\">מהו ב׳</span> what is meant by (why are they named) biraniyoth? <span dir=\"rtl\">ביירן ציידן וכ׳</span> (not <span dir=\"rtl\">ציירן</span>), he laid a trap for them, he caught them (ensnared them).</div>","alt":[]},"4189":{"h":"בִּירַנְתָּא","r":"B00732","html":"<div class=\"sense\"> 1). <span class=\"citation\">Targ. Esth. I, 2</span> (h. text <span dir=\"rtl\">הבירה</span>); a. fr.—Pl. <span dir=\"rtl\">בִּירְנָיָתָא</span>, <span dir=\"rtl\">בִּרְ׳</span>; constr. <a href=\"#\" data-headword=\"בִּירָנִית\">בִּירְנְיָת</a>. <span class=\"citation\">Targ. Ps. XLVIII, 4</span> (h. text <a href=\"#\" data-headword=\"אַרְמוֹן I\">ארמון</a>). <span class=\"citation\">Targ. Am. III, 9</span> <span dir=\"rtl\">באשדור בִּרְנְיָת</span> (!).—<span class=\"citation\">Targ. Y. Lev. XXV, 29</span> <a href=\"#\" data-headword=\"בִּירְנִין\">בִּירְנִין</a> masc. (some ed. <a href=\"#\" data-headword=\"בּוּרְנִין\">בּוּרְנִין</a>) <i>fortified places</i></div>","alt":[]},"4190":{"h":"בִּירְצָא","r":"B00733","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ברץ</span>) <i>brim.</i> Pl. <span dir=\"rtl\">בִּירְצַיָּיא</span>. <span class=\"citation\">Ab. Zar. 74ᵇ</span> <span dir=\"rtl\">וחתים להו אבִּירְצַיְיהוּ</span> (some ed. <span dir=\"rtl\">אבּוּרְ׳</span>) and sealed the kegs on their brims. [<span class=\"citation\">Gitt. 69ᵇ</span> <a href=\"#\" data-headword=\"בִּירְצָא\">בירצא</a>, some ed., v. <a href=\"#\" data-headword=\"כִּרְצָא\">כַּרְצָא</a>.]</div>","alt":[]},"4191":{"h":"בִּירְקָא","r":"B00734","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Birka</i>, in Babylon. <span class=\"citation\">Kidd. 72ᵃ</span>, v. <a href=\"#\" data-headword=\"בֵּירְתָא\">בִּירְתָא</a>.</div>","alt":[]},"4192":{"h":"בירקא","r":"B00735","html":"<div class=\"sense\">, <span class=\"citation\">Ab. Zar. 28ᵇ</span> <span dir=\"rtl\">פתילתא ב׳</span>, v. <a href=\"#\" data-headword=\"בַּרְקָא II\"><span dir=\"rtl\">בַּרְקָא</span> II</a>, 2.</div>","alt":[]},"4193":{"h":"בֵּירְתָא","r":"B00736","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>well</i>, v. <a href=\"#\" data-headword=\"בֵּיר\">בֵּיר</a>.</div>","alt":[]},"4194":{"h":"בִּירְתָא","r":"B00737","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Ezra VI, 2</span>. Targ. II Esth. IX, 6, v. <a href=\"#\" data-headword=\"בִּירַנְתָּא\">בִּירַנְתָּא</a>; a. e.—Freq. as pr. n. pl. <i>Fort</i>. <span class=\"citation\">Y. Ber. II, 5ᵃ</span> top <span dir=\"rtl\">בִּירַת מלכא וכ׳</span> the royal fort of Bethlehem; (<span class=\"citation\">Lam. R. to I, 16</span>, end <span dir=\"rtl\">בירת ערבא</span>). Pesik. Shim. p. 117ᵃ; <span class=\"citation\">Yalk. Jer. 263</span> <span dir=\"rtl\">כד תימוט בירה ב׳ שמה</span> (read <span dir=\"rtl\">בירתא</span>) when a capital declines, it is still called the Capital.—<span class=\"citation\">Sot. 38ᵇ</span> <span dir=\"rtl\">(<span dir=\"rtl\">דשיחורי</span>) <span dir=\"rtl\">ב׳ דשחורי</span></span> the Fort of Shiḥori. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> <span dir=\"rtl\">בירת סיריקה</span> (Bab. <span class=\"citation\">ib. 31ᵃ</span> <span dir=\"rtl\">בירת סריקא</span> (not <a href=\"#\" data-headword=\"בֵּיר\">בירא</a>; Ms. M. <span dir=\"rtl\">ב׳ סירקי׳</span>) Fort Sirikah in Samaria. <span class=\"citation\">Kidd. 72ᵃ</span> <span dir=\"rtl\">ב׳ דסטיא</span>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ב׳ דנדה</span> Ms. Oxf. (ed. only <a href=\"#\" data-headword=\"בִּירְקָא\">בִּירְקָא</a>) opprobrious by-names of Babylonian places (v. Graetz <i>Messene</i>, in Progr. of Bresl. Jew. Semin. 1879); a. fr. [<span class=\"citation\">Y. Peah VII, 20ᵃ</span> bot. <span dir=\"rtl\">ב׳ דחרובתא</span>, v. <a href=\"#\" data-headword=\"כְּוַורְתָּא\">כְּוַורְתָּא</a>.]—[Pl. <a href=\"#\" data-headword=\"בִּינָתָא\">בִּירָתָא</a> (?). <span class=\"citation\">Targ. Prov. I, 21</span>, prob. to be read <a href=\"#\" data-headword=\"בִּרְיְתָא\">בִּירְיָתָא</a> <i>streets</i>, v. Nöld. Mand. Gr. p. 17.]</div>","alt":[]},"4195":{"h":"בִּירְתִין","r":"B00738","html":"<div class=\"sense\"> m. pl., v. <a href=\"#\" data-headword=\"בְּרָתָא\">בְּרָתָא</a></div>","alt":[]},"4196":{"h":"בִּירְתִית","r":"B00739","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בִּירְתִין\">preced. art.</a>) <i>of Birtha.</i> <i>—</i> Pl. <span dir=\"rtl\">בִּירְתִיּזֹת</span>. <span class=\"citation\">Y. Pes. III, 30ᵃ</span>, v. <a href=\"#\" data-headword=\"קוּבְטָאוֹת\">קוּבְטָיוֹת</a>.</div>","alt":[]},"4197":{"h":"בִּישׁ I","r":"B00740","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בְּאֵישׁ\">באיש</a>) <i>bad, wrong</i> (of persons and deeds); also <i>ill, sick</i>. <span class=\"citation\">Targ. Gen. VI, 5</span>; a. v. fr.—<span class=\"citation\">Lev. R. s. 22</span> (prov.) <span dir=\"rtl\">טב לב׳ וכ׳</span> when thou hast done good to a bad man, thou hast done evil (to thyself). <span class=\"citation\">B. Kam. 115ᵃ</span> חנן בישא Ḥanan, the bad man.—<span class=\"citation\">B. Mets. 75ᵇ</span> bot. <span dir=\"rtl\">דב׳ ליה וכ׳</span> he who fares badly in one place; a. fr.—Pl. <span dir=\"rtl\">בִּישִׁין</span>, <span dir=\"rtl\">בִּישַׁיָּא</span>, <span dir=\"rtl\">בִּישַׁיָּיא</span>. <span class=\"citation\">Targ. Gen. XIII, 13</span>; a. v. fr.—<span dir=\"rtl\">בִּישַׁיָּיא</span> freq. <i>the sick</i>. <span class=\"citation\">Koh. R. to IV, 6</span> <span dir=\"rtl\">ומפלגא לב׳</span> and distributes (the apples) among the sick.—<span class=\"citation\">Y. Bets. I, 60ᶜ</span> bot. <span dir=\"rtl\">מבקרא ביש׳</span> (not <span dir=\"rtl\">בייש׳</span>) to visit the sick.—Fem. <a href=\"#\" data-headword=\"בִּישׁ I\">בִּישָׁא</a>, <a href=\"#\" data-headword=\"בִּישְׁתָּא\">בִּישְׁתָּא</a> </div><div class=\"sense\"><b>1)</b>  (adj.) <i>bad;</i></div><div class=\"sense\"><b>2)</b>  (noun) <i>evil, wickedness, illness</i>. <span class=\"citation\">Targ. Gen. XXXVII, 20</span>; a. fr.—<span class=\"citation\">Ib. VI, 5</span>, a. fr. <span dir=\"rtl\">בִּישַׁת</span> constr.—<span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">ב׳ מי וכ׳</span> can bad be good? Y. ib. XIV, 14ᶜ bot. <span dir=\"rtl\">טב לבישתא וכ׳</span> (vinegar is) good for a sore, but bad for a sound tooth. <span class=\"citation\">Lev. R. s. 33</span>, beg., from it (the tongue) comes the good <span dir=\"rtl\">ומינה ב׳</span> and from it the evil; a. fr.—Pl. <a href=\"#\" data-headword=\"בִּישְׁתָּא\">בִּישָׁתָא</a>, <span dir=\"rtl\">בִּישָׁאתָא</span>, <a href=\"#\" data-headword=\"בֵּישָׁן\">בִּישָׁן</a>.—<span class=\"citation\">Targ. Gen. XXVIII, 8</span> (ed. Vien. O. <a href=\"#\" data-headword=\"בִּישׁ I\">בישא</a>, corr. acc.); a. fr.—<span class=\"citation\">Snh. 7ᵃ</span> happy is he who hears (himself insulted) and keeps silence <span dir=\"rtl\">חלפוה בישתיה מאה</span> (corr. <span dir=\"rtl\">חלפוהו בישתא</span>, v. Rabb. D. S. a. l. note 7) a hundred evils pass by him (he escapes &amp;c.); a. fr.</div>","alt":["בִּישָׁא"]},"4198":{"h":"בִּישׁ II","r":"B00741","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>K’far Bish</i>, prob. <i>Capharabis</i> in upper Idumæa. <span class=\"citation\">Lam. R. to II, 2</span>; <span class=\"citation\">Gitt. 57ᵃ</span></div>","alt":["כְּפַר ב׳"]},"4199":{"h":"בִּישׁוּ","r":"B00742","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (בִּישׁ I) </div><div class=\"sense\"><b>1)</b> <i>bad quality</i>. <span class=\"citation\">Targ. Jer. XXIV, 2</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>wickedness, evil</i>. <span class=\"citation\">Targ. O. Gen. XXXI, 52</span>; a. fr.—<span class=\"citation\">Sabb. 156ᵃ</span> <span dir=\"rtl\">חדא לב׳</span> one quality on the bad side; <span dir=\"rtl\">כולי לב׳</span> all bad. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">בישו עבדית וכ׳</span> (<a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a>) (not <span dir=\"rtl\">בישי</span>) have I done wrong that I &amp;c.? Pesik. Zakh. p. 24ᵇ [read twice:] <span dir=\"rtl\">למיגזי לבישא בִּישׁוּתֵיה</span>; (Tanḥ. Ki Thetse 6 <span dir=\"rtl\">בִּישְׁתֵּיה</span>, ed. Bub. ib. <span dir=\"rtl\">בישותיה</span>) to repay the bad man his badness. <span class=\"citation\">B. Kam. 115ᵃ</span> <span dir=\"rtl\">מפורסם לב׳</span> notorious for vice.—<span class=\"citation\">Men. 52ᵃ</span> <span dir=\"rtl\">מבישותין וכ׳</span> of our shortcomings they speak to them. <span class=\"citation\">Ab. Zar. 65ᵃ</span> <span dir=\"rtl\">עינא … ב׳</span> the eye which desires to see your misfortune. <span class=\"citation\">Keth. 25ᵇ</span>; <span class=\"citation\">Macc. 5ᵇ</span> <span dir=\"rtl\">הדר הזייה לר׳ א׳ בישות</span> he turned around and looked at R. E. with displeasure; <span class=\"citation\">Pes. 53ᵇ</span> <span dir=\"rtl\">חזא ביה … ב׳</span> (Ms. M. 2 a. Oxf. <span dir=\"rtl\">בבישות</span>, v. Rabb. D. S. a. l. note 400).—<span class=\"citation\">Y. Taan. III, 66ᶜ</span> bot. <span dir=\"rtl\">ומדינתא אזלא בבאישות</span> and the city perishes in wickedness (by pestilence).</div>","alt":["בִּושׁוּת","בִּישׁוּתָא","בְּאִישׁ׳"]},"4200":{"h":"בִּישּׁוּל","r":"B00743","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּשּׁוּל\">בִּשּׁוּ׳</a></div>","alt":["בִּישּׁוּלָא"]},"4201":{"h":"בִּישׁוּת","r":"B00744","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּישׁוּ\">בִּישׁוּ</a></div>","alt":["בִּישׁוּתָא"]},"4202":{"h":"בִּישֵּׂם","r":"B00745","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּשַׂם\">בָּשַׂם</a>,.—<span class=\"citation\">Pesik. R. s. 21</span>, read <a href=\"#\" data-headword=\"בָּסַס\">בִּיסֵּס</a>, v. <a href=\"#\" data-headword=\"בָּסַס\">בָּסַס</a>.</div>","alt":[]},"4203":{"h":"בֵּישָׁן","r":"B00746","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">בית שאן</span>, v. <a href=\"#\" data-headword=\"שְׁאָן\">שְׁאָן</a>) <i>Beshan</i> (Scythopolis), in Galilee. Y. B. Mets. X, 12ᶜ top <span dir=\"rtl\">דרייא דב׳</span> the dwelling houses of B.—<span class=\"citation\">Pes. 50ᵇ</span> <span dir=\"rtl\">בני ביישן</span> (Ms. Oxf. <a href=\"#\" data-headword=\"בֵּישָׁן\">בישן</a>, Ms. M. <a href=\"#\" data-headword=\"מֵישָׁן\">מישן</a>).</div>","alt":["(ביישן)"]},"4204":{"h":"בֵּישָׁנִי","r":"B00747","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בֵּישָׁן\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>inhabitant</i> or <i>native of Beshan</i>. <span class=\"citation\">Meg. 24ᵇ</span> (ed. <span dir=\"rtl\">בשיני</span>, Ms. M. <span dir=\"rtl\">בשני</span>, corr. acc.).—Pl. <a href=\"#\" data-headword=\"בֵּישָׁנִי\">בֵּישָׁנִין</a>. <span class=\"citation\">Y. Ber. II, 4ᵈ</span> bot.; (Meg. l. c. <span dir=\"rtl\">אנשי בית שאן</span>).—Ch. <span dir=\"rtl\">בַּיישַׁנָאֵי</span>. <span class=\"citation\">Y. Meg. III, beg. 73ᵈ</span></div><div class=\"sense\"><b>—2)</b> <i>beshani</i>, name of a species of olives. <span class=\"citation\">Peah VII, 1</span> an olive called <span dir=\"rtl\">ב׳ …</span> (Ms. M. <a href=\"#\" data-headword=\"בַּיְתוּסִי\">ביי׳</a>) beshani. Y. ib. 20ᵃ top <span dir=\"rtl\">אית דבעי מימר ב׳ ממש וכ׳</span> some would say, it means really a beshani (named after Beshan), others would derive its name from the fact (v. <a href=\"#\" data-headword=\"בּוֹשׁ\">בּוֹשׁ</a>) that it shames its neighbor (trees by its richness). [Oth. opin. <i>a dry olive</i>, not used for manufacturing oil.]</div>","alt":["(ביישני)"]},"4205":{"h":"בִּישְׂרָא","r":"B00748","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּשְׂרָא\">בִּשְׂרָא</a></div>","alt":[]},"4206":{"h":"בִּישְׂרָנָא","r":"B00749","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בִּישְׂרָא\">preced.</a>) <i>fleshy, stout.</i> <i>—</i> Pl. <a href=\"#\" data-headword=\"בִּישְׂרָנָא\">בִּישְׂרָנֵי</a>. <span class=\"citation\">Keth. 61ᵃ</span></div>","alt":[]},"4207":{"h":"בִּישְׁתָּא","r":"B00750","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּישׁ I\"><span dir=\"rtl\">בִּישׁ</span> I</a> fem., a. <a href=\"#\" data-headword=\"בִּישׁוּ\">בִּישׁוּ</a>.</div>","alt":[]},"4208":{"h":"בי\"ת","r":"B00751","html":"<div class=\"sense\"><i>Beth</i>, the second letter of the Alphabeth. <span class=\"citation\">Y. Sabb. XVI, 15ᶜ</span> top; a. fr.; v. <a href=\"#\" data-headword=\"אל\">אל&quot;ף</a>.—<span class=\"citation\">Y. Ned. III, 38ᵃ</span> bot. <span dir=\"rtl\">בי&quot;ת תרי וכ׳</span> the Beth (in <span dir=\"rtl\">ביצחק</span> <span class=\"citation\">Gen. XXI, 12</span>) intimates two, a son that is destined to inherit two worlds. <span class=\"citation\">Lev. R. s. 19</span> <span dir=\"rtl\">אם אתה עושה ב׳ כ&quot;ף</span> if thou changest the Beth into a Kaf; a. fr.—Pl. <span dir=\"rtl\">בֵּיתִין</span>. <span class=\"citation\">Sabb. 103ᵇ</span> one must not write … <span dir=\"rtl\">בי׳ כפין</span> (Ms. M. <span dir=\"rtl\">בָּתִּין</span>) the Beths so as to be taken for Kafs.—Chald. <a href=\"#\" data-headword=\"בי\">בי&quot;תא</a>. Cant. R. beg.; a. fr. [<span class=\"citation\">Shek. III, 2</span> Mish. ed. <a href=\"#\" data-headword=\"בַּיְתָא\">ביתא</a>, read <a href=\"#\" data-headword=\"בֵּיטָא I\">בֵּיטָא</a>.]</div>","alt":[]},"4209":{"h":"בִּית","r":"B00752","html":"<div class=\"sense\">, inf. <a href=\"#\" data-headword=\"בּוּת\">בּוּת</a> (sec. r. of <a href=\"#\" data-headword=\"בּוֹא\">בוא</a>) <i>to go in, lodge, pass the night.</i> <span class=\"citation\">Dan. VI, 19</span>. <span class=\"citation\">Targ. Gen. XXXII, 22</span>; a. fr.—<span class=\"citation\">Pes. 107ᵃ</span> <span dir=\"rtl\">בת טוות</span> (Dan. l. c.) he went to bed without tasting food. <span class=\"citation\">Snh. 95ᵃ</span> (prov.) <span dir=\"rtl\">בת דינא וכ׳</span> if punishment is procrastinated, punishment is gone. <span class=\"citation\">Taan. 24ᵇ</span> <span dir=\"rtl\">ביתו כולי וכ׳</span> go ye all to bed fasting. <span class=\"citation\">Pes. 42ᵃ</span> <span dir=\"rtl\">מיא דביתו</span> (Chald. transl. of the ambiguous <span dir=\"rtl\">מים שֶׁלָּנוּ</span>) water kept in vessels over night. <span class=\"citation\">Ber. 60ᵇ</span> <span dir=\"rtl\">בת בדברא</span> he slept in the open field. <span class=\"citation\">Snh. 63ᵇ</span>.—<span class=\"citation\">Ib. 109ᵃ</span> top <span dir=\"rtl\">בעי למֵיבַת</span> he wanted to stay over night; a. e.—Part. <a href=\"#\" data-headword=\"בָּאִית\">בָּאֵית</a>. <span class=\"citation\">Targ. Is. LVIII, 5</span>.</div><div class=\"sense\"><b>Pa. בַּיֵּית</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"בי\">same</a>. <span class=\"citation\">Erub. 73ᵃ</span> (opp. to taking meals).</div></div><div class=\"sense\"><b>Af. אָבִית</b> <div class=\"sense\"><i>to keep over night, postpone burial</i>. <span class=\"citation\">Snh. 47ᵃ</span> <span dir=\"rtl\">מֵבִית ליה למת</span> dare one postpone the burial of the dead?</div></div>","alt":["בָּת"]},"4210":{"h":"בַּיִת","r":"B00753","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"בִּית\">preced.</a>; v. Ges. H. Dict. s. v. as to various etymological attempts), constr. <a href=\"#\" data-headword=\"בֵּיתָא I\">בֵּית</a>, pl. <span dir=\"rtl\">בָּתִּים</span>. </div><div class=\"sense\"><b>1)</b> <i>house, household, home</i>. <span class=\"citation\">Yoma 11ᵇ</span> ב׳ מיוחד לדירה <i>bayith</i> means a building intended for a dwelling. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מי שמייחד ביתו לו</span> (Var. v. Rabb. D. S. a. l. note) he who devotes his house (its contents) to himself exclusively (unaccommodating); <span class=\"citation\">Arakh. 16ᵃ</span> <span dir=\"rtl\">מי שמיוחד וכ׳</span>.—<span dir=\"rtl\">בעל הב׳</span> (abbrev. <span dir=\"rtl\">בע&quot;ה</span>) <i>owner, landlord; host; private man</i>, opp. to trader, artisan &amp;c. <span class=\"citation\">Ber. 46ᵃ</span> <span dir=\"rtl\">בע&quot;ה בוצע וכ׳</span> the host breaks the bread, and the guest says the blessing. <span class=\"citation\">Tosef. ib. IV, 14</span> <span dir=\"rtl\">של בע&quot;ה</span> home-made (bread), opp. <a href=\"#\" data-headword=\"גְּלוּסְקִין\">גלוסקין</a>; Y. ib. VI, 10ᵇ bot.—<span class=\"citation\">Sabb. I, 1</span> <span dir=\"rtl\">בע&quot;ה</span> the donor, opp. <a href=\"#\" data-headword=\"עני\">עני</a> the recipient. <span class=\"citation\">Gen. R. s. 22</span>; a. v. fr.—בן ב׳ <i>inmate, attendant.</i> <span class=\"citation\">Ab. I, 5</span>; a. fr.—<span dir=\"rtl\">פסול הב׳</span> the degraded (slave) of the house. <span class=\"citation\">Gen. R. s. 70</span>.</div><div class=\"sense\"><b>—2)</b>  Esp. (<a href=\"#\" data-headword=\"שַׁרְיֵי\">הַ</a>)בַּ׳ <i>the Temple</i>. <span dir=\"rtl\">בפני הב׳</span> in days when the Temple exists, <span dir=\"rtl\">שלא בפני הב׳</span> when it does not exist. <span class=\"citation\">Ḥull. V, 1</span>; a. fr.—<span dir=\"rtl\">ב׳ שני</span> or <span dir=\"rtl\">ב׳ אחרון</span> <i>the Second Temple</i>. <span class=\"citation\">Cant. R. to VIII, 9</span>; a. fr.—הר הב׳ Temple Mount, v. <a href=\"#\" data-headword=\"הַר\">הַר</a>.</div><div class=\"sense\"><b>—3)</b> <i>school, college</i>, (collect.) <i>disciples;</i> בֵּית הלל Hillelites &amp;c. <span class=\"citation\">Bets. I, 1</span>; a. fr. <span class=\"citation\">Treat. Sof’rim IV, 1</span> <span dir=\"rtl\">של ב׳ וכ׳</span> those of the house of &amp;c. [<span class=\"citation\">Y. Shebi. II, 33ᵈ</span> bot., a. e. <span dir=\"rtl\">דבית … ר׳</span>, usu. <a href=\"#\" data-headword=\"*דְּבִי\">דבי</a>, v. <a href=\"#\" data-headword=\"בֵּי\">בֵּי</a>].</div><div class=\"sense\"><b>—4)</b> <i>body</i>. <span class=\"citation\">Ber. 44ᵇ</span> <span dir=\"rtl\">אוי לו לב׳ וכ׳</span> that human body (Rashi: stomach) is to be pitied where vegetables are a constant guest (being the only food).</div><div class=\"sense\"><b>—5)</b> <i>wife.</i> <span class=\"citation\">Yoma I, 1</span> ביתו זו וכ׳ ‘his house’—that means his wife. <span class=\"citation\">Ib. 13ᵃ</span> <span dir=\"rtl\">והך לאו ביתו היא</span> but this one (designated for him in case of his wife’s death) cannot be called ‘his house’. <span class=\"citation\">Sabb. 118ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—6)</b>  Euphem. <i>pudenda; marital intercourse</i>. <span class=\"citation\">Y. Sabb. IX, 12ᵃ</span> top; <span class=\"citation\">Mikv. VIII, 4</span> <span dir=\"rtl\">שמשה את בֵּיתָהּ</span> she had intercourse. Ib. <span dir=\"rtl\">כבדה את הב׳</span> she washed &amp;c. <span class=\"citation\">Y. Sot. I, 16ᶜ</span> bot. <span dir=\"rtl\">אסורה לביתה</span> is forbidden to her husband. <span class=\"citation\">Nidd. 5ᵃ</span> <span dir=\"rtl\">מהומת לביתה</span> she hastens to perform her marital duty. Y. ib. I, beg. 48ᵈ. Cmp. <a href=\"#\" data-headword=\"חֶדֶר\">חֶדֶר</a>.</div><div class=\"sense\"><b>—7)</b> <i>store-house, store-room</i>. <span dir=\"rtl\">בֵּית העצים</span> wood-room; <span dir=\"rtl\">ב׳ התבן</span> straw-magazine; <span dir=\"rtl\">ב׳ הבקר</span> stable; &amp;c. <span class=\"citation\">Yoma 11ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—8)</b>  (geogr.) <i>place, town</i>, in compounds (for which see the respective determinants), e.g. <span dir=\"rtl\">ב׳ בוקיא</span></div><div class=\"sense\"><b>—9)</b>  (anat.) <i>limb, organ</i>, in compounds (v. supra 8)), e.g. <span dir=\"rtl\">ב׳ הבליעה</span></div><div class=\"sense\"><b>—10)</b> <i>shed</i> for plants, <i>covering.</i> <span class=\"citation\">Shebi. II, 4</span> (pl.). Y. ib. 33ᵈ.—<span class=\"citation\">Y. Sabb. VII, 10ᵃ</span>.—1</div><div class=\"sense\"><i>receptacle, cover</i> &amp;c., e.g. <span dir=\"rtl\">ב׳ הדיו</span> <i>inkstand</i>. <span class=\"citation\">Tosef. Kel. B. Mets. IV, 11</span>; <span dir=\"rtl\">ב׳ יד</span> <i>sleeve</i>, v. <a href=\"#\" data-headword=\"אוּנְקְלַי II\"><span dir=\"rtl\">אוּנְקְלַי</span> II</a>, &amp;c.—<span class=\"citation\">Men. 34ᵇ</span>, a. e. <i>cases of the T’fillin</i></div><div class=\"sense\"><b>Chief compounds:. בֵּית אָב</b> <div class=\"sense\">, pl. <span dir=\"rtl\">בָּתֵּי אָבוֹת</span> </div><div class=\"sense\"><b>1)</b> <i>paternal home, family</i>. <span class=\"citation\">Snh. 38ᵃ</span> <span dir=\"rtl\">שני ב׳ א׳</span> two families (dynasties); a. fr.—<span class=\"citation\">Tosef. Ter. II, 11</span> <span dir=\"rtl\">בתי אבות</span> = <span dir=\"rtl\">אריסי ב׳ א׳</span> <i>hereditary land-tenants;</i> <span class=\"citation\">B. Bath. 46ᵇ</span></div><div class=\"sense\"><b>—2)</b> <i>priest’s division.</i> <span class=\"citation\">Taan. II, 6</span>; a. fr.; v. <a href=\"#\" data-headword=\"אֱנוֹשׁ\">אֱנוֹשׁ</a> pl.</div><div class=\"sense\"><b>—3)</b> <i>origin of a law, rule</i> &amp;c.; cmp. <a href=\"#\" data-headword=\"אָב II\"><span dir=\"rtl\">אָב</span> II</a>. <span class=\"citation\">Cant. R. to II, 4</span> <span dir=\"rtl\">ב׳ א׳ של הלכה</span> the origin (principle) of a legal rule. <span class=\"citation\">Midr. Till. to Ps. CIV, 29</span> wherever the root <span dir=\"rtl\">רעש</span> is used, it means cessation of government, <span dir=\"rtl\">ואיזהו ב׳ א׳ שלהם וכ׳</span> and where is the origin (determining the meaning) of all of them? (Answ. <span class=\"citation\">Jer. LI, 29</span>). <span class=\"citation\">Lev. R. s. 1</span>, beg. <span dir=\"rtl\">מב׳ א׳ שלהן וכ׳</span> from the chief passage (<span class=\"citation\">Hag. I, 13</span> ‘Haggai, the messenger’ &amp;c.) we learn that prophets are called messengers (or angels).—<span dir=\"rtl\">בֵּית דִּין</span> (abbr. <span dir=\"rtl\">ב&quot;ד</span>) <i>court</i>.—<span dir=\"rtl\">ב&quot;ד של שבעים ואחד</span> or <span dir=\"rtl\">ב&quot;ד הגדול</span> the Great Sanedrin of seventy one members. <span class=\"citation\">Snh. I, 5</span>. Y. ib. 19ᵃ bot.; a. fr.—<span dir=\"rtl\">ב&quot;ד נוטה</span> court of an odd number of judges. <span dir=\"rtl\">ב&quot;ד שקול</span> of an even number of judges. <span class=\"citation\">Snh. 3ᵇ</span>.—<span dir=\"rtl\">ב&quot;ד שריא</span> a permitting court, opprobrious name of a court too lax in religious affairs. Y. Gitt. VII, 48ᵈ top; Y. Nidd. III, 50ᵈ bot.—[For all other compounds not self-evident, v. respective determinants.] [<span dir=\"rtl\">בית תר</span>, v. <a href=\"#\" data-headword=\"בִּיתֵּר\">בִּיתֵּר</a>.—<span class=\"citation\">Gen. R. s. 12</span> <span dir=\"rtl\">בית שלו</span>, <span dir=\"rtl\">בית של עולם</span>, v. <a href=\"#\" data-headword=\"בִּיָּא\">בִּיָּא</a>.]</div></div>","alt":[]},"4211":{"h":"בֵּיתָא I","r":"B00754","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"בַּיִת\">same</a>. <span class=\"citation\">Targ. Ex. XII, 3</span>; a. v. fr.—<span class=\"citation\">Meg. 16ᵃ</span> <span dir=\"rtl\">ווי מב׳ וכ׳</span> woe inside, woe outside! <span class=\"citation\">Gen. R. s. 32</span> <span dir=\"rtl\">ההוא ב׳ קלקלתא</span> that house which is a ruin (a Samaritan’s designation of the Jerusalem Temple). <span class=\"citation\">Y. Snh. I, 18ᶜ</span> <span dir=\"rtl\">ההן ב׳ דלרע</span> that house down there (Rabbi’s college); <span class=\"citation\">Y. R. Hash. II, 58ᵃ</span> bot. <span dir=\"rtl\">והן בייתא</span>.—<span class=\"citation\">Yeb. 109ᵇ</span> <span dir=\"rtl\">דבייתיה כי בייתיה דמי</span> for his (the trustee’s) house is like his (the neighbor’s) own house (he is familiar with the interior); a. fr.—<i>Pi.</i> <span dir=\"rtl\">בָּתִּין</span>, <span dir=\"rtl\">בָּתַּיָּא</span>, <span dir=\"rtl\">בָּתֵּי</span>. <span class=\"citation\">Targ. Ex. I, 21</span>; a. v. fr.—<span class=\"citation\">B. Bath. 61ᵇ</span> sq. <span class=\"citation\">Ib. 67ᵃ</span>, v. <a href=\"#\" data-headword=\"דַּרְתָּא\">דַּרְתָּא</a>.—<span class=\"citation\">Ber. 6ᵃ</span> <i>the case of T’fillin</i>, v. <a href=\"#\" data-headword=\"בַּיִת\">preced.</a> [Playful etymol. <span dir=\"rtl\">ב̇וא אי̇ת̇יב בה</span>. <span class=\"citation\">Sabb. 77ᵇ</span>.]</div><div class=\"sense\"><b>—2)</b> <i>night-lodging</i>. <span class=\"citation\">Gitt. 57ᵃ</span> <span dir=\"rtl\">לא יהבי ב׳ לאושפיזא</span> they would not designate a house as a lodging for strangers (<span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">דלא הות מקבלא אכסניא</span>).</div>","alt":["בֵּית","בַּיְיתָא"]},"4212":{"h":"בֵּיתָא II","r":"B00755","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"בַּת I\">בַּת</a>) <i>bath</i>, a measure. <span class=\"citation\">Targ. Is. V, 10</span>. <span class=\"citation\">Targ. Ezek. XLV, 11</span>; a. e.—Pl. <span dir=\"rtl\">בַּתִּין</span>, <span dir=\"rtl\">בֵּיתִין</span>. <span class=\"citation\">Ib. 14</span>. <span class=\"citation\">Targ. I Kings VII, 26</span>.</div>","alt":[]},"4213":{"h":"בַּיְתָא","r":"B00756","html":"<div class=\"sense\"><i>night-bird</i>, v. <a href=\"#\" data-headword=\"בָּאוָת\">בָּאוָת</a>.</div>","alt":[]},"4214":{"h":"בי\"תא","r":"B00757","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בי\">בי&quot;ת</a></div>","alt":[]},"4215":{"h":"בַּיְתוֹס","r":"B00758","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Βοηθός) <i>Boëthus;</i></div><div class=\"sense\"><b>1)</b>  the founder of a sect similar to that of the Sadducees, named <span dir=\"rtl\">בַּיְיתוֹסִין</span> <i>Boëthusians</i>. Ab. d’R. Nath. ch. V.</div><div class=\"sense\"><b>—2)</b>  father of one Martha or Miriam, a rich woman in the days of the siege of Jerusalem by Titus. <span class=\"citation\">Gitt. 56ᵃ</span>. <span class=\"citation\">Lam. R. to I, 16</span> <a href=\"#\" data-headword=\"מִרְיָם\">מרים</a>; Y. Keth. V, 30ᵇ bot. <span dir=\"rtl\">מרתא</span>.</div><div class=\"sense\"><b>—3)</b>  B. ben Zonin. <span class=\"citation\">Y. B. Mets. V, 10ᵇ</span> top; a. fr.</div><div class=\"sense\"><b>—4)</b>  R. B.—<span class=\"citation\">Y. Erub. VI, 23ᶜ</span> bot.</div>","alt":["בַּיְיתוֹס"]},"4216":{"h":"בַּיְתוּסִי","r":"B00759","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Boëthusian</i>, v. <a href=\"#\" data-headword=\"בַּיְתוֹס\">preced.</a> <span class=\"citation\">Sabb. 108ᵃ</span> <span dir=\"rtl\">שאל ב׳ אחד</span> (Mass. <span class=\"citation\">Sof. I, 2</span> <span dir=\"rtl\">שאל אחד</span>, corr. acc.) a Boëthusian asked. <span class=\"citation\">Tosef. Yoma I, 8</span> (<span class=\"citation\">Yoma 19ᵇ</span> <span dir=\"rtl\">צדוקי</span>).—Pl. <a href=\"#\" data-headword=\"בַּיְתוּסִי\">בַּיְתוֹסִים</a>, <a href=\"#\" data-headword=\"בַּיְתוּסִי\">בַּיְתוֹסִין</a>, <a href=\"#\" data-headword=\"בַּיְתוּסִי\">בַּיי׳</a>. <span class=\"citation\">Men. X, 3</span>. <span class=\"citation\">Y. Yoma I, 39ᵃ</span> bot. <span dir=\"rtl\">מפני הב׳</span> (for which ib. a. Bab. Yoma l. c. <span dir=\"rtl\">הצדוקים</span>); Tosef. l. c. [Ar. ed. pr. <span dir=\"rtl\">בית סי</span>, <span dir=\"rtl\">בית סין</span>, read as one w., like Tosef. l. c. Var.]</div>","alt":["בַּיְי׳"]},"4217":{"h":"ביתור","r":"B00760","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּיתֵּר\">בִּיתֵּר</a></div>","alt":[]},"4218":{"h":"בית־יוני","r":"B00761","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִינִי\">הִינִי</a> 3).</div>","alt":[]},"4219":{"h":"בִּיתוּתָא","r":"B00762","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בית</span>) <i>dwelling</i>. <span class=\"citation\">Targ. Job XXX, 23</span> Ms. (Var. a. ed. <span dir=\"rtl\">בית קבורתא</span>).</div>","alt":[]},"4220":{"h":"ביתיס","r":"B00763","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Yoma I, 18</span>, Var. for <a href=\"#\" data-headword=\"בַּיְתוּסִי\">בַּיְתוֹסִי</a>.</div>","alt":["בַּיְתִסִי"]},"4221":{"h":"בִּיתֵּר","r":"B00764","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (prob. a contr. of <span dir=\"rtl\">בית תרעא</span>) <i>Bithter</i> (Βιθθηρά), known as <i>Bettar</i>, a town in Southern Palestine, renowned as the centre of the Bar-Kokhba revolution against Hadrian. [As to its situation, v. Neub. Géogr. p. 130; Graetz Gesch. der <span class=\"citation\">Jud. IV, 168</span>). <span class=\"citation\">Gitt. 57ᵃ</span> <span dir=\"rtl\">כרך ב׳</span> the Fortress of B.—<span class=\"citation\">Y. Taan. IV, 69ᵃ</span> top. <span class=\"citation\">Lam. R. to II, 2</span>; <span class=\"citation\">IV, 18</span>; a. fr.—<span class=\"citation\">Y. Ber. I, 3ᵈ</span>, a. fr. <span dir=\"rtl\">הרוגי ב׳</span> those killed in the Bar-Kokhba revolution (whom Hadrian would not allow to be buried). <span class=\"citation\">Ḥall. IV, 10</span> (<span class=\"citation\">11</span>) (Y. ed. <a href=\"#\" data-headword=\"ביתור\">ביתור</a>; ed. Nap. <span dir=\"rtl\">בייתר</span>, Ven. <span dir=\"rtl\">ביתיר</span>) mentioned as a place not belonging to Palestine proper. <span class=\"citation\">Cant. R. to II, 17</span> <span dir=\"rtl\">בית תר</span>.</div>","alt":[]},"4222":{"h":"*בֵּיתְרֵי","r":"B00765","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Bethre</i>. <span class=\"citation\">Snh. 95ᵃ</span> <span dir=\"rtl\">כי מטו בי תרי</span> (Ms. M. <span dir=\"rtl\">ביטרי</span>) when they came to B.</div>","alt":[]},"4223":{"h":"*ביתרתה","r":"B00766","html":"<div class=\"sense\">, <span class=\"citation\">Y. Succ. I, 52ᵃ</span> bot., read, with Y. Erub. I, 19ᶜ top; <span class=\"citation\">Y. Kil. IV, 29ᵇ</span>, <span dir=\"rtl\">בית חבירתא</span> or <span dir=\"rtl\">תה …</span>, name of a field or an estate.</div>","alt":[]},"4224":{"h":"בְּכָא","r":"B00767","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בכי\">בכי</a></div>","alt":["בָּכָה"]},"4225":{"h":"בכוליאר","r":"B00768","html":"<div class=\"sense\">, <span class=\"citation\">Yoma 25ᵃ</span>, v. <a href=\"#\" data-headword=\"כּוֹכְלִיאָס\">כּוֹכְלְיָיס</a></div>","alt":[]},"4226":{"h":"בְּכוֹר","r":"B00769","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>first-born</i> (opp. <span dir=\"rtl\">פשוט</span>, a plain, unprivileged son); also of animals. <span class=\"citation\">B. Bath. 126ᵃ</span> <span dir=\"rtl\">ב׳ ופשוט</span>; a. fr.—<span class=\"citation\">Y. Pes. X, beg. 37ᵇ</span> <span dir=\"rtl\">הוה ב׳ והוה אכיל</span> was a first-born and yet did not fast (on the eve of Passover).—<span class=\"citation\">Yeb. 16ᵃ</span>; Y. ib. I, 3ᵃ bot. <span dir=\"rtl\">ב׳ שטן</span> (play on <a href=\"#\" data-headword=\"קטן\">קטן</a>) the first in obstinate dispute.—<span class=\"citation\">Gen. R. s. 91</span> (ref. to <span class=\"citation\">Gen. XLII, 37</span>) <span dir=\"rtl\">הרי זה ב׳ שוטה וכ׳</span> is this a foolish first-born son! are thy children not my children? [<span dir=\"rtl\">ב׳ שוטה</span> a first-born son by his mother, v. <a href=\"#\" data-headword=\"בּוּכְרָא I\"><span dir=\"rtl\">בּוּכְרָא</span> I</a>.]—<span class=\"citation\">Bekh. VIII, 1</span>, a. fr. <span dir=\"rtl\">ב׳ לנחלה</span> a first-born with the privileges of a double share of inheritance (<span class=\"citation\">Deut. XXI, 15</span> sq.), <span dir=\"rtl\">ב׳ לכהן</span> one who must be redeemed from the priest (<span class=\"citation\">Ex. XIII, 2</span>). Ib. IV, 4 <span dir=\"rtl\">ראה את הב׳</span> examined the first-born animal (and declared it defective); a. fr.—Pl. <span dir=\"rtl\">בְּכוֹרִים</span>, <span dir=\"rtl\">בְּכוֹרוֹת</span>. <span class=\"citation\">Ex. R. s. 18</span> <span dir=\"rtl\">בְּכוֹרֵי מצרים</span> the first-born of Egyptian cattle; <span class=\"citation\">ib.</span> <span dir=\"rtl\">מכת בכורות</span> the plague of the first-born in Egypt; <span class=\"citation\">Num. R. s. 4</span>; a. fr.—<span class=\"citation\">Bekh. IV, 5</span> he who receives payment <span dir=\"rtl\">להיות רואה ב׳</span> for examining first-born animals (as to bodily defects, v. supra); a. fr.—[<span class=\"citation\">Y. Shek. III, beg. 47ᵇ</span> <span dir=\"rtl\">הבכו׳</span>, read <span dir=\"rtl\">הבַּכִּירוֹת</span>.] Ch. <a href=\"#\" data-headword=\"בּוּכְרָא I\">בּוּכְרָא</a>.</div>","alt":[]},"4227":{"h":"בִּכּוּרָא","r":"B00770","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= <a href=\"#\" data-headword=\"בִּכּוּרָה\">next w.</a>) <i>early fig</i>. <span class=\"citation\">Targ. Hos. IX, 10</span>. <span class=\"citation\">Targ. Is. XXVIII, 4</span>.—Pl. <span dir=\"rtl\">בִּכּוּרִין</span>, <span dir=\"rtl\">בִּכּוּרַיָּא</span> m. <i>first fruits</i>. <span class=\"citation\">Targ. Lev. II, 14</span>; a. e.</div>","alt":[]},"4228":{"h":"בִּכּוּרָה","r":"B00771","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>early fruit</i>, esp. <i>fig.</i></div><div class=\"sense\">Pl. <span dir=\"rtl\">בִּכּוּרוֹת</span>. <span class=\"citation\">Gen. R. s. 22</span> <span dir=\"rtl\">היה אוכל הב׳ וכ׳</span> ate the early fruits himself and offered the late to the king. <span class=\"citation\">Snh. 91ᵇ</span>; <span class=\"citation\">Lev. R. s. 4</span> <span dir=\"rtl\">ב׳ נאות</span> fine early figs. <span class=\"citation\">Ter. IV, 6</span> <span dir=\"rtl\">בב׳</span> at the time of early ripening.—2) Pl. <span dir=\"rtl\">בִּכּוּרִים</span> m. (b. h.) <i>first fruits</i> (to be offered), (sub. <span dir=\"rtl\">מנחת</span>) <i>offering of first fruits.</i> <span class=\"citation\">Bicc. I, 1</span>; a. fr.—<i>Biccurim</i>, name of a treatise of the Mishnah, belonging to the order of Seeds <span dir=\"rtl\">(זרעים</span>).</div>","alt":["בִּיכּ׳"]},"4229":{"h":"בְּכוֹרָה","r":"B00772","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>first-born</i>. Pl. <span dir=\"rtl\">בְּכוֹרוֹת</span>. <span class=\"citation\">Ex. R. s. 18</span> <span dir=\"rtl\">הנקבות הב׳</span> the first-born females (in Egypt).</div><div class=\"sense\"><b>—2)</b> <i>first birth, birth-right</i>. <span class=\"citation\">B. Bath. 123ᵃ</span> <span dir=\"rtl\">נטל ב׳ מראובן וכ׳</span> took the birth-right from Reuben and gave it to Joseph. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ראויה היתה ב׳ וכ׳</span> the first birth (of Jacob’s children) was destined to issue from Rachel. <span class=\"citation\">Ib. 124ᵃ</span> <span dir=\"rtl\">חלק ב׳</span> the share of the first-born; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>the law appertaining to first-born animals</i>, v. <a href=\"#\" data-headword=\"בְּכוֹר\">בְּכוֹר</a>.—<span class=\"citation\">Bekh. I, 1</span> <span dir=\"rtl\">חייב בב׳</span> is subject to the law &amp;c., <span dir=\"rtl\">פטור מן הב׳</span> is exempt from &amp;c.; a. v. fr.—Pl. <span dir=\"rtl\">בְּכוֹרוֹת</span>, v. supra a. <a href=\"#\" data-headword=\"בְּכוֹר\">בְּכוֹר</a>.—<i>B’khoroth</i> (Bekh.), name of a Talmudic treatise, belonging to the order of Kodashim <span dir=\"rtl\">(קדשים</span>).</div>","alt":[]},"4230":{"h":"בְּכוֹרוּתָא","r":"B00773","html":"<div class=\"sense\">, <i>birth-right</i>. <span class=\"citation\">Targ. O. Gen. XXV, 31</span> sq.; v. <a href=\"#\" data-headword=\"בְּכֵירוּתָא\">בְּכֵירוּתָא</a>.</div>","alt":[]},"4231":{"h":"*בּכּוּשָׁא","r":"B00774","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">בר כושא</span>, v. <span dir=\"rtl\">כשכש</span>; for Syr. <span dir=\"rtl\">בכשא</span> = <span dir=\"rtl\">בר כשא</span>, cmp. <a href=\"#\" data-headword=\"דּוֹפֵק\">דּוֹפֵק</a>) <i>knocker</i> for giving signals for worship. <span class=\"citation\">Y. Meg. III, 73ᵈ</span> bot. (Var. <a href=\"#\" data-headword=\"מַכּוֹשׁ\">מַכּוֹשָׁא</a>).</div>","alt":[]},"4232":{"h":"בָּכוּתָא","r":"B00775","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּכִיתָא\">בְּכִיתָא</a></div>","alt":[]},"4233":{"h":"בכי","r":"B00776","html":"<div class=\"sense\"> √בך <i>to break through, split</i>, v. Ges. H. Dict. s. v.; v. <span dir=\"rtl\">בכר</span>) <i>to weep</i>. <span class=\"citation\">Ḥull. 7ᵇ</span>; a. fr. Ohol. XVIII, 4 <span dir=\"rtl\">שדה בּוֹכִין</span> weepers’ field, a place where the funeral cortege disperses; v. <span class=\"citation\">M. Kat. 5ᵇ</span> <span dir=\"rtl\">שדה שמפטירין בה מתים</span> (Ms. M. <span dir=\"rtl\">שמפסידין</span>) where the funeral addresses are held.</div><div class=\"sense\"><b>Pi. בִּכָּה</b> <div class=\"sense\"><b>1)</b> <i>to cause to weep, make cry</i>. <span class=\"citation\">Lam. R. to I, 2</span> (ref. to <span dir=\"rtl\">בכה תבכה</span>) <span dir=\"rtl\">בוכה ומְבַכָּה מה&quot;ש עמה</span> she cries and makes the angels cry with her. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">היו מְבַכִּין אותו</span> they made it (the Egyptian child) cry.</div><div class=\"sense\"><b>—2)</b> <i>to mourn, lament</i> (<span class=\"citation\">Ezek. VIII, 14</span>). <span class=\"citation\">Tosef. Kel. B. Bath. II, 8</span> <span dir=\"rtl\">מְבַכּוֹת מיתיהן</span> lament their dead.</div></div>","alt":["בָּכָה"]},"4234":{"h":"בכי ²","r":"B00777","html":"<div class=\"sense\">, also (act. v.) <i>to lament</i>. <span class=\"citation\">Targ. Gen. XXIII, 2</span>; a. fr.—Part. <a href=\"#\" data-headword=\"בְּכִי I\">בָּכֵי</a>. <span class=\"citation\">Ber. 5ᵇ</span> לההוא שופרא … קא בכינא I cry over that beauty that it should rot in the ground. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אמאי קבכית</span> why criest thou? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דהוה קא בכי</span> (v. Rabb. D. S. a. l.) that he was crying. <span class=\"citation\">Lam. R. to I, 17</span> <span dir=\"rtl\">בָּכְיָה סלקא בָּכְיָה נחתא</span> weeping she (Israel) goes up (to the ruins of Jerusalem), weeping she goes down. <span class=\"citation\">Y. Yoma II, 39ᵈ</span> top <span dir=\"rtl\">שרון … בָּכְיִין</span> all the people began to cry.—<span class=\"citation\">Y. Ḥag. I, 76ᶜ</span> bot. <span dir=\"rtl\">בכי בעיינוי</span> blear-eyed.—<span class=\"citation\">Taan. 5ᵇ</span> וכי בכדי בכו בָּכַיָּיא Ms. M. (ed. <span dir=\"rtl\">ספדו</span>) is it for naught the weepers wept? <span class=\"citation\">Gen. R. s. 68</span>, v. <a href=\"#\" data-headword=\"בְּכִי I\">next w.</a>; a. fr.</div>","alt":["בְּכָא"]},"4235":{"h":"בְּכִי I","r":"B00778","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"בכי ²\">preced.</a>) <i>weeping</i>. <span class=\"citation\">Gen. R. s. 68</span>; <span class=\"citation\">Lev. R. s. 8</span>, a. e. (playing on <span dir=\"rtl\">בכושרות</span>, <span class=\"citation\">Ps. LXVIII, 7</span>) <span dir=\"rtl\">ב׳ ושירות</span> weeping and songs, <span dir=\"rtl\">מאן דבעי אומר וכ׳</span> he who loves (his wife) sings, he who does not, weeps; <span class=\"citation\">Snh. 22ᵃ</span></div>","alt":[]},"4236":{"h":"בְּכִי I ²","r":"B00779","html":"<div class=\"sense\">Targ. II, Sam. XIII, 36; v. <a href=\"#\" data-headword=\"בְּכִיתָא\">בְּכִיתָא</a></div>","alt":[]},"4237":{"h":"בְּכִי II","r":"B00780","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Baalbek</i> (<i>En-Bekhi</i>, later <i>Heliopolis</i>), an ancient city of Syria, renowned for its temples and bazaars <a href=\"#\" data-headword=\"יָרִיד\">(יריד</a>). <span class=\"citation\">Ab. Zar. 11ᵇ</span> <span dir=\"rtl\">יריד שבעין ב׳</span> the bazaar at En B. (with its idolatrous rites). <span class=\"citation\">Maasr. V, 8</span> שום ב׳ ב׳ Baalbek garlic.</div>","alt":["בַּעַל ב׳","(עֵין ב׳)"]},"4238":{"h":"בְּכָי","r":"B00781","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> בָּכָא?) a species of <i>pears</i>, prob. the pyrum Syrium of the Romans (cmp. LXX a. Vulg. <span class=\"citation\">I Chr. XIV, 15</span>). . <span class=\"citation\">Y. Kil. I, 27ᵃ</span></div>","alt":[]},"4239":{"h":"בִּכְיָא","r":"B00782","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"בְּכִי I\">בְּכִי</a>. <span class=\"citation\">Targ. Is. XXXVIII, 3</span>; a. e.</div>","alt":[]},"4240":{"h":"בַּכְיָא","r":"B00783","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בכי\">בכי</a>) <i>weeper, wailer.</i> Pl. <span dir=\"rtl\">בָּכַיָּיא</span>. <span class=\"citation\">Taan. 5ᵇ</span>, v. <a href=\"#\" data-headword=\"בכי\">בכי</a> ch.</div>","alt":[]},"4241":{"h":"בְּכִיָּה","r":"B00784","html":"<div class=\"sense\">, f. = <a href=\"#\" data-headword=\"בְּכִי I\"><span dir=\"rtl\">בְּכִי</span> I</a>. <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> top <span dir=\"rtl\">בכיי׳ של תפלות</span>; Bab. <span class=\"citation\">Taan. 29ᵃ</span> <span dir=\"rtl\">בכי של חנם</span> weeping for no cause. <span class=\"citation\">Gitt. 58ᵃ</span>, a. fr. <span dir=\"rtl\">געו בב׳</span> they sobbed loudly.</div>","alt":["בְּכִייָּה"]},"4242":{"h":"בִּכְיוּתָא","r":"B00785","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. I Gen. XXXV, 8</span>; (II ib. <a href=\"#\" data-headword=\"בָּכוּתָא\">בְּכוּתָא</a>), v. <a href=\"#\" data-headword=\"בְּכִיתָא\">בְּכִיתָא</a></div>","alt":[]},"4243":{"h":"בְּכִייָּה","r":"B00786","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּכִיָּה\">בְּכִיָּה</a></div>","alt":[]},"4244":{"h":"*בַּכְיָין","r":"B00787","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּכִייָּה\">preced. ws.</a>) <i>weeper</i>. <span class=\"citation\">Targ. Esth. II, 21</span> (Esth. R. ib. <a href=\"#\" data-headword=\"בַּרְבָּרִי\">בַּרְבָּרִי</a>).</div>","alt":["בַּכְיָן"]},"4245":{"h":"בְּכֵין","r":"B00788","html":"<div class=\"sense\"><i>then</i>, v. <a href=\"#\" data-headword=\"כֵּן\">כֵּן</a>.</div>","alt":[]},"4246":{"h":"בַּכִּיר","r":"B00789","html":"<p class=\"morphology\">m.</p><div class=\"sense\">a ch. (b. h. <span dir=\"rtl\">בַּכֻּרָה</span>; <span dir=\"rtl\">בכר</span>) <i>early, first-ripening</i>, opp. <span dir=\"rtl\">לקיש</span> or <span dir=\"rtl\">אפיל</span>. <span class=\"citation\">Snh. 18ᵇ</span> <span dir=\"rtl\">אם ב׳ ולקיש וכ׳</span> when the early and the late seeds blossom simultaneously &amp;c.; Y. ib. I, 18ᶜ bot.; Y. R. Hash. I, 58ᵇ bot. (corr. acc.). <span class=\"citation\">Gen. R. s. 61</span>; <span class=\"citation\">Koh. R. to XI, 6</span> (ref. to Koh. ib.) <span dir=\"rtl\">אם זרעת בב׳</span> if thou hast sown in the early season. Ib. <span dir=\"rtl\">הב׳</span> the early seed. Ib. to VII, 26 <span dir=\"rtl\">לקיש לסטים ב׳ וכ׳</span> (read <span dir=\"rtl\">ללס׳</span>) the latest of the robbers is the first to be hanged.—Fem. h. <span dir=\"rtl\">בַּכִּירָה</span>. <span class=\"citation\">Y. Taan. I, 64ᵃ</span> bot. <span dir=\"rtl\">הב׳ וכ׳</span> the early rain sets in on the third (of Marḥeshvan), v. <a href=\"#\" data-headword=\"בֵּינוֹנִי\">בֵּינוֹנִי</a>. [<span class=\"citation\">Y. Sot. III, 19ᵃ</span> top <span dir=\"rtl\">תאינה ב׳</span>, v. <a href=\"#\" data-headword=\"בִּכּוּרָה\">בִּכּוּרָה</a>.]—Pl. <span dir=\"rtl\">בַּכִּירוֹת</span>. Y. Dem. I, beg. 21ᶜ (<span class=\"citation\">Tosef. ib. I, 3</span> <span dir=\"rtl\">בִּכּוּרוֹת</span>). <span class=\"citation\">Y. R. Hash. I, 56ᵈ</span> top <span dir=\"rtl\">אלו הב׳</span> those are the early-bearing sheep; (<span class=\"citation\">Y. Shek. III, beg. 47ᵇ</span> <span dir=\"rtl\">הבכורות</span>, corr. acc.).</div>","alt":[]},"4247":{"h":"בְּכֵירוּתָא","r":"B00790","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"בְּכוֹרָה\">בְּכוֹרָה</a> 2). <span class=\"citation\">Targ. Gen. XXV, 31</span> (ed. Berl. <a href=\"#\" data-headword=\"בְּכוֹר\">בְּכוֹ׳</a>); a. fr.—<span class=\"citation\">Ber. 7ᵇ</span> <span dir=\"rtl\">זבנה לבכירותֵיה</span> (not <span dir=\"rtl\">זבניה</span>) he (Esaw) sold his birthright; <span class=\"citation\">ib.</span> <span dir=\"rtl\">שקלו בכירותיה מיניה ויהביה ליוסף</span> Ms. M. (read <span dir=\"rtl\">ויהבוה</span>; ed. incorr.) his (Reuben’s) birthright was taken from him and given to Joseph (v. Rabb. D. S. a. l. note). <span class=\"citation\">Sot. 13ᵃ</span> <span dir=\"rtl\">נהי דזביני לבכירותי וכ׳</span> though I sold my birthright, have I ever sold my plain heir’s right?</div>","alt":["בְּכֵרוּתָא"]},"4248":{"h":"בְּכִיתָא","r":"B00791","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <span dir=\"rtl\">בָּכוּת</span>, <span dir=\"rtl\">בָּכִית</span>) <i>weeping, mourning</i>. <span class=\"citation\">Targ. Gen. L, 4</span>. <span class=\"citation\">Targ. Deut. XXXIV, 8</span> (Y. <span dir=\"rtl\">בכותא</span>); a. e.—<span class=\"citation\">Gen. R. s. 15</span>, end, Ar. (missing in ed.); Pesik. Ronni p. 142ᵇ; v. <a href=\"#\" data-headword=\"*אַלְיָתָא\">אַלְיָתָא</a>.</div>","alt":["(בָּכוּתָא)"]},"4249":{"h":"בכלוספין","r":"B00792","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a></div>","alt":["בכלופסין"]},"4250":{"h":"בכנא","r":"B00793","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּכָנָא\">בּוּכָנָא</a></div>","alt":[]},"4251":{"h":"בָּכַר","r":"B00794","html":"<div class=\"sense\"> [<i>to break forth,</i>] <i>to be early</i>. [Kal prob. not used.]</div><div class=\"sense\"><b>Pi. בִּיכֵּר</b> <div class=\"sense\"><b>1)</b> <i>to be early, produce first fruits</i>. Tanḥ. Vayḥi 14; <span class=\"citation\">Gen. R. s. 99</span> <span dir=\"rtl\">מְבַכֶּרֶת</span> (<span dir=\"rtl\">פירותיה</span>) has early crops, opp. <span dir=\"rtl\">מלקשת</span>, <span dir=\"rtl\">מאפלת</span>. [Ib. end <span dir=\"rtl\">מבכרין מפירותיהם</span> read <span dir=\"rtl\">מכבדין</span>, v. <a href=\"#\" data-headword=\"כָּבֵד I\">כָּבַד</a>.]</div><div class=\"sense\"><b>—2)</b> <i>to bear for the first time</i> (of animals). <span class=\"citation\">Bekh. I, 3</span> sq. <span dir=\"rtl\">שלא בִיכְּרָה</span> that never before had given birth; a. fr.</div><div class=\"sense\"><b>—3)</b>  (neut. v.) <i>to be first in ripening.</i> <span class=\"citation\">Bicc. III, 1</span> and sees <span dir=\"rtl\">תאנה שבִּכְּרָה</span> a fig which is first ripe, <span dir=\"rtl\">אשכול שביכר</span> a cluster of grapes which &amp;c. Y. Maasr. I, 49ᵃ top <span dir=\"rtl\">משיְבַכֵּר צמייא וכ׳</span>, v. <a href=\"#\" data-headword=\"צַמְיָיא\">צמייא</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">משבִּיכֵּירוּ בנות שבע</span>, v. <a href=\"#\" data-headword=\"בַּר II\">בְּרַת</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בִּיכֵּירוּ</span>, <span dir=\"rtl\">משיְבַכְּרוּ</span> (v. <a href=\"#\" data-headword=\"בָּחַל I\">בָּחַל</a> as to spelling).</div><div class=\"sense\"><b>—4)</b>  (b. h.) <i>to recognize as first-born</i> <a href=\"#\" data-headword=\"בְּכוֹר\">(בכור</a>). <span class=\"citation\">B. Bath. 130ᵃ</span> sq.</div></div><div class=\"sense\"><b>Hif. הִבְכִּיר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"בכנא\">same</a>. <span class=\"citation\">Bekh. III, 2</span> <span dir=\"rtl\">המַבְכִּירוֹת</span> those animals which have given birth for the first time.</div></div><div class=\"sense\"><b>Hithpa. הִתְבַּכֵּר</b> <div class=\"sense\"><i>tohasten</i>. <span class=\"citation\">Yalk. Gen. 161</span> <span dir=\"rtl\">שהיא מִתְבַּכֶּרֶת בפירותיה</span>, v. supra.</div></div>","alt":[]},"4252":{"h":"בְּכַר","r":"B00795","html":"<div class=\"sense\">—<i>Pa</i>. <a href=\"#\" data-headword=\"בַּכִּיר\">בַּכִּר</a> </div><div class=\"sense\"><b>1)</b> <i>to produce, mature</i>. <span class=\"citation\">Targ. Y. Deut. XXXIII, 14</span> <span dir=\"rtl\">דמְבַכְּרָא וכ׳</span> which his land produces.</div><div class=\"sense\"><b>—2)</b> <i>to recognize as first-born</i>. <span class=\"citation\">Targ. O. Deut. XXI, 16</span>.</div><div class=\"sense\"><b>Ithpa. אִתְבַּכֵּר</b> <div class=\"sense\"><i>to be dedicated as the first-born</i>. <span class=\"citation\">Targ. O. Lev. XXVII, 26</span>.</div></div>","alt":[]},"4253":{"h":"בִּכְרָא","r":"B00796","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּכְרָא I\"><span dir=\"rtl\">בּוּכְרָא</span> I</a>, 2.</div>","alt":[]},"4254":{"h":"בֻּכְרָא","r":"B00797","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּךְ\">בּוּכְ׳</a></div>","alt":[]},"4255":{"h":"בְּכֵרוּתָא","r":"B00798","html":"<div class=\"sense\">, v. <span dir=\"rtl\">בְּכֵיר׳</span></div>","alt":[]},"4256":{"h":"בַּכַּרְיָא","r":"B00799","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בּוּכַּרְיָא\">בּוּכַּרְיָא</a></div>","alt":[]},"4257":{"h":"בַּל","r":"B00800","html":"<div class=\"sense\"> , v. Ges. H. Dict. s. v.) <i>not</i>, frequ. used, in connection with a verb, in the sense of <i>a prohibitive law</i>. <span class=\"citation\">Erub. 100ᵃ</span> <span dir=\"rtl\">עובר על בל תגרע</span> he transgresses the law which says ‘thou shalt not diminish therefrom’ (<span class=\"citation\">Deut. XIII, 1</span>). <span class=\"citation\">Pes. III, 3</span> <span dir=\"rtl\">שמוזהרים עליו בבל יראה וכ׳</span> concerning which we are cautioned by the law prohibiting leavened things to be seen or to be found (<span class=\"citation\">Ex. XIII, 7</span>; <span class=\"citation\">XII, 19</span>); a. v. fr. [Our w. is also applied to Bible texts in which <a href=\"#\" data-headword=\"לֹא\">לֹא</a> appears.]</div>","alt":[]},"4258":{"h":"בֵּל","r":"B00801","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Bel</i>, the Babylonian deity. <span class=\"citation\">Ab. Zar. 11ᵇ</span> <span dir=\"rtl\">בית ב׳ בבבל</span> the temple of Bel in Babylon.</div>","alt":[]},"4259":{"h":"*בָּל","r":"B00802","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">בהל</span>, cmp. <a href=\"#\" data-headword=\"בָּאלֵי\">בָּאלֵי</a>) <i>care, anxiety.</i> <span class=\"citation\">Dan. VI, 15</span>.</div>","alt":[]},"4260":{"h":"בָּלָא","r":"B00803","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּאלָא\">בָּאלָא</a></div>","alt":[]},"4261":{"h":"בַּלָּא","r":"B00804","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>destroyer</i>, v. <a href=\"#\" data-headword=\"בִּלְעָם\">בִּלְעָם</a>.</div>","alt":[]},"4262":{"h":"בְּלָא","r":"B00805","html":"<div class=\"sense\"><i>to be worn out</i>, v. <a href=\"#\" data-headword=\"בְּלֵי I\">בְּלֵי</a>.</div>","alt":[]},"4263":{"h":"בְּלֹא","r":"B00806","html":"<div class=\"sense\"><i>without</i>, v. <a href=\"#\" data-headword=\"לֹא\">לֹא</a>, <a href=\"#\" data-headword=\"לָא I\"><a href=\"#\" data-headword=\"לָא I\">לָא</a>.</a></div>","alt":["בְּלָא"]},"4264":{"h":"בְּלָאוֹת","r":"B00807","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (of <a href=\"#\" data-headword=\"בְּלֵי I\">בְּלָי</a>; <a href=\"#\" data-headword=\"בלי\">בלי</a>) <i>outworn garments</i>. <span class=\"citation\">Keth. V, 8</span> <span dir=\"rtl\">מתכסה בבְלָאוֹתֵיהֶן וכ׳</span> she wears her winter clothes in their outworn condition in the summer. <span class=\"citation\">Ib. 65ᵇ</span> <span dir=\"rtl\">מותר ב׳</span> the entirely outworn clothes (= <span dir=\"rtl\">שחקים</span> Mish. l. c.); a. fr.—2) <i>the woman’s right to claim compensation for the wear or ruin of the things which she brought along as her property</i> (v. <a href=\"#\" data-headword=\"מְלוֹג\">מלוג</a>, a. <span dir=\"rtl\">צאן ברזל</span>). <span class=\"citation\">Yeb. X, 1</span> <span dir=\"rtl\">ולא ב׳ …</span> nor can she claim compensation for used or spent property (but may take the things in what condition they are, v. comment.). <span class=\"citation\">Keth. XI, 6</span>.—[Y. ib. V, 30ᵇ bot.; XI, 34ᵃ bot., as in Mish. <span class=\"citation\">ib. XI, 7</span> <span dir=\"rtl\">בליות</span>.]</div>","alt":["בְּלָיוֹת"]},"4265":{"h":"בלאי","r":"B00808","html":"<div class=\"sense\">, <span class=\"citation\">Ned. 91ᵇ</span> Ar., read with ed. <a href=\"#\" data-headword=\"כְּלָאֵי\">כְּלָאֵי</a>.</div>","alt":[]},"4266":{"h":"בְּלָאֵי","r":"B00809","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>those of</i> (the family or town of) <i>Bela</i>, in Babylon, (prob. a nickname). <span class=\"citation\">Kidd. 70ᵇ</span>; v. <a href=\"#\" data-headword=\"טְלָאֵי I\">טְלָאֵי</a>.</div>","alt":[]},"4267":{"h":"בְּלָאִים","r":"B00810","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"בְּלָאוֹת\">בְּלָאוֹת</a>) <i>fragments, rags</i>. <span class=\"citation\">Succ. 15ᵇ</span> sq. <span dir=\"rtl\">בְּלָאֵי כלים</span> torn pieces of garments. <span class=\"citation\">Ib. V, 3</span>; a. e.—<span class=\"citation\">Ḥull. 107ᵇ</span> <span dir=\"rtl\">בלאי חמתות</span> fragments of wine bags.—<span class=\"citation\">Kel. XXVII, 5</span> <span dir=\"rtl\">בְּלוֹיֵי נפה וכ׳</span> (leather) pieces from a winnow or sieve.</div>","alt":["בְּלוֹיִים"]},"4268":{"h":"בְּלָאִין","r":"B00811","html":"<div class=\"sense\"><span class=\"citation\">Targ. Jer. XXXVIII, 11</span>; a. e.</div>","alt":[]},"4269":{"h":"בלארי","r":"B00812","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלְנְרִין\">בַּלְנְרִין</a></div>","alt":[]},"4270":{"h":"בלבוטס","r":"B00813","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"בּוּלֶבְטֵס\">בּוּלֶבְטֵס</a>.</div>","alt":[]},"4271":{"h":"בִּלְבֵּל","r":"B00814","html":"<div class=\"sense\"> (Pilp. of <a href=\"#\" data-headword=\"בָּלַל\">בלל</a> or <a href=\"#\" data-headword=\"בִּיל\">בול</a>; cmp. <span dir=\"rtl\">בהל</span>) <i>to mix up; to disarrange, upset, disturb</i>. <span class=\"citation\">Bekh. 38ᵇ</span> (expl. <span dir=\"rtl\">תבלל</span>, <span class=\"citation\">Lev. XXI, 20</span>) <span dir=\"rtl\">דבר המבלבל וכ׳</span> something which disturbs the arrangement (of the white and the black) of the eye. <span class=\"citation\">Snh. 108ᵃ</span> <span dir=\"rtl\">עמד ובלבל את וכ׳</span> (Var. <span dir=\"rtl\">ופזר</span>) he upset the bridal canopy. <span class=\"citation\">Sot. 46ᵇ</span> <span dir=\"rtl\">לא בִילְבְּלָהּ</span> did not disturb the town (by pillaging, removing the inhabitants &amp;c.). <span class=\"citation\">Y. B. Kam. IV, end, 4ᶜ</span> one struck him fatally <span dir=\"rtl\">ובא השני ובִילְבְּלוֹ</span> and the other came and made him senseless (accelerating his death).—Part. pass. <span dir=\"rtl\">מְבוּלְבָּל</span>, f. <span dir=\"rtl\">מְבוּלְבֶּלֶת</span>. <span class=\"citation\">Succ. 22ᵃ</span> <span dir=\"rtl\">סוכה מב׳</span> a festive booth the covering of which is disarranged, v. <span dir=\"rtl\">דָּבַל</span>. [<span class=\"citation\">Pesik. R. s. 4</span> <span dir=\"rtl\">נתבלבל</span>, v. <a href=\"#\" data-headword=\"כִּלְכֵּל\">כִּלְכֵּל</a>.]</div>","alt":["בִּילְבֵּל"]},"4272":{"h":"בַּלְבֵּל","r":"B00815","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XI, 9</span>. <span class=\"citation\">Targ. Is. XXVIII, 28</span> <span dir=\"rtl\">ומְבַלְבֵּל</span> and mixes up (the grain with the chaff, h. text <a href=\"#\" data-headword=\"הָמַם\">המם</a>); a. e.—Part. pass. <span dir=\"rtl\">מְבַלְבַּל</span>. <span class=\"citation\">Bekh. 44ᵃ</span> <span dir=\"rtl\">משום דמְבַלְבְּלָן</span> because they (the white and the black of the eye) are mixed up, v. preced.—Denom. <a href=\"#\" data-headword=\"מְבַלְבְּלִיתָא\">מְבַלְבְּלִיתָא</a> <i>mixture of white and black</i> (h. <span dir=\"rtl\">תְּבַלֻּל</span>, v. <a href=\"#\" data-headword=\"בִּלְבֵּל\">preced.</a>). <span class=\"citation\">Ibid.</span> (Ar. ed. pr. <span dir=\"rtl\">מברב׳</span>).</div><div class=\"sense\"><b>Ithpalp. אִיבַּלְבֵּל</b> <div class=\"sense\"><i>to be disturbed, mixed up</i>. <span class=\"citation\">Ḥull. 26ᵇ</span> <span dir=\"rtl\">מִיבַּלְבְּלֵי</span> they (water and wine) mix well. <span class=\"citation\">M. Kat. 9ᵇ</span> <span dir=\"rtl\">לִבַּלְבֵּל פתורם</span> thy table (meals) be disturbed (by the noise of children).</div></div>","alt":[]},"4273":{"h":"בלבסים","r":"B00816","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">לִבְסִים</a> a. <a href=\"#\" data-headword=\"כְּלוּפְסִין\"><a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a>.</a></div>","alt":["בלבסין"]},"4274":{"h":"בלבקיא","r":"B00817","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גְּלַבְקְיָא\">גְּלַבְקְיָא</a></div>","alt":["בלבקי"]},"4275":{"h":"*בלג","r":"B00818","html":"<div class=\"sense\">, <span class=\"citation\">Deut. R. s. 9</span> <span dir=\"rtl\">דעתו מובלגת</span>, read <span dir=\"rtl\">מוּבְהֶלֶת</span>, v. <a href=\"#\" data-headword=\"בָּהַל\">בָּהַל</a>, end.</div>","alt":[]},"4276":{"h":"בִּלְגָּה","r":"B00819","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּילְגָּה\">בִּילְגָּה</a></div>","alt":[]},"4277":{"h":"*בלגי","r":"B00820","html":"<div class=\"sense\">, <span class=\"citation\">Yoma 83ᵇ</span> <span dir=\"rtl\">אהדרוהו ב׳ וצעי</span> ed. (Ms. M. 1 <a href=\"#\" data-headword=\"פְּלָאגֵי\">פלאגי</a>; <span class=\"citation\">2</span> a. Ar. <span dir=\"rtl\">פלוגי</span>; Ms. Oxf., <span class=\"citation\">Yalk. Deut. 959</span> Ms. <span dir=\"rtl\">לגי</span>, v. Rabb. D. S. a. l. note), take <a href=\"#\" data-headword=\"ב\">ב</a> as servile letter, v. <a href=\"#\" data-headword=\"לוּגָּא\">לוּגָּא</a>.</div>","alt":[]},"4278":{"h":"בַּלְדָּר","r":"B00821","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (veredarius, βερεδάριος, with change of liquida) <i>courier</i>. <span class=\"citation\">Y. Taan. IV, 68ᶜ</span> bot. <span dir=\"rtl\">ביום ולילה נפק בלדרה וכ׳</span> could the courier go in one day and night from Jerusalem to Tyre? <span class=\"citation\">Gen. R. s. 10</span>. <span class=\"citation\">Gen. R. s. 78</span>; a. e.—Pl. <span dir=\"rtl\">בּוּלְּדָּרִין</span>, <span dir=\"rtl\">בּוּלְדָּארִין</span>. <span class=\"citation\">Esth. R. to I, 8</span> <span dir=\"rtl\">הכתבים והב׳</span> (strike out either of the two, v. Pesik. Shek. p. 14ᵃ, <span class=\"citation\">Cant. R. to III, 4</span>). Ib. <span dir=\"rtl\">ושלח בולדארין והחזיר וכ׳</span> and sent couriers (after them) and had the letters brought back.</div>","alt":["בּוּלְדָּר"]},"4279":{"h":"בַּלְדַּרְסִין","r":"B00822","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (a corrupt. of Brundisii, Βρεντέσιον) <i>Brundisium</i>, a port in Calabria, Italy. <span class=\"citation\">Erub. IV, 1</span> (<span class=\"citation\">41ᵃ</span>); 43ᵃ Ms. M. (ed. <a href=\"#\" data-headword=\"פְּלַנְדִּיסִין\">פלנדרסין</a>, Var. <a href=\"#\" data-headword=\"פְּלַנְדִּיסִין\">פלנדסין</a>, <a href=\"#\" data-headword=\"פְּרַנְדְּסִין\">פרנדסין</a>, <a href=\"#\" data-headword=\"פְּלַנְדִּיסִין\">פלנדיסין</a>, <span dir=\"rtl\">פרדיסין</span>; v. Rabb. D. S. a. l. notes). Cmp. <a href=\"#\" data-headword=\"בַּרְדְּסִין\">בַּרְדְּסִין</a>.</div>","alt":[]},"4280":{"h":"בָּלָה","r":"B00823","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בלי\">בלי</a></div>","alt":[]},"4281":{"h":"בְּלוֹ","r":"B00824","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a tax</i> (cmp. Assyr. <i>biltu</i>, v. Schr. KAT Gloss. II, s. v. <span dir=\"rtl\">ובל</span>). <span class=\"citation\">Ezra IV, 13</span>; a. e.—<span class=\"citation\">B. Bath. 8ᵃ</span> expl. <i>capitation tax;</i> <span class=\"citation\">Ned. 62ᵇ</span>. <span class=\"citation\">Gen. R. s. 64</span>; Esth. R. introd., v. <a href=\"#\" data-headword=\"פרובגירון\">פרובגירון</a>.</div>","alt":[]},"4282":{"h":"*(?)בַּלְוָוטִי","r":"B00825","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Balvati</i>. <span class=\"citation\">Arakh. 11ᵃ</span></div>","alt":[]},"4283":{"h":"*בְּלוּזְמָא","r":"B00826","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בלזם</span> = <span dir=\"rtl\">בלסס</span>, <span dir=\"rtl\">בסם</span>) <i>drinking of spiced wines</i>, whence (cmp. <a href=\"#\" data-headword=\"בָּסֵם\">בָּסַם</a>) <i>frolic, carousal</i>.—Pl. <span dir=\"rtl\">בְּלוּזְמָאוֹת</span>. <span class=\"citation\">Lev. R. s. 12</span> <span dir=\"rtl\">והיו שם שתי ב׳</span> (<span class=\"citation\">Yalk. Jer. 320</span> <a href=\"#\" data-headword=\"בלזמיות\">בלזמיות</a>) two excessive rejoicings took place at the same time. [<span class=\"citation\">Num. R. s. 10</span> a. <span class=\"citation\">Midr. Prov. to ch. XI</span> have <a href=\"#\" data-headword=\"צְהָלָה\">צהלה</a>.]</div>","alt":[]},"4284":{"h":"בָּלוּט","r":"B00827","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בלט</span>) </div><div class=\"sense\"><b>1)</b> <i>acorn, nut</i>.—Pl. <span dir=\"rtl\">בְּלוּטִים</span>, <span dir=\"rtl\">בְּלוּטִין</span>. <span class=\"citation\">Men. 63ᵃ</span> בְּלוּטֵי היונים Grecian nuts (nut-ben; v. Sm. Ant. s. v. Balanus).</div><div class=\"sense\"><b>—2)</b> <i>oak.</i> <i> Pl.</i> as above. <span class=\"citation\">Y. Keth. VII, end, 31ᵈ</span>; <span class=\"citation\">Gen. R. s. 15</span>, expl. <span dir=\"rtl\">אַלֹּונִים</span> (v. <a href=\"#\" data-headword=\"בְּלוּט\">next w.</a>)</div><div class=\"sense\"><b>—3)</b>  (v. Sm. Ant. s. v. Porta) <i>peg placed in the door-bars</i> when quite home in the socket. <span class=\"citation\">Pesik. R. s. 6</span> if the gate-bars were wanting <span dir=\"rtl\">ב׳ אחד</span> only one peg.—<i>Pl.</i> as above. Ibid.</div><div class=\"sense\"><b>—4)</b> <i>key-bit</i>. Y. Sabb. VIII, 11ᵇ bot. <a href=\"#\" data-headword=\"כלוט\">כלוט</a> (corr. acc.); v. <a href=\"#\" data-headword=\"חָף\">חָף</a>.</div>","alt":[]},"4285":{"h":"בְּלוּט","r":"B00828","html":"<div class=\"sense\">, <i>oak</i>. <span class=\"citation\">Targ. Y. II, Gen. XXXV, 8</span> (h. text <a href=\"#\" data-headword=\"אַלֹּון I\">אַלֹּון</a>); a. e.—Pl. <span dir=\"rtl\">בְּלוּטִין</span>, <span dir=\"rtl\">בְּלוּטֵי</span>.—<span class=\"citation\">Targ. Ezek. XXVII, 6</span>.—<span class=\"citation\">R. Hash. 23ᵃ</span> Ar. (ed. <span dir=\"rtl\">בוטמי</span> a. <span dir=\"rtl\">בלוטי</span> transposed; v. <a href=\"#\" data-headword=\"בּוּטְמָא\">בּוּטְמָא</a>); <span class=\"citation\">B. Bath. 80ᵇ</span></div>","alt":["בְּלוּטָא"]},"4286":{"h":"בְּלוֹיִים","r":"B00829","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּלָאִים\">בְּלָאִים</a></div>","alt":[]},"4287":{"h":"בָּלוּל","r":"B00830","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּלַל\">בלל</a>) </div><div class=\"sense\"><b>1)</b> <i>mixed up</i>, v. <a href=\"#\" data-headword=\"בָּלַל\">בָּלַל</a>.</div><div class=\"sense\"><b>—2)</b> <i>cloudy</i>. <span class=\"citation\">B. Bath. 147ᵃ</span>, v. <a href=\"#\" data-headword=\"בָּרוּר\">בָּרוּר</a>.</div>","alt":[]},"4288":{"h":"בלולין","r":"B00831","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לוּל\">לוּל</a></div>","alt":[]},"4289":{"h":"בְּלוֹנְיָא","r":"B00832","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בִּלְיוֹנָא\">בִּלְיוֹנָא</a></div>","alt":[]},"4290":{"h":"בלוניא","r":"B00833","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to I, 10</span>; <span class=\"citation\">Yalk. Cant. 983</span> <a href=\"#\" data-headword=\"כלוניא\">כלוניא</a>, <a href=\"#\" data-headword=\"כלוניא\">כלונייס</a>, read <a href=\"#\" data-headword=\"כְּלִינְסָא\">כְּלִינְיָא</a>, v. <a href=\"#\" data-headword=\"לִינְיָא\">לִינְיָא</a> a. <a href=\"#\" data-headword=\"חָרַז\"><a href=\"#\" data-headword=\"חָרַז\">חָרַז</a>.</a></div>","alt":[]},"4291":{"h":"*בְּלוּנְקֵי","r":"B00834","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">בי אלונקי</span>, v. <a href=\"#\" data-headword=\"*אֲלַנְקֵי\">אֲלַנְקֵי</a>) <i>poles for carrying burdens to market;</i> cmp. <a href=\"#\" data-headword=\"אוּנְקְלַי I\"><span dir=\"rtl\">אוּנְקְלַי</span> I</a>, 2.—<span class=\"citation\">Y. Dem. II, 22ᶜ</span> bot. <span dir=\"rtl\">בלוקח מן הב׳</span> when buying from the retailer’s stand, opp. <span dir=\"rtl\">מן הגינה</span> directly from the garden.</div>","alt":[]},"4292":{"h":"בלוסא","r":"B00835","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּלְסָא\">בּוּלְסָא</a></div>","alt":[]},"4293":{"h":"בלוספין","r":"B00836","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a></div>","alt":[]},"4294":{"h":"בְּלוּעָה","r":"B00837","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בלע</span>, v. <a href=\"#\" data-headword=\"בְּלִיעֵי\">בְּלִיעֵי</a>) <i>vortex, gulf</i>. <span class=\"citation\">Snh. 108ᵃ</span> <span dir=\"rtl\">ב׳ דגדר</span> (Ms. O. <span dir=\"rtl\">בְּלִיעָה דגדור</span>, v. Rabb. D. S. a. l. note 300) the gulf of G.</div>","alt":[]},"4295":{"h":"בלופסין","r":"B00838","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a></div>","alt":[]},"4296":{"h":"בלורי","r":"B00839","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלְנְרִין\">בַּלְנְרִין</a></div>","alt":[]},"4297":{"h":"בְּלוּרְיָא","r":"B00840","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>B’luria</i> (Valeria). <span class=\"citation\">R. Hash. 17ᵇ</span>, a proselyte. Cmp. <a href=\"#\" data-headword=\"בְּרוּרְיָא\">בְּרוּרְיָא</a>.</div>","alt":[]},"4298":{"h":"בְּלוּרִיֹּות","r":"B00841","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 28</span>; Yalk. Zeph. 566, v. <a href=\"#\" data-headword=\"בְּלוּרִית\">בְּלוּרִית</a></div>","alt":["בְּלֵרִיֹּות"]},"4299":{"h":"*בלורין","r":"B00842","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"בַּלְנְרִין\">בַּלְנְרִין</a> f. (balnearia) <i>bath-house</i>. <span class=\"citation\">Gen. R. s. 8</span>; <span class=\"citation\">Yalk. Gen. 13</span> <span dir=\"rtl\">וראה ב׳ אחת מושלכ׳</span> saw a bath-house cast down.—[<span class=\"citation\">Ab. Zar. 18ᵇ</span>, v. <a href=\"#\" data-headword=\"*בלרין\">בלרין</a>.]</div>","alt":["בולרין"]},"4300":{"h":"בְּלוּרִית","r":"B00843","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בלר</span>, √<span dir=\"rtl\">בל</span>, v. <a href=\"#\" data-headword=\"בָּלַל\">בלל</a>) <i>something twisted</i>, whence </div><div class=\"sense\"><b>1)</b> <i>chain, rope</i> or <i>wreath</i> (v. P. Sm. I, 532 <span dir=\"rtl\">בלורא</span> = h. <span dir=\"rtl\">מעשה מקשה</span>, a. <a href=\"#\" data-headword=\"בְּלוּרְיָא\">בלוריא</a> vincula jugi).—Pl. <a href=\"#\" data-headword=\"בְּלוּרִיֹּות\">בְּלוּרִיּוֹת</a>. <span class=\"citation\">Gen. R. s. 28</span>; Yalk. Zeph. 566 <span dir=\"rtl\">ב׳ של זהב</span> (Gen. R. l. c. some ed. <a href=\"#\" data-headword=\"בְּלוּרִיֹּות\">בְּלֵרִיֹּות</a>) thick gold chains (as translation of <a href=\"#\" data-headword=\"יֶתֶר I\">יתר</a>, <span class=\"citation\">Job XXII, 20</span>).</div><div class=\"sense\"><b>—2)</b> <i>plait</i> or <i>locks</i>, esp. the long hair worn by the Roman and Greek youths of the upper classes and offered to the gods on arriving at puberty (v. Sm. Ant. s. v. κόμη). <span class=\"citation\">Ab. Zar. I, 3</span> <span dir=\"rtl\">יום תגלחת זקנו ובלוריתוֹ</span> the day of shaving his (the gentile’s) beard and cutting his locks (v. Maim. a. l.). Ib. 29ᵃ. <span class=\"citation\">Tosef. Sabb. VI</span> (<span class=\"citation\">VII), 1</span>. <span class=\"citation\">Deut. R. s. 2</span> <span dir=\"rtl\">העושה ב׳ וכ׳</span> he who grows a wig does so for none but an idolatrous purpose. <span class=\"citation\">Lev. R. s. 23</span>; a. fr.—<span class=\"citation\">Snh. 82ᵃ</span> <span dir=\"rtl\">תפשה בבלוריתָהּ</span> he seized her by her plait.</div>","alt":[]},"4301":{"h":"בְּלוֹרִיתָא","r":"B00844","html":"<div class=\"sense\">, <i>woman’s plait</i>. <span class=\"citation\">Targ. Y. I Num. XXV, 6</span> (ref. to <span class=\"citation\">Snh. 82ᵃ</span>, v. <a href=\"#\" data-headword=\"בְּלוּרִית\">preced.</a>).</div>","alt":[]},"4302":{"h":"בְּלוּשָׁא","r":"B00845","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בלש</span>) <i>search, examination</i>. <span class=\"citation\">Targ. Ps. LXIV, 7</span>.</div>","alt":[]},"4303":{"h":"בָּלוֹשָׁא","r":"B00846","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלְשָׁא\">בַּלְשָׁא</a>, <a href=\"#\" data-headword=\"בַּלֶּשֶׁת\"><a href=\"#\" data-headword=\"בַּלֶּשֶׁת\">בַּלֶּשֶׁת</a>.</a></div>","alt":["בָּלוֹשֶׁת"]},"4304":{"h":"בלזמיות","r":"B00847","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בְּלוּזְמָא\">בְּלוּזְמָא</a></div>","alt":[]},"4305":{"h":"*בָּלַח","r":"B00848","html":"<div class=\"sense\"> (cmp. b. h. <span dir=\"rtl\">בלה</span> in <span dir=\"rtl\">בַּלָּהָה</span>, a. <a href=\"#\" data-headword=\"בָּחַל I\">בָּחַל</a>), <i>Hif.</i> הִבְלִיחַ <i>to be unsteady, dazzle</i>. <span class=\"citation\">Y. Pes. I, beg. 27ᵃ</span></div>","alt":[]},"4306":{"h":"בִּלְחוֹד","r":"B00849","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לְחוֹד\">לְחוֹד</a></div>","alt":[]},"4307":{"h":"בָּלַט","r":"B00850","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בל</span>, v. <a href=\"#\" data-headword=\"בָּלַל\">בָּלַל</a>; cmp. <span dir=\"rtl\">פלט</span>, <span dir=\"rtl\">מלט</span>, <span dir=\"rtl\">ולד</span>; cmp. Assyr. <span dir=\"rtl\">בלט</span> <i>to live</i>, Schr. KAT gloss. I, II) </div><div class=\"sense\"><b>1)</b>  (neut. v.) <i>to stand forth, project; to be cut in relief</i>, opp. <span dir=\"rtl\">שקע</span> to sink, be engraven. <span class=\"citation\">R. Hash. 24ᵇ</span> טבעת שחותמה בֹּולֵט Ms. M. (ed. incorr.) a ring whose seal is cut in relief; <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> bot. <span class=\"citation\">Gitt. 20ᵃ</span> sq. <span class=\"citation\">Sot. III, 4</span> <span dir=\"rtl\">עיניה בוֹלְטוֹת</span> her eyes protruded; <span class=\"citation\">Num. R. s. 9</span>.—<span class=\"citation\">Yoma 54ᵃ</span> <span dir=\"rtl\">דוחקין ובולטין</span> pressing forth and protruding (from behind the curtain); a. fr.</div><div class=\"sense\"><b>—2)</b>  (act. v.) <i>to drive forth, beat</i>. <span class=\"citation\">Y. Sabb. XII, 13ᵈ</span> <span dir=\"rtl\">בבולט מקום הכתב וכ׳</span> when he beats out the place of writing, opp. <span dir=\"rtl\">חוקק</span>.</div>","alt":[]},"4308":{"h":"בְּלַט","r":"B00851","html":"<div class=\"sense\">Part. pass. <span dir=\"rtl\">בָּלִיט</span>. <span class=\"citation\">Targ. II Chr. V, 9</span>. <span class=\"citation\">Ḥull. 45ᵇ</span> <span dir=\"rtl\">בְּלִיטָן</span>, <span class=\"citation\">ib. 76ᵃ</span> <span dir=\"rtl\">בְּלִיטֵי</span> protruding sinews, opp. <span dir=\"rtl\">בלועי</span> sunk in the flesh, indistinguishable.</div>","alt":[]},"4309":{"h":"בלטוורא","r":"B00852","html":"<div class=\"sense\">, read <span dir=\"rtl\">בַּבֹּושָׁרוֹת</span>. <span class=\"citation\">Cant. R. to II, 15</span> <span dir=\"rtl\">קיניגין מכללה ודיארטיה עתידים מן ב׳ דא דיחתו וייטורד זה שטיחם אחריהם</span>, read, acc. to intimation in comment. Mat. K., as follows: <span dir=\"rtl\">קיניגין ותייטרן הה&quot;ד מוציא אסירים בכשרות ואח&quot;כ התייטרון זה שנ׳ הבאים אחריהם בים</span> (the passage through the Red Sea and the coming of the noble Egyptians afterwards was) like the order of the kynegion (the actors in the fights of the arena) and the theatron (the spectators), as it says (<span class=\"citation\">Ps. LXVIII, 7</span>), ‘He leadeth forth the captives with their outfits’, and then come the spectators, as we read (<span class=\"citation\">Ex. XIV, 28</span>), ‘who came after them into the Sea.’</div>","alt":[]},"4310":{"h":"בלי","r":"B00853","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ned. III, 38ᵃ</span> top, v. <a href=\"#\" data-headword=\"*בריכסון\">בריכסון</a>.—Pesik. Baḥod. p. 107ᵇ, v. <a href=\"#\" data-headword=\"כִּילִי\">כִּילִי</a>.</div>","alt":[]},"4311":{"h":"בלי ²","r":"B00854","html":"<div class=\"sense\"> , v. <a href=\"#\" data-headword=\"בָּלַל\">בלל</a>; cmp. <a href=\"#\" data-headword=\"נָבָל I\">נבל</a>) <i>to be crumbled; to be worn out, to fail, decay, perish</i>. <span class=\"citation\">Koh. R. to I, 4</span> <span dir=\"rtl\">הוא בוֹלֶה</span> it (the generation of man) decays (dies out), <span dir=\"rtl\">אינה בוֹלָה</span> it (the earth) does not grow old. <span class=\"citation\">Taan. 9ᵃ</span> (play on <span dir=\"rtl\">עד בלי די</span> <span class=\"citation\">Mal. III, 10</span>) <span dir=\"rtl\">עד שיִבְלוּ שפתותיכם מלומר די</span> until your lips grow tired from saying, It is enough; (Y. ib. III, 66ᵈ bot. <span dir=\"rtl\">שיבללו</span>, v. <a href=\"#\" data-headword=\"בָּלַל\">בָּלַל</a>); a. fr.—Part. pass. <a href=\"#\" data-headword=\"בָּלוּל\">בָּלוּי</a> <i>outworn</i>. Pl. <a href=\"#\" data-headword=\"בְּלוֹיִים\">בְּלוּיִים</a>. <span class=\"citation\">Midr. Till. to Ps. XXV, 1</span>.</div><div class=\"sense\"><b>Pi. בִּלָּה</b> <div class=\"sense\"><i>to wear out, outlive, survive</i>. <span class=\"citation\">Lev. R. s. 4</span> <span dir=\"rtl\">הנפש מְבַלָּה וכ׳</span> the soul survives the body. <span class=\"citation\">Lev. R. s. 19</span> (play on <span dir=\"rtl\">אין בלתך</span>, <span class=\"citation\">I Sam. II, 2</span>) <span dir=\"rtl\">אין לְבַלֹּותֶךָ</span> there is none to outlive thee. Koh. R. l. c.; <span class=\"citation\">Cant. R. to V, 15</span> one erects a building <span dir=\"rtl\">ואחר מְבַלֶּה אותו</span> (not <span dir=\"rtl\">מכלה</span>) and another man ruins it. <span class=\"citation\">Snh. 105ᵃ</span>, v. <a href=\"#\" data-headword=\"בִּלְעָם\">בִּלְעָם</a>.</div></div><div class=\"sense\"><b>Nif. נִבְלָה</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִתְבַּלָּה</span> <i>to become outworn, fade away</i>. Esth. R. introd. <span dir=\"rtl\">עתידין לְהִבָּלוֹת</span> (<span class=\"citation\">Gen. R. s. 42</span> <span dir=\"rtl\">לִבְלוֹת</span>) are destined to decay. <span class=\"citation\">Deut. R. s. 7</span>, end <span dir=\"rtl\">נִתְבַּלּוּ</span> (the garments) were worn out. <span class=\"citation\">B. Mets. 87ᵃ</span> <span dir=\"rtl\">נ׳ הבשר</span> her body was withered. <span class=\"citation\">B. Bath. 146ᵃ</span> <span dir=\"rtl\">עשויין לִיבָּלוֹת</span> made to be used up.</div></div>","alt":["בָּלָה"]},"4312":{"h":"בְּלֵי I","r":"B00855","html":"<div class=\"sense\"><span class=\"citation\">Targ. Deut. VIII, 4</span>; <span class=\"citation\">Targ. Y. Deut. XXIX, 4</span> <span dir=\"rtl\">בלמו</span>, Var. <span dir=\"rtl\">כלמו</span>, read <span dir=\"rtl\">בלת</span>; a. fr.—<span class=\"citation\">Lev. R. s. 19</span> <span dir=\"rtl\">כולו בלה</span> all goes to ruin. <span class=\"citation\">Ber. 5ᵇ</span>, v. <a href=\"#\" data-headword=\"בְּכָא\">בְּכָא</a>. <span class=\"citation\">Ib. 6ᵃ</span>. <span class=\"citation\">Bekh. 9ᵃ</span> <span dir=\"rtl\">ובלו להו ואזול</span> they failed and went to destruction. <span class=\"citation\">Ab. V, 22</span> <span dir=\"rtl\">סיב ובְלֵה בה</span> grow old and frail in it (the study of the Law).—[<span class=\"citation\">Targ. Ps. LXII, 11</span>; <span class=\"citation\">XCI, 2</span> Ms., v. <span dir=\"rtl\">כְּלִי I</span>.]</div><div class=\"sense\"><b>Pa. בַּלֵּי</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"בלי ²\">preced.</a> <i>Pi.</i>—<span class=\"citation\">Targ. Is. III, 15</span>; a. e.—<span class=\"citation\">Ab. Zar. 20ᵃ</span> that this beauty <span dir=\"rtl\">ב׳ עפרא</span> dust will destroy.—Part. pass. f. <span dir=\"rtl\">מְבַלְּיָא</span>. <span class=\"citation\">Lev. R. s. 33</span> (interpret. <span dir=\"rtl\">בלה נאפים</span> <span class=\"citation\">Ezek. XXIII, 43</span>) Aquila translates παλαιὰ πόρνη (old harlot), <span dir=\"rtl\">דהוא מבליא גייארא</span> ed. (Ar. <span dir=\"rtl\">דהיא מב׳ גיירייא</span>, Yalk. Dan. 1061 only <span dir=\"rtl\">דהיא מבליא</span>) which means, a wasted harlot (wasted through fornication).</div></div>","alt":["בְּלָא","בְּלָה"]},"4313":{"h":"*בְּלֵי II","r":"B00856","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> constr. (<a href=\"#\" data-headword=\"בְּלֵי I\">preced.</a>, cmp. <a href=\"#\" data-headword=\"בְּלָאוֹת\">בְּלָאוֹת</a>, <a href=\"#\" data-headword=\"בְּלוֹיִים\">בְּלוֹיִים</a>) <i>rotten pieces of</i> (wood). <span class=\"citation\">Targ. Is. XLIV, 19</span> (h. text <a href=\"#\" data-headword=\"בִּיל\">בּוּל</a>, v. Rashi a. l.; Var. <span dir=\"rtl\">יִבְלֵי</span>).</div>","alt":[]},"4314":{"h":"בְּלִי","r":"B00857","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"*בְּלֵי II\">preced. ws.</a>) prop. <i>destruction, naught; not;</i> v. <a href=\"#\" data-headword=\"בְּלִימָה\">בְּלִימָה</a>. <span class=\"citation\">Ber. 44ᵇ</span> <span dir=\"rtl\">מב׳ בשר</span> if without meat.</div>","alt":[]},"4315":{"h":"בליוטוס","r":"B00858","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּלֶבְטֵס\">בּוּלֶבְטֵס</a></div>","alt":[]},"4316":{"h":"*בִּלְיוֹנָא","r":"B00859","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בלי\">בלי</a>, formed like <a href=\"#\" data-headword=\"בִּזְיוֹנָא\">בזיונא</a>) [<i>destruction</i>,] a cacophem. for idolatrous <i>phylactery, amulet</i> (v. Sm. Ant. s. v. Amuletum). <span dir=\"rtl\">ב׳ דגושפנקא</span> (Ar. <a href=\"#\" data-headword=\"בילוניא\">בילוניא</a>) <i>an amulet</i> (<i>stone</i>) <i>set in a ring</i>. <span class=\"citation\">Gitt. 57ᵃ</span> <span dir=\"rtl\">עד דמתחזי ב׳ וכ׳</span> so that the stone of a ring could be distinguished (as to shape, legend &amp;c.) at a distance of a mile (from the illuminated town). <span class=\"citation\">Ib. 58ᵃ</span> <span dir=\"rtl\">נקטי ב׳ וכ׳</span> (Yalk. Lam. 1242 <a href=\"#\" data-headword=\"כיליינא\">כיליינא</a>, <a href=\"#\" data-headword=\"כּוֹלְיָא\">כול׳</a>) they took an amulet (believed to effect the begetting of healthy and handsome children).</div>","alt":["בִּילְיוֹנָא"]},"4317":{"h":"בְּלָיוֹת","r":"B00860","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּלָאוֹת\">בְּלָאוֹת</a></div>","alt":[]},"4318":{"h":"בְּלִיָּיתָא","r":"B00861","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּלִיתָא\">בְּלִיתָא</a></div>","alt":[]},"4319":{"h":"בְּלִילָה","r":"B00862","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּלַל\">בלל</a>, v. <a href=\"#\" data-headword=\"בִּילָה\">בִּילָה</a>) <i>mixing, mixture</i>. <span class=\"citation\">Y. Maas. Sh. II, 53ᶜ</span>; <span class=\"citation\">Y. Dem. V, 24ᵈ</span> top <span dir=\"rtl\">אין ב׳ אלא וכ׳</span> b’lilah (an even distribution) applies only to wine or oil. <span class=\"citation\">Men. III, 2</span> <span dir=\"rtl\">זו בְּלִילָתָהּ עבה וכ׳</span> the one forms a thick mixture (one <i>Log</i> of oil to one <i>Issaron</i> of flour), the other forms a loose mixture (three Log to one <i>Issaron</i>).—Pl. <span dir=\"rtl\">בְּלִילוֹת</span>. <span class=\"citation\">Tosef. Dem. II, 7</span>; <span class=\"citation\">Men. 18ᵇ</span>; <span class=\"citation\">Ḥull. 132ᵇ</span> <span dir=\"rtl\">הב׳</span> the priest’s mixing the offerings (<span class=\"citation\">Lev. II, 5</span>; a. fr.).</div>","alt":[]},"4320":{"h":"בְּלִים","r":"B00863","html":"<div class=\"sense\"> part. pass. of <a href=\"#\" data-headword=\"בְּלַם\">בְּלַם</a>.</div>","alt":[]},"4321":{"h":"בְּלִימָה","r":"B00864","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"בְּלִי\">בְּלִי</a>) [<i>nothing</i>,] <i>air</i> (fr. <span class=\"citation\">Job XXVI, 7</span>). <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">עשר ספירות ב׳</span> (some ed. <a href=\"#\" data-headword=\"בְּלִימָה\">בלי מה</a>) the ten heavenly spheres (cmp. Sepher Yetsir. beg.). <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">על אויר העולם על ב׳ …</span> he rested it (the upper story, the sky) on the atmosphere, on b’limah (Tanḥ. Ḥaye 3 <span dir=\"rtl\">על מה על האויר</span>).</div>","alt":["(בְּלִי מָה)"]},"4322":{"h":"בלינוס","r":"B00865","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 42</span>, read <a href=\"#\" data-headword=\"כָּלִינוֹס\">כָּלִינוֹס</a>.</div>","alt":[]},"4323":{"h":"בַּלִּינֵי","r":"B00866","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלְנֵי\">בַּלְנֵי</a></div>","alt":[]},"4324":{"h":"בלינירין","r":"B00867","html":"<div class=\"sense\">, <span class=\"citation\">Y. Snh. X, 29ᵃ</span> top, read <a href=\"#\" data-headword=\"כְּלִינִידִין\">כְּלִינִידִין</a>.</div>","alt":[]},"4325":{"h":"בליסטורי","r":"B00868","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלִּיסְטָרִי\">בַּלִּיסְטָרִי</a></div>","alt":[]},"4326":{"h":"בליסטין","r":"B00869","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to II, 14</span>, read <span dir=\"rtl\">כלִיסְטִין</span>; cmp. <span class=\"citation\">Ex. R. s. 21</span>.</div>","alt":[]},"4327":{"h":"בַּלִּיסְטְרָא","r":"B00870","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ballistra, βάλιστρα) <i>catapult, a war engine for throwing stones</i>, or (b. manualis) <i>for arrows</i>. <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">אבני ב׳</span> stones thrown from the catapult. <span class=\"citation\">Y. Sot. VIII, 22ᵇ</span> bot. <span dir=\"rtl\">ברד כנגד בליצטורא שלהן</span>; (Mekh. Bshall. s. 2 <span dir=\"rtl\">בלסטראות</span>, pl.; <span class=\"citation\">Yalk. Ex. 232</span> <span dir=\"rtl\">בלסיטראות</span>, read <span dir=\"rtl\">בליסט׳</span>) the hail stones correspond to the catapults in the warfare of men. <span class=\"citation\">Pesik. R. s. 17</span>; Pesik. Vayhi p. 67ᵃ <span dir=\"rtl\">אבני בלסתרא</span> (corr. acc.). <span class=\"citation\">Pesik. R. s. 29—30</span> (p. 139ᵇ ed. Fr.) <span dir=\"rtl\">את האבן בליסטרה</span> (read <span dir=\"rtl\">אבן הבל׳</span>). Lam. R. introd. (R. <span class=\"citation\">Josh. 2</span>) <span dir=\"rtl\">אבני בליסטרוס</span> (read … <span dir=\"rtl\">רא</span>); a. fr.—Pl. <span dir=\"rtl\">בַּלִּיסְטְרָאוֹת</span>. Yalk. l. c., v. supra. Tanḥ. Bo 4; Shof’tim 14. Mekh. l. c. <span class=\"citation\">Midr. Till. to Ps. XVIII</span>.</div>","alt":["(בליצטרא)"]},"4328":{"h":"בַּלִּיסְטָרִי","r":"B00871","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ballistarius, βαλιστάριος) <i>attendant of the catapult</i>, also <i>archer</i>. <span class=\"citation\">Ḥull. 60ᵇ</span> <span dir=\"rtl\">או ב׳ היה …</span> was Moses a hunter or an archer (to have known the nature of animals so well)?</div>","alt":["(בליסטורי)"]},"4329":{"h":"בליספימיא","r":"B00872","html":"<div class=\"sense\">, v. <span dir=\"rtl\">בְּלַסְפֵ׳</span></div>","alt":[]},"4330":{"h":"בְּלִיעָה","r":"B00873","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בלע</span>) </div><div class=\"sense\"><b>1)</b> <i>swallowing, gluttony</i>. <span class=\"citation\">Num. R. s. 14</span> (play on <a href=\"#\" data-headword=\"בֶּלַע\">בֶּלַע</a> <span class=\"citation\">Gen. XXXVI, 32</span>) he sold his birthright <span dir=\"rtl\">בשביל בְּלִיעָתוֹ</span> to satisfy his gluttony.—בית הב׳ <i>œsophagus</i>. <span class=\"citation\">Toh. I, 1</span>; a. fr.—2) <i>vortex</i>, v. <a href=\"#\" data-headword=\"בְּלוּעָה\">בְּלוּעָה</a>.</div>","alt":[]},"4331":{"h":"בְּלִיעֵי","r":"B00874","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <span dir=\"rtl\">בית הבליעה</span>, v. <a href=\"#\" data-headword=\"בְּלִיעָה\">preced.</a>) <i>gullet</i>, whence (cmp. <a href=\"#\" data-headword=\"וֶשֶׁט\">וֶשֶׁט</a>) <i>straits</i> (prob. <i>Scylla and Charybdis</i>). <span class=\"citation\">Bekh. 9ᵃ</span>.—Snh. 110ᶜ <span dir=\"rtl\">בלועי דקרח</span> (corr. acc.) the chasm created for Korah.</div>","alt":["בֵּי בְּ׳"]},"4332":{"h":"בְּלִיַּעַל","r":"B00875","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>availing nothing, wickedness</i>. <span class=\"citation\">Snh. 111ᵇ</span> (playing on <a href=\"#\" data-headword=\"עוֹל\">עוֹל</a>) <a href=\"#\" data-headword=\"בְּרַק II\">בני ב׳</a> means <span dir=\"rtl\">בנים … עול וכ׳</span></div>","alt":[]},"4333":{"h":"בְּלִיעֲתָא","r":"B00876","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"בְּלִיעָה\">בְּלִיעָה</a>) <i>swallowing</i>, <span class=\"citation\">Targ. Y. I Num. XXVI, 11</span>, constr. <a href=\"#\" data-headword=\"בְּלִיעָה\">בְּלִיעַת</a>.</div>","alt":[]},"4334":{"h":"בליצטורא","r":"B00877","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלִּיסְטְרָא\">בַּלִּיסְטְרָא</a></div>","alt":["בליצטרא"]},"4335":{"h":"בליקוס","r":"B00878","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְקִיס\">כַּלְקִיס</a></div>","alt":[]},"4336":{"h":"בְּלִיתָא","r":"B00879","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בלי\">בלי</a>) <i>rag, shred</i>. <span class=\"citation\">Sabb. 134ᵃ</span>. <span class=\"citation\">Ḥull. 8ᵇ</span> <span dir=\"rtl\">ב׳ דפרסא</span> a shred of a curtain (soft rag). <span class=\"citation\">Kidd. 48ᵇ</span> <span dir=\"rtl\">צייר בב׳</span> tied up in a rag.—Pl. <a href=\"#\" data-headword=\"בְּלִיָּיתָא\">בְּלִיָּיתָא</a>. <span class=\"citation\">Yeb. 120ᵃ</span> (some ed. <a href=\"#\" data-headword=\"בְּלִיתָא\">בליתא</a>).</div>","alt":[]},"4337":{"h":"בָּלַל","r":"B00880","html":"<div class=\"sense\"> sec. r. of <a href=\"#\" data-headword=\"בִּיל\">בול</a>, <span dir=\"rtl\">ביל</span>; √<a href=\"#\" data-headword=\"בּוֹ\">בו</a>, <span dir=\"rtl\">בה</span>, cmp. <a href=\"#\" data-headword=\"בִּין\">בִּין</a>, <i>to penetrate, break through</i>, v. <span dir=\"rtl\">בלט</span>; b) √בל <i>to crumble, soften</i>, cmp. √<span dir=\"rtl\">מל</span>; v. <a href=\"#\" data-headword=\"בלי\">בלי</a>, <a href=\"#\" data-headword=\"נָבָל I\">נבל</a>, <span dir=\"rtl\">בלט</span> in <a href=\"#\" data-headword=\"בּוּלְטִיתָא\">בולטיתא</a>) <i>to mix</i> (with oil), <i>knead, stir; to mix fodder</i>. <span class=\"citation\">Zeb. XIV, 3</span> (<span class=\"citation\">112ᵇ</span>) <span dir=\"rtl\">הבּוֹלֵל</span> the priest who kneads the meat-offering with oil, v. <a href=\"#\" data-headword=\"בְּלִילָה\">בְּלִילָה</a>. <span class=\"citation\">Dem. V, 5</span> <span dir=\"rtl\">בולל ונוטל</span> (strike out <span dir=\"rtl\">ואוכל</span> in Bab. ed., Ar. Var. <span dir=\"rtl\">בורר</span>) he mixes the fruits and takes the tithe. <span class=\"citation\">Y. B. Kam. IV, beg. 4ᵃ</span> <span dir=\"rtl\">לִבְלוֹל</span> to mix up (coins in a bag.) <span class=\"citation\">Y. R. Hash. I, 56ᵈ</span> bot.; Tanḥ. Noah 11, v. <a href=\"#\" data-headword=\"בּוּל III\"><span dir=\"rtl\">בּוּל</span> III</a>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"בָּלוּל\">בָּלוּל</a>, f. <a href=\"#\" data-headword=\"בְּתוּלָה\">בְּלוּלָה</a>. <span class=\"citation\">Snh. 24ᵃ</span> (play on <a href=\"#\" data-headword=\"בָּבֶל\">בבל</a>) <span dir=\"rtl\">ב׳ במקרא וכ׳</span> mixed up (confused) in Bible study &amp;c. [<span class=\"citation\">Y. Yeb. VIII, end, 9ᵈ</span> <span dir=\"rtl\">קריבה בבלל</span>, read <span dir=\"rtl\">בכָלִיל</span>.] V. <a href=\"#\" data-headword=\"בָּלוּל\">בָּלוּל</a>.</div><div class=\"sense\"><b>Nif. נִבְלַל</b> <div class=\"sense\">, <i>Hof.</i> הוּבְלָל <i>to be mixed</i>. Y. Maas. Sh. II, 53ᶜ, v. <a href=\"#\" data-headword=\"חָפַן\">חָפַן</a>. <span class=\"citation\">Men. XII, 4</span> (<span class=\"citation\">103ᵇ</span>; <span class=\"citation\">18ᵇ</span>) <span dir=\"rtl\">ששים נבללין</span> sixty measures of flour can be thoroughly mixed; v. <a href=\"#\" data-headword=\"בִּילָה\">בִּילָה</a>. Ib. <span dir=\"rtl\">יכולים לְהִבָּלֵל</span>.—Y. Shek. VI, 49ᵈ bot. <span dir=\"rtl\">אש מוּבְלָלָה באש</span> fire mixed with fire.—[Y. Taan. III, 66ᵈ bot. <span dir=\"rtl\">עד שיִבָּלֲלוּ וכ׳</span> until your speech shall become confounded from repeatedly saying, Enough; v. <a href=\"#\" data-headword=\"בלי\">בלי</a>.] Y. Ber. VI, 10ᵃ top (play on <a href=\"#\" data-headword=\"בַּל\">בַּל</a>) <span dir=\"rtl\">יִבָּלֲלוּ וכ׳</span> all blessings shall be kneaded thogether—<i>Pilp</i>. <a href=\"#\" data-headword=\"בִּלְבֵּל\">בִּלְבֵּל</a>.</div></div>","alt":[]},"4338":{"h":"בָּלַם I","r":"B00881","html":"<div class=\"sense\"> , <i>fodder-bag, nose-bag, muzzle</i>)<i> to muzzle, restrain</i>. <span class=\"citation\">Yalk. Num. 743</span> (read in place of <span dir=\"rtl\">כדו בלום וכ׳</span>:) <span dir=\"rtl\">פיו בָּלוּם לעמו של משה יכול הוא לִבְלוֹם צפורנו של אחד מהם</span> the mouth of the people of Moses is tied up (we dare not talk), but can he tie up (disable) the nail of any of them (the Canaanites)? <span class=\"citation\">Ḥull. 89ᵃ</span> (play on <a href=\"#\" data-headword=\"בְּלִימָה\">בלימה</a>, <span class=\"citation\">Job XXVI, 7</span>) <span dir=\"rtl\">שבּוֹלֵם וכ׳</span> who restrains himself in strife (refrains from violence, keeps silence &amp;c.).—2) part. pass. <a href=\"#\" data-headword=\"בָּלוּל\">בָּלוּם</a> (cmp. <a href=\"#\" data-headword=\"אִלֵּם\">אִלֵּם</a>) <i>unfit for use, lame, sore, swollen, closed by a tumor</i>. <span class=\"citation\">Bekh. 40ᵇ</span> <span dir=\"rtl\">פיו ב׳</span> one whose mouth is swollen (one opin. in Rashi: <i>shrunk</i>); <span dir=\"rtl\">רגליו מְבוּלָּמוֹת</span> (Pu.) one whose feet are swollen (shrunk). Ib. 43ᵇ חוטמו ב׳ Ar. (ed. <span dir=\"rtl\">בולם</span>, corr. acc.) whose nose is obstructed.—<span class=\"citation\">Gitt. 67ᵃ</span> <span dir=\"rtl\">אוצר ב׳</span> a packed treasury of knowledge; v. <a href=\"#\" data-headword=\"בָּלַס\">בָּלַס</a>.—<i>Part. Pu.</i> <a href=\"#\" data-headword=\"מְפוּלָּם\">מְבוּלָּם</a>, v. supra.</div><div class=\"sense\"><b>*. הִבְלִים</b> <div class=\"sense\"><i>to restrict</i> … Y. Ḥag. II, 78ᵃ bot. <span dir=\"rtl\">ובלבד שיַבְלִים לעיסתו</span> provided that (when cutting &amp;c.) he does only as much as is needed for his dough for the offering; [Tosaf. to <span class=\"citation\">Ḥag. 17ᵇ</span>, s. v. <a href=\"#\" data-headword=\"אֲלָא I\">אלא</a>, cites <span dir=\"rtl\">שיכלה עיסתו</span>, v. <a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a>.]</div></div>","alt":[]},"4339":{"h":"בָּלַם II","r":"B00882","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בָּלַם I\">preced.</a>; cmp. Syr. <a href=\"#\" data-headword=\"*בְּלָמָא\">בלמא</a> <i>halter</i>) <i>to attempt to get rid of the halter; to kick, strike</i> (of an unruly horse). Pesik. Zakh. p. 24ᵇ (ref. to <span class=\"citation\">Ps. XXXII, 9</span>) thou puttest a bit on him <span dir=\"rtl\">והוא בוֹלֵם</span> and he strikes. Ib. <span dir=\"rtl\">קריב לגביה והוא ב׳</span> (strike out <a href=\"#\" data-headword=\"לֹא\">לא</a>, as Tanḥ. ed. Bub. Ki Thetse, 6 a. <span class=\"citation\">Yalk. Ps. 719</span>) you come near him and he strikes; Tanḥ. Ki Thetse, 6; <span class=\"citation\">Yalk. Deut. 938</span>, Ps. l. c. (with var. vers.).</div>","alt":[]},"4340":{"h":"בְּלַם","r":"B00883","html":"<div class=\"sense\"> I.</div><div class=\"sense\"><b>—1)</b>  Part. pass. <a href=\"#\" data-headword=\"בְּלִים\">בְּלִים</a> <i>tied, mute</i>. <span class=\"citation\">Targ. Is. XXXII, 4</span>; a. e. [<span class=\"citation\">Targ. Y. Deut. XXIX, 4</span>; v. <a href=\"#\" data-headword=\"בְּלֵי I\"><span dir=\"rtl\">בְּלֵי</span> I</a>.]</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כְּרַךְ I\">כרך</a>) <i>to put meat between bread, wrap up</i>. <span class=\"citation\">Ḥull. 107ᵇ</span> <span dir=\"rtl\">ב׳ ליה אומצא</span> wrapped up a piece of meat for him (v. Tosaf. a. l.).</div>","alt":[]},"4341":{"h":"*בְּלָמָא","r":"B00884","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּלַם\">preced.</a>; v. <a href=\"#\" data-headword=\"בָּלַם I\">בָּלַם</a>) <i>halter</i>, trnsf. <i>guard, protection of the borders of a field</i>, as fences &amp;c.; cmp. <a href=\"#\" data-headword=\"אַפְסָרָא\">אַפְסָרָא</a>. <span class=\"citation\">B. Mets. 103ᵇ</span> <span dir=\"rtl\">כל עיקר ב׳ וכ׳</span> whatever is essential for guarding the limits, the landlord must provide. [Ms. M. <span dir=\"rtl\">כלומ׳</span>, Ar. <span dir=\"rtl\">כלמי</span>, v. <a href=\"#\" data-headword=\"*כְּלָמָא\">כְּלָמָא</a>.]</div>","alt":[]},"4342":{"h":"בַּלָּן","r":"B00885","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (βαλανεύς) <i>bathing master, bathing attendant</i> (who receives a small coin as fee, cmp. <a href=\"#\" data-headword=\"אוֹלְיָאר\">אוֹלְיָיר</a>). <span class=\"citation\">Shebi. VIII, 5</span>; v. <a href=\"#\" data-headword=\"בַּיָּיר\">בַּיָּיר</a>. <span class=\"citation\">Y. B. Bath. IV, 14ᶜ</span> bot. <span dir=\"rtl\">מקום הב׳</span> the bathing master’s station (the income therefrom); a. fr.—Pl. <span dir=\"rtl\">כַּלָּנִין</span>. <span class=\"citation\">Sabb. IV, 2</span> <span dir=\"rtl\">קורות הב׳</span> the beams whereon the bathing masters are stationed.</div>","alt":["בַּלָּנִי"]},"4343":{"h":"בַּלַּן","r":"B00886","html":"<div class=\"sense\"><span class=\"citation\">Lev. R. s. 28</span> <span dir=\"rtl\">אזל בדיל ב׳</span> he went after a bather. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אתעביד ב׳ וספר</span> has become a bather and hair cutter; <span class=\"citation\">Esth. R. to VI, 10</span> <span dir=\"rtl\">(בלן</span>); <span class=\"citation\">Pesik. R. s. 18</span>.</div>","alt":["בַּלָּנָא","בַּלְנַאי","בַּלְנַי"]},"4344":{"h":"בלנטיא","r":"B00887","html":"<div class=\"sense\">, Sifra B’har Par. 5, ch. VII (<span class=\"citation\">Yalk. Lev. 666</span> <span dir=\"rtl\">בגלטקא</span>), v. <a href=\"#\" data-headword=\"לֶקְטִיקָא\">לֶקְטִיקָא</a> a. <a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\">גְּלוּגְדְּקָא</a>.</div>","alt":[]},"4345":{"h":"בַּלָּנִי","r":"B00888","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלָּן\">בַּלָּן</a>, <a href=\"#\" data-headword=\"בַּלַּן\"><a href=\"#\" data-headword=\"בַּלַּן\">בַּלַּן</a>.</a></div>","alt":["בַּלְנַי"]},"4346":{"h":"בַּלְנֵי","r":"B00889","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (balnea, balineæ) <i>bath, bathing</i>. <span class=\"citation\">Y. Ber. VI, 10ᶜ</span> bot. <span dir=\"rtl\">כהדין דשתי חמרא בתר בילני</span> (read <span dir=\"rtl\">בליני</span>) as if one drinks wine after bathing (for medicinal purposes, when the wine which he drinks after meal cannot be considered as a continuation of the draught taken before meal; v. <a href=\"#\" data-headword=\"אֲלוּנְטִית II\"><span dir=\"rtl\">אֲלוּנְטִית</span> II</a>). <span class=\"citation\">Y. Maas. Sh. IV, 54ᵈ</span> bot. as much as one will ask (for the fruits left over) on a hot summer day <span dir=\"rtl\">בתר ב׳</span> after bathing time (when he is anxious to sell).—*Denom. <span dir=\"rtl\">בַּלָּנִיּוֹת</span> f. pl. (= balnearia) <i>bathing apparel.</i> <span class=\"citation\">B. Bath. IV, 5</span> (<span class=\"citation\">67ᵇ</span>, Bab. ed.) <span dir=\"rtl\">ואת הב׳</span> (Var. <a href=\"#\" data-headword=\"וִילָאוֹת\">וִילָאוֹת</a> q. v.).</div>","alt":["בַּלִּינֵי"]},"4347":{"h":"בלנידיא","r":"B00890","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. VI, 8ᵇ</span> bot., transl. of <span dir=\"rtl\">רעלות</span> <span class=\"citation\">Is. III, 19</span>, read <a href=\"#\" data-headword=\"כְּלָנִידְיָיא\">כְּלָנִידְיָיא</a>.</div>","alt":[]},"4348":{"h":"בַּלְנְרִין","r":"B00891","html":"<div class=\"sense\"><b>1)</b>  constr. constr. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"בַּלְרֵי\">בַּלְרֵי</a>) <span dir=\"rtl\">בַּלְנְרֵי</span></span> m. pl. (balnearia) <i>bathing apparel, bathing utensils</i>. <span class=\"citation\">Y. Kil. IX, 32ᵃ</span> bot.; <span class=\"citation\">Y. M. Kat. III, 82ᵃ</span> <span dir=\"rtl\">ב׳ נשים</span> women’s bathing clothes; <span class=\"citation\">Sabb. 147ᵇ</span> <a href=\"#\" data-headword=\"בַּלְרֵי\">בלרי</a> (some ed. <a href=\"#\" data-headword=\"בלורי\">בלורי</a>, corr. <span dir=\"rtl\">בלנ׳</span>); <span class=\"citation\">Tosef. Kil. V, 16</span> <a href=\"#\" data-headword=\"בלארי\">בלארי</a> (corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>bath-house</i>, v. <a href=\"#\" data-headword=\"*בלורין\">בלורין</a>.—V. <a href=\"#\" data-headword=\"בַּנְּרִיּוֹת\">בַּנְּרִיּוֹת</a>.</div>","alt":["(בַּלְרִין)"]},"4349":{"h":"בָּלַס","r":"B00892","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בל</span>, v. <a href=\"#\" data-headword=\"בָּלַל\">בָּלַל</a>) </div><div class=\"sense\"><b>1)</b> <i>to mix with all sorts of things, to mix indiscriminately.</i> <i> Part. pass</i>. <span dir=\"rtl\">בָּלוּס</span>, f. <span dir=\"rtl\">בְּלוּסָה</span>. <span class=\"citation\">Sabb. 76ᵇ</span> <span dir=\"rtl\">עיסה ב׳</span> a dough of unsifted flour (with bran &amp;c.). <span class=\"citation\">B. Bath. 58ᵃ</span> <span dir=\"rtl\">אוצר ב׳</span> a store room of mixed things (lumber room).—<span class=\"citation\">Gitt. 67ᵃ</span> <span dir=\"rtl\">אוצר ב׳</span> a mind full of all kind of knowledge (oth. vers. <span dir=\"rtl\">בלום</span>, v. <a href=\"#\" data-headword=\"בָּלַם I\">בָּלַם</a>).—Pl. <span dir=\"rtl\">בְּלוּסִין</span>. <span class=\"citation\">Mikv. IX, 5</span> <span dir=\"rtl\">הב׳</span> utensils soaked with a mixture of colors (stains from use), opp. <span dir=\"rtl\">נקיים</span> shining, polished.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"בלי\">בלי</a>) <i>to rot</i>. <span class=\"citation\">Gen. R. s. 28</span> <span dir=\"rtl\">אוצרות בְּלוּסִים</span> store of spoiled fruits.</div>","alt":[]},"4350":{"h":"בלסימיה","r":"B00893","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּלַסְפֵימְיָא\">בְּלַסְפֵימְיָא</a></div>","alt":[]},"4351":{"h":"בַּלְסָם","r":"B00894","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בסם</span>, with inserted <a href=\"#\" data-headword=\"ל\">ל</a> = <a href=\"#\" data-headword=\"ר\">ר</a>; hence βάλσαμον which was readopted as <a href=\"#\" data-headword=\"בַּלְסָם\">בלסמון</a>; cmp. <a href=\"#\" data-headword=\"*בְּלוּזְמָא\">בְּלוּזְמָא</a>) <i>balsam, aromatic gum</i>. <span class=\"citation\">Gen. R. s. 91</span> (interpr. <a href=\"#\" data-headword=\"צְרֵי I\">צרי</a>) <span dir=\"rtl\">בלסם קטף</span> the gum of the balsam tree.—<span class=\"citation\">Targ. Cant. VII, 14</span>. <span class=\"citation\">Lev. R. s. 31</span>; <span class=\"citation\">Cant. R. to I, 15</span>; a. e. Cmp. <a href=\"#\" data-headword=\"פַּלְסְמוֹן\">פַּלְסְמוֹן</a> a. <a href=\"#\" data-headword=\"אַפַּרְסָמוֹן\">אַפַּרְסָמוֹן</a>.</div>","alt":["בַּלְסְמוֹן"]},"4352":{"h":"בְּלַסְפֵימְיָא","r":"B00895","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (βλασφημία) <i>blasphemy</i>. Y’lamd. to Num. XXVIII, quot. (<span dir=\"rtl\">בליספ׳</span>) in Ar.—Tanḥ. ed. Bub. Tol’doth 21 <a href=\"#\" data-headword=\"בלסימיה\">בלסימיה</a> (corr. acc.).</div>","alt":[]},"4353":{"h":"בְּלַסְפֵימִיסון","r":"B00896","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"בְּלַסְפֵימִיסון\">בְּלַסְפֵימֵיסִין</a> (ἐβλασφήμησεν) <i>he blasphemed</i>. Y’lamd., ref. to <span class=\"citation\">I Kings XXI, 13</span> quot. in Ar. (interpret. <a href=\"#\" data-headword=\"בָּרַךְ\">בֵּרַךְ</a>).</div>","alt":[]},"4354":{"h":"בלסתרא","r":"B00897","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלִּיסְטְרָא\">בַּלִּיסְטְרָא</a></div>","alt":[]},"4355":{"h":"בָּלַע","r":"B00898","html":"<div class=\"sense\"> , v. <a href=\"#\" data-headword=\"בָּלַל\">בלל</a>) <i>to absorb</i>, opp. <span dir=\"rtl\">פלט</span>; <i>to swallow, consume</i>. <span class=\"citation\">Y. Shek. VI, 49ᶜ</span> bot.… <span dir=\"rtl\">שהאור בּוֹלֵעַ בּוֹלַעַת … בּוֹלְעִין</span> the flame absorbs a portion of the oil, and so do the wood and the kettle. <span class=\"citation\">Ḥull. 110ᵇ</span> the liver when boiled with other meat <span dir=\"rtl\">פולטת ואינה ב׳</span> gives out (blood) but absorbs nothing from the other pieces. <span class=\"citation\">Y. Sabb. XIV, 14ᵈ</span> top; <span class=\"citation\">Tosef. Sabb. XII</span> (<span class=\"citation\">XIII), 9</span> but he may sip vinegar <span dir=\"rtl\">ובוֹלֵעַ</span> and swallow it (opp. <span dir=\"rtl\">פלט</span> to spit it out). <span class=\"citation\">Y. Ter. VIII, 45ᵇ</span> bot. <span dir=\"rtl\">הלעוס כבָלוּעַ</span> what is chewed is to be considered as swallowed. <span class=\"citation\">Ḥull. 71ᵃ</span> <span dir=\"rtl\">טומאה בְלוּעָה</span> an unclean object (food) that has been swallowed.—<span class=\"citation\">Snh. 110ᵃ</span> <span dir=\"rtl\">הַבְּלוּעִין</span> those (of the band of Korah) that were swallowed up. <span class=\"citation\">Kel. IX, 6</span>, v. <a href=\"#\" data-headword=\"דָּֽרְבָן\">דָּֽרְבָן</a>; a. fr.</div><div class=\"sense\"><b>Nif. נִבְלַע</b> <div class=\"sense\"><i>to be swallowed;</i> with <span dir=\"rtl\">בין</span>, <i>to be absorbed, disappear</i>. <span class=\"citation\">Sot. 36ᵇ</span>; Tanḥ. Vayigg. 4; <span class=\"citation\">Yalk. Gen. 150</span> (interpret. the name Bela, <span class=\"citation\">Gen. XLVI, 21</span>) <span dir=\"rtl\">שנ׳ בין האומות</span> for he (Joseph) has disappeared among gentiles. <span class=\"citation\">Gen. R. s. 94</span>; Yalk. l. c. <span dir=\"rtl\">שנבלע ממני</span> he disappeared to me.</div></div><div class=\"sense\"><b>Hif. הִבְלִיעַ</b> <div class=\"sense\"><i>to cause swallowing, to make absorb</i>. <span class=\"citation\">Ex. R. s. 33</span> <span dir=\"rtl\">הִבְלַעְתָּ לקרה</span> thou mad’st (the earth) swallow Korah. <span class=\"citation\">Ber. 24ᵇ</span> <span dir=\"rtl\">מַבְלִיעוֹ בטליתו</span> he hides the spittle in his cloak; Y. Sabb. VII, 10ᵇ top. <span class=\"citation\">Ḥull. 113ᵃ</span> <span dir=\"rtl\">מַבְ׳ דם באברים</span> causes the blood to remain in the meat (prevents it from flowing out).—Trnsf. <i>to sell something in connection with other things, in a lump, in the bargain</i>. <span class=\"citation\">Bekh. 31ᵇ</span> <span dir=\"rtl\">מבליעו וכ׳</span> he sells it (the meat) in the bargain with the hide &amp;c. <span class=\"citation\">B. Mets. 64ᵃ</span>; <span class=\"citation\">B. Kam. 118ᵇ</span> one who robs his neighbor <span dir=\"rtl\">וה׳ לו בחשבון</span> and makes up for it implicitly on settling his accounts. V. <a href=\"#\" data-headword=\"הַבְלָעָה\">הַבְלָעָה</a>.</div></div><div class=\"sense\"><b>Hof. הוּבְלַע</b> <div class=\"sense\"><i>to be swallowed up; to mingle with</i>, v. supra Nif.—Part. <span dir=\"rtl\">מוּבְלַע</span>. <span class=\"citation\">Ber. 31ᵇ</span> <span dir=\"rtl\">מ׳ בין אנשים</span> mixing with people, expl. <span dir=\"rtl\">לא ארוך וכ׳</span> neither very tall &amp;c. (of average qualities). <span class=\"citation\">Erub. IV, 6</span> <span dir=\"rtl\">מ׳ ביניהן</span> his property is enclosed between theirs (reaches into the limits of each). Y. ib. IV, 21ᵈ bot. <span dir=\"rtl\">עיירות המוּבְלָעוֹת</span> <i>inland-towns</i>, opp. border-towns. Y. B. Bath. VII, 15ᶜᵈ <span dir=\"rtl\">מוּבְלָעִין בה</span> fields which are enclosed by others belonging to the same estate.</div></div><div class=\"sense\"><b>Hithpa. הִתְבַּלֵעַ</b> <div class=\"sense\"><i>to be swallowed up, to disappear</i>. <span class=\"citation\">Midr. Till. to Ps. XIX</span>, beg. <span dir=\"rtl\">מִתְבַּלֵּעַ מן וכ׳</span> he disappears from the world (forfeits his life).</div></div>","alt":[]},"4356":{"h":"בְּלַע","r":"B00899","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. VII, 12</span>; a. fr.—<span class=\"citation\">Ḥull. 111ᵃ</span> <span dir=\"rtl\">כי היכי דפליט הדר ב׳</span> as it gives out, so does it again absorb; a. fr.—Part. pass. <a href=\"#\" data-headword=\"בְּלִיעָה\">בְּלִיעַ</a>, <a href=\"#\" data-headword=\"בְּלִיעָה\">בְּלִיעָא</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בליעא דמא</span> filled with blood.—<span class=\"citation\">Snh. 110ᵃ</span> <span dir=\"rtl\">בלועי דקרח</span>, v. <a href=\"#\" data-headword=\"בְּלִיעֵי\">בְּלִיעֵי</a>.— Trnsf. <i>to receive blows</i> (cmp. <a href=\"#\" data-headword=\"סָפַג\">סָפַג</a>). <span class=\"citation\">Men. 7ᵃ</span> קולפי טאבי בַּלְעִי וכ׳ I received many blows at the hands of Ab. over &amp;c. <span class=\"citation\">Arakh. 22ᵃ</span>. <span class=\"citation\">Ber. 56ᵃ</span>.—Targ. II, <span class=\"citation\">Esth. III, 7</span> <span dir=\"rtl\">בְּלִיעָן אינון בידי</span> they are swallowed up (bound to be destroyed) by my hand.</div><div class=\"sense\"><b>Af. אַבְלַע</b> <div class=\"sense\">, as h. Hif. <span class=\"citation\">Ḥull. 67ᵇ</span> <span dir=\"rtl\">אַבְלַע לי</span> let me swallow them (put them in my mouth). <span class=\"citation\">Men. 17ᵃ</span>, v. infra. <span class=\"citation\">B. Mets. 64ᵃ</span> <span dir=\"rtl\">וא׳ ליה בחשבון</span>, v. <a href=\"#\" data-headword=\"בָּלַע\">preced.</a> Hif.</div></div><div class=\"sense\"><b>Ithpe. אִיתְבְּלַע  אִיבְּלַע</b> <div class=\"sense\"> = as h. Nif. </div><div class=\"sense\"><b>1)</b> <i>to be swallowed up, to disappear</i>. <span class=\"citation\">Targ. Y. Gen. XLVI, 21</span> <span dir=\"rtl\">אתב׳ מניה</span> he was swallowed up (disappeared) from his side; v. <a href=\"#\" data-headword=\"בָּלַע\">preced.</a> <span class=\"citation\">Targ. Josh. VI, 5</span> <span dir=\"rtl\">יתבלע וכ׳</span> shall sink into the ground beneath it; a. e.—Y. R. Hash. II, 58ᵃ bot. <span dir=\"rtl\">איתב׳ מן קומוי</span> (the moon) disappeared from his sight.</div><div class=\"sense\"><b>—2)</b> <i>to be given to eat;</i> trnsf. <i>to be taught</i>. <span class=\"citation\">Ber. 24ᵇ</span> <span dir=\"rtl\">הא מילתא אִבְלְעָא לי בי וכ׳</span> v. Rabb. D. S. a. l. note) this I have been taught in the school of R. &amp;c.; (<span class=\"citation\">Men. 17ᵃ</span> <span dir=\"rtl\">הא מילתא אבלע לי וכ׳</span> this has R. Ḥ. taught me).</div></div>","alt":[]},"4357":{"h":"בֶּלַע","r":"B00900","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּלַע\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>absorption, natural loss, leakage</i>. <span class=\"citation\">B. Mets. III, 8</span> (<span class=\"citation\">40ᵃ</span>) <span dir=\"rtl\">לוג ומחצה ב׳</span> a <i>Log</i> and a half is a reasonable leakage (absorbed by new vessels); a. e.</div><div class=\"sense\"><b>—2)</b>  pr. n. m. (b. h.) <i>Bela;</i> v. <a href=\"#\" data-headword=\"בָּלַע\">בָּלַע</a> a. <a href=\"#\" data-headword=\"בְּלִיעָה\"><a href=\"#\" data-headword=\"בְּלִיעָה\">בְּלִיעָה</a>.</a></div><div class=\"sense\"><b>—3)</b>  <a href=\"#\" data-headword=\"בֶּלַע\">בֶּלַע</a> or <a href=\"#\" data-headword=\"בַּלָּע\">בַּלַּע</a> (cmp. <a href=\"#\" data-headword=\"בְּלִי\">בְּלִי</a>) <i>a nothing, a mote</i>. Tanḥ. Vayak. 7 (ref. to <span dir=\"rtl\">כְּבַלַּע</span> <span class=\"citation\">Num. IV, 20</span>) <span dir=\"rtl\">כב׳ הזה שהוא נופל בעין</span>; (<span class=\"citation\">Num. R. s. 5</span> <span dir=\"rtl\">מן העין</span>) as much as a mote which enters one’s eye.</div>","alt":[]},"4358":{"h":"בַּלָּע","r":"B00901","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>swallower, glutton</i>. <span class=\"citation\">Num. R. s. 14</span>; v. <a href=\"#\" data-headword=\"בְּלִיעָה\">בְּלִיעָה</a>. <span class=\"citation\">Snh. 105ᵃ</span>, v. <a href=\"#\" data-headword=\"בִּלְעָם\">בִּלְעָם</a>.</div>","alt":[]},"4359":{"h":"בְּלַע ²","r":"B00902","html":"<div class=\"sense\"> ch. m. (cmp. <a href=\"#\" data-headword=\"בֶּלַע\">בֶּלַע</a>) <i>the thing swallowed, choking fit</i>. <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> <span dir=\"rtl\">אהן בלעה שרי</span> in a choking attack it is allowed (to apply remedies on the Sabbath) Ib. <span dir=\"rtl\">הוה ליה בלע</span> had a choking fit; <span class=\"citation\">Koh. R. to X, 5</span> <span dir=\"rtl\">הוה ליה חד בלעא</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לאפקא בִלְעֵיה</span> to get out what he had swallowed.</div>","alt":["בְּלְעָא","בִּלְעָה"]},"4360":{"h":"בלעין","r":"B00903","html":"<div class=\"sense\">, <span class=\"citation\">Y. Dem. III, 23ᵇ</span> <span dir=\"rtl\">מחוסר לב׳</span>, read <span dir=\"rtl\">בְּעָלִין</span> = <span dir=\"rtl\">בְּעָלִים</span>, v. <a href=\"#\" data-headword=\"בַּעַל\">בַּעַל</a></div>","alt":[]},"4361":{"h":"בִּלְעָם","r":"B00904","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Balaam</i>, the gentile prophet of the Pentateuch. <span class=\"citation\">Snh. 105ᵃ</span> ב׳ בַּלַּע עם Ar. (Var. in Ar., a. ed. <a href=\"#\" data-headword=\"בַּלָּא\">בַּלָּא</a>) devourer (destroyer) of the people; other homilet. etymology ibid. <span dir=\"rtl\">שבִּלָּה עם</span> he ruined the people (through debauchery; Rashi: = <a href=\"#\" data-headword=\"בִּלְבֵּל\">בִּלְבֵּל</a>). <span class=\"citation\">Gen. R. s. 65</span>. <span class=\"citation\">Ab. V, 19</span> (as type of false teachers); a. fr.</div>","alt":[]},"4362":{"h":"בַּלְעֵס","r":"B00905","html":"<div class=\"sense\"> (<span dir=\"rtl\">בלע</span> with <a href=\"#\" data-headword=\"ס\">ס</a> intens.; cmp. <a href=\"#\" data-headword=\"בָּלַס\">בלס</a>, <span dir=\"rtl\">לעס</span>); <i>Ithpe.</i> אִתְבַּלְעֵס <i>to be choked, to choke</i>. Y. Ter. VIII, 46ᵃ <span dir=\"rtl\">ואיתכ׳</span>, <span dir=\"rtl\">ואיתכלעסון</span> (corr. acc.).</div>","alt":[]},"4363":{"h":"*בַּלְצָא","r":"B00906","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Baltsa</i>. <span class=\"citation\">Ex. R. s. 29</span> <span dir=\"rtl\">שאל ב׳ את ר׳ עקיבא</span> [prob. to be be read <span dir=\"rtl\">אל׳ ז&quot;ל</span> = <span dir=\"rtl\">אליהו ז&quot;ל</span>, cmp. Y. Ber. IX, 13ᶜ; <span class=\"citation\">Midr. Till. to Ps. XVIII</span>; <span class=\"citation\">CIV</span> end].</div>","alt":[]},"4364":{"h":"בִּלָּק","r":"B00907","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בִּילָּק\">בִּילָּק</a></div>","alt":[]},"4365":{"h":"בָּלָק","r":"B00908","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Balak</i>, King of Moab. <span class=\"citation\">Ber. 7ᵃ</span>. <span class=\"citation\">Num. R. s. 20</span>; a. fr.</div>","alt":[]},"4366":{"h":"בלקטורים","r":"B00909","html":"<div class=\"sense\"> …, v. <a href=\"#\" data-headword=\"*כּוֹלֶּקְטָר\">כּוֹלֶּקְטָר</a> (collectarius), and <a href=\"#\" data-headword=\"כַּלַּקְטֵירִין\">כַּלַּקְטֵירִין</a> (χαρακτῆρες).</div>","alt":["בלקטירין","רין"]},"4367":{"h":"בלקיא","r":"B00910","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גְּלַבְקְיָא\">גְּלַבְקְיָא</a></div>","alt":[]},"4368":{"h":"בלרא","r":"B00911","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוֹלְרָא\">בּוּלְרָא</a></div>","alt":[]},"4369":{"h":"בַּלְרֵי","r":"B00912","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלְנְרִין\">בַּלְנְרִין</a></div>","alt":[]},"4370":{"h":"בלריון","r":"B00913","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בלרין\">בלרין</a></div>","alt":[]},"4371":{"h":"בְּלֵרִיּוֹת","r":"B00914","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּלוּרִית\">בְּלוּרִית</a></div>","alt":[]},"4372":{"h":"*בלרין","r":"B00915","html":"<div class=\"sense\">, <span class=\"citation\">Ab. Zar. 18ᵇ</span> ב׳ ובלריון Ms. M. (ed. only <a href=\"#\" data-headword=\"*בלורין\">בלורין</a>; Y. ib. I, 40ᵃ <span dir=\"rtl\">מילרין מילריה</span>, added in Ms. M. l. c. as <span dir=\"rtl\">מלרין ומלריון</span>; <span class=\"citation\">Yalk. Ps. 613</span> <span dir=\"rtl\">בלרין ובלריין</span>) corruption of <span dir=\"rtl\">לִיבְּרָלִין</span> (liberales, sub. ludi, or liberalia) <i>Bacchanalian games</i> (v. Sm. Ant. s. v. Dionysia). [The preceding <a href=\"#\" data-headword=\"לוליון\">לוליון</a> or <a href=\"#\" data-headword=\"לוליון\">לולין</a> must prob. be read <span dir=\"rtl\">לודין</span> <i>ludi</i>.] V. <a href=\"#\" data-headword=\"סְגוּלָרִין\">סגולרין</a>.</div>","alt":[]},"4373":{"h":"בָּלַשׁ","r":"B00916","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בל</span>, v. <a href=\"#\" data-headword=\"בָּלַל\">בלל</a>) </div><div class=\"sense\"><b>1)</b>  *<i>to hack and break the clods of earth</i> (v. <a href=\"#\" data-headword=\"בּוּל II\"><span dir=\"rtl\">בּוּל</span> II</a>; v. Sm. Ant. s. v. Raster). <span class=\"citation\">Lev. R. s. 36</span> on setting a vine <span dir=\"rtl\">בּוֹלְשִׁין אותה וכ׳</span> (read <span dir=\"rtl\">אותן</span>) you first break them (the large stony clods) under it and then you plant it. Cmp. <a href=\"#\" data-headword=\"*אַבְלוֹשֵׁי\">אַבְלוֹשָׁא</a>.</div><div class=\"sense\"><b>—2)</b>  (law) <i>to search</i> (for concealed goods &amp;c.) <i>to hold a visitation</i>. Denom. <a href=\"#\" data-headword=\"בַּלְשִׁי\">בַּלְשִׁי</a></div><div class=\"sense\"><b>—3)</b>  (milit.) <i>to patrol.</i> <span class=\"citation\">Midd. I, 7</span> <span dir=\"rtl\">לִבְלוֹשׁ וכ׳</span> to patrol the Temple.</div>","alt":[]},"4374":{"h":"בְּלַשׁ","r":"B00917","html":"<div class=\"sense\">; <i>to search, examine</i>. <span class=\"citation\">Targ. O. Gen. XXXI, 35</span>; a. fr.</div><div class=\"sense\"><b>Pa. בַּלֵּשׁ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"בָּלַשׁ\">same</a>. <span class=\"citation\">Targ. Is. XXII, 5</span> <span dir=\"rtl\">מְבַלְּשִׁין</span> (ed. Vien. <span dir=\"rtl\">מַבְלְשִׁין</span> Af.); a. e.</div></div><div class=\"sense\"><b>Ithpa. אִתְבַּלַּשׁ</b> </div><div class=\"sense\"><b>Ithpe. אִתְבְּלִּישׁ</b> <div class=\"sense\"><i>to be searched, ransacked</i>. <span class=\"citation\">Targ. Ob. I, 6</span>, quot. <span class=\"citation\">B. Kam. 3ᵇ</span>; a. e.</div></div>","alt":[]},"4375":{"h":"בַּלְשָׁא","r":"B00918","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"בַּלְשִׁי\">next w.</a>) <i>searcher; constable</i>. <span class=\"citation\">Nidd. 52ᵃ</span> <span dir=\"rtl\">שדר ב׳ וכ׳</span> he sent a constable and forced her to leave her (second) husband.—Pl. <span dir=\"rtl\">בָּלוֹשִׁין</span>, <span dir=\"rtl\">בָּלוֹשַׁיָּיא</span>. <span class=\"citation\">Targ. Zeph. I, 12</span>; a. e.—<span class=\"citation\">Ber. 44ᵃ</span> בָּלוֹשֵׁי Ar. a. Ms. F. (ed. <a href=\"#\" data-headword=\"בָּאלוֹשָׁא\">בָּאלוֹשֵׁי</a>).</div>","alt":["בָּלוֹשָׁא"]},"4376":{"h":"בַּלְשִׁי","r":"B00919","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בלש</span>) <i>detective, investigator, searching tax-commissioner, constable</i>. <span class=\"citation\">Y. Dem. VII, 26ᵃ</span> <span dir=\"rtl\">מקל ב׳</span> (not <a href=\"#\" data-headword=\"מֵיקֵל\">מיקל</a>) the commissioner’s pointed staff (with which he searches). Y’lamd. to Gen. XXXVIII, 1 quot. in Ar. <span dir=\"rtl\">בלשיי מסר וכ׳</span> the constable delivers the prisoner over to the executioner.—Pl. <a href=\"#\" data-headword=\"בַּלְשִׁי\">בַּלְשִׁין</a>. <span class=\"citation\">Kel. XV, 4</span> <span dir=\"rtl\">מקל הב׳</span>, v. supra.—<span dir=\"rtl\">בַּלְשִׁיִּין</span>. Y’lamd. to Num. XXIII, 7. [Var. in Hai Gaon <span dir=\"rtl\">בַּלְסַיי</span>.]</div>","alt":["בַּלְשַׁיי"]},"4377":{"h":"בֵּלְשָׁפָט","r":"B00920","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Belshafat</i> (contr. of <a href=\"#\" data-headword=\"בֵּי אֱלִישָׁפָט\">בי אלישפט</a>), a staple town in Susiana (Khazistan), Syriac name <i>Beth-Lapetha = Ahwaz</i> (Neub. Géogr. p. 380). <span class=\"citation\">Taan. 22ᵃ</span> <span dir=\"rtl\">בי לפט</span> ed. (Var. <a href=\"#\" data-headword=\"בילפט\">בילפט</a>, <a href=\"#\" data-headword=\"בולשפטי\">בולשפטי</a>, v. Rabb. D. S. a. l. note 8). <span class=\"citation\">B. Mets. 73ᵇ</span> <a href=\"#\" data-headword=\"זוּלְשָׁפָט\">זולשפט</a> ed. (Ar. <a href=\"#\" data-headword=\"לוּלְשָׁפָט\">לולשפט</a>, Ms. H. <a href=\"#\" data-headword=\"בֵּלְשָׁפָט\">בלשפט</a>); <span class=\"citation\">B. Bath. 98ᵃ</span> <span dir=\"rtl\">וול שפט</span> ed. (Ar. <span dir=\"rtl\">לולש׳</span>; Ms. M. <span dir=\"rtl\">ולשפט</span>; Var. <span dir=\"rtl\">ויל שפט</span>, <span dir=\"rtl\">וילש׳</span>, <span dir=\"rtl\">לישפט</span>, <span dir=\"rtl\">בי לישפט</span>, v. Rabb. D. S. a. l. note). [Yoḥăsin s. v. <a href=\"#\" data-headword=\"בַּרְקָתָא\">ברוקא</a>: <a href=\"#\" data-headword=\"בֵּי אֱלִישָׁפָט\">בי אלישפט</a>.]</div>","alt":[]},"4378":{"h":"בַּלֶּשֶׁת","r":"B00921","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בלש</span>) <i>reconnoitring troop, quartermaster’s division, marauders</i>. <span class=\"citation\">Bets. 21ᵃ</span>; <span class=\"citation\">Tosef. ib. II, 6</span>. <span class=\"citation\">Ab. Zar. V, 6</span> (Y. ed. <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בו׳</a>). Y. ib. 45ᵃ top <span dir=\"rtl\">בשלום בו׳ ובמלחמת בו׳</span> the Mishnah means when the troop comes in peace, or when it comes with hostility. <span class=\"citation\">Sabb. 145ᵇ</span> ed. <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בו׳</a>, Ar. <span dir=\"rtl\">בל׳</span>.</div>","alt":["בּוֹלֶשֶׁת"]},"4379":{"h":"בַּלְתִּי","r":"B00922","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Beth-Baltin</i> &amp;c., v. <a href=\"#\" data-headword=\"בִּירָם\">בִּירָם</a>. <span class=\"citation\">R. Hash. II, 4</span> (<span class=\"citation\">22ᵇ</span>; Ms. M. <span dir=\"rtl\">בילתי</span>, <a href=\"#\" data-headword=\"בַּלְתִּי\">בלתי</a>; v. Rabb. D. S. c. l. note). Ib. 23ᵃ bot. <span dir=\"rtl\">מאי בית ב׳</span> (Ms. M. 1 <span dir=\"rtl\">בילתי</span>, 2 <span dir=\"rtl\">בלחי</span>, Ms. L. <a href=\"#\" data-headword=\"בִּילְתִּין\">בילתין</a>) what is B. B.? Answ. <a href=\"#\" data-headword=\"בִּירָם\">בירם</a>.</div>","alt":["בַּלְתִּין","בַּלְתָּן","בית ב׳"]},"4380":{"h":"במגנימין","r":"B00923","html":"<div class=\"sense\">, <span class=\"citation\">Y. R. Hash. I, 57ᵇ</span>, <span dir=\"rtl\">כהדא ב׳</span>, prob. to be read: <span dir=\"rtl\">כהדין אִיפוֹמְנִימָטִין</span> (ὑπομνήματα) like <i>the minutes</i> of the court proceedings, opp. to <a href=\"#\" data-headword=\"בַּלְתִּי\">preced.</a> <span dir=\"rtl\">דירין</span>, read <span dir=\"rtl\">דִּיקִין</span> (δίκη, pl.).</div>","alt":[]},"4381":{"h":"בְּמִדְבַּר","r":"B00924","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>the fourth book of Moses</i> (<i>Numeri</i>). <span class=\"citation\">Gen. R. s. 3</span>; a. e.—<span dir=\"rtl\">ב׳ רבה</span> the fourth book of Midrash Rabbah (Num. R.).</div>","alt":["סֵפֶר ב׳"]},"4382":{"h":"בָּמָה","r":"B00925","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>entrance, gathering place, ascent</i> (cmp. b. h. <a href=\"#\" data-headword=\"מָבוֹא\">מָבוֹא</a> a. <a href=\"#\" data-headword=\"מַעֲלֶה I\">מַעֲלֶה</a>); esp. <i>Bamah</i>, name of the legitimate altars prior to, and of the illegitimate after, the establishment of a central sanctuary (at Shiloh) and of the Temple at Jerusalem; <i>temporary</i> or <i>improvised altar;</i> v. <span class=\"citation\">Zeb. XIV, 4—8</span>.—<span class=\"citation\">Meg. I, 10</span> <span dir=\"rtl\">ב׳ גדולה</span> national altar; <span dir=\"rtl\">ב׳ קטנה</span> local altar (during their period of legitimacy); <span class=\"citation\">Tosef. Zeb. XIII, 17</span> sq.; a. fr.—Pl. <span dir=\"rtl\">בָּמוֹת</span> Zeb. l. c. Ib. 114ᵇ <span dir=\"rtl\">בשעת היתר הב׳</span> at the period when bamoth were permitted. v. supra; a. fr. [<span class=\"citation\">Meg. 32ᵃ</span> <span dir=\"rtl\">הלוחות והב׳</span>, v. <a href=\"#\" data-headword=\"בִּימָה\">בִּימָה</a>.] Cmp. <a href=\"#\" data-headword=\"בִּימָה\">בִּימָה</a>.</div>","alt":[]},"4383":{"h":"בָּמוֹסָא","r":"B00926","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בָּמָסָא\">בָּמָסָא</a></div>","alt":[]},"4384":{"h":"בָּמוֹתָא","r":"B00927","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּמְתָא\">בָּמְתָא</a></div>","alt":[]},"4385":{"h":"במיסטאות","r":"B00928","html":"<div class=\"sense\">, Midr. Thron. Salom., Beth-Hammidr. ed. Jellinek V, 2, read <span dir=\"rtl\">בָּימוֹסָאוֹת</span>, v. <a href=\"#\" data-headword=\"בִּימוּס\">בִּימוֹס</a></div>","alt":[]},"4386":{"h":"*בָּמָסָא","r":"B00929","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>altar, high-place</i>. [<span class=\"citation\">Targ. Y. II, Deut. XXXII, 13</span> <a href=\"#\" data-headword=\"*בָּמָסָא\">בַּמְסָא</a>, read <a href=\"#\" data-headword=\"בָּמְתָא\">בָּמָתָא</a>.]—Pl. <span dir=\"rtl\">בָּמָסַיָּא</span>, <span dir=\"rtl\">בָּמוֹסִין</span>, <span dir=\"rtl\">בָּמוֹסַיָּא</span> (<span dir=\"rtl\">בַּמְסַיָּא</span>) <i>idolatrous places of worship</i>. <span class=\"citation\">Targ. II Chr. XIV, 4</span>; a. e.</div>","alt":[]},"4387":{"h":"במרזה","r":"B00930","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to VII, 10</span> some ed., read <span dir=\"rtl\">ככּוֹמֶר הזה</span>.</div>","alt":[]},"4388":{"h":"בָּמְתָא","r":"B00931","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. I Kings III, 4</span>; a. e.—Pl. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"בָּמוֹתָא\">בָּמוֹתָא</a>) <a href=\"#\" data-headword=\"בָּמְתָא\">בָּמָתָא</a></span>. Targ. ib. 2; a. e.—[<span class=\"citation\">Targ. II Chr. XI, 15</span> <span dir=\"rtl\">בָּמָתַיָּיא</span>.]</div>","alt":[]},"4389":{"h":"בֵּן","r":"B00932","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, constr. <a href=\"#\" data-headword=\"בֵּן\">בֶּן</a> (b. h.; <a href=\"#\" data-headword=\"בני\">בנה</a>) <i>offspring, son, child</i>. <span dir=\"rtl\">שבוע הב׳</span> the male child’s week, a disguise for <i>circumcision day</i>, adopted during the Hadrianic persecutions. <span class=\"citation\">Snh. 32ᵇ</span>; <span class=\"citation\">Y. Keth. I, 25ᶜ</span>; a. e.—<span dir=\"rtl\">ישוע הב׳</span> a disguise for <span dir=\"rtl\">פִּדְיוֹן הבן</span>. <span class=\"citation\">B. Kam. 80ᵃ</span>.—… <span dir=\"rtl\">בְּנוֹ של</span> the son of, v. <a href=\"#\" data-headword=\"שֶׁל\">שֶׁל</a>. <span dir=\"rtl\">בְּנָן של קדושים</span> descendant of holy men. <span class=\"citation\">Ab. Zar. 50ᵃ</span>; a. e.—Pl. <span dir=\"rtl\">בָּנִים</span>, constr. <a href=\"#\" data-headword=\"בְּנֵי\">בְּנֵי</a>. <span class=\"citation\">Ab. III, 14</span> <span dir=\"rtl\">ב׳ למקום</span> chosen children of God. <span class=\"citation\">Gen. R. s. 82</span> <span dir=\"rtl\">בָּנֶיהָ של תורה</span> children (followers) of the Law.—Trnsf. <i>belonging to, fit for</i> &amp;c.; e.g. <span dir=\"rtl\">בני גולה</span> those belonging to the colony of exiles, Babylonians &amp;c.; <span dir=\"rtl\">בני גליל</span> Galileans; <span dir=\"rtl\">בני אכילה</span> things fit to be eaten &amp;c. [For such compounds as are not self-evident, see the respective determinants.] [<span dir=\"rtl\">בני פיקרין</span>, v. <a href=\"#\" data-headword=\"בְּנִיפִיקָרִין\">בְּנִיפיקָרִין</a>.]</div>","alt":[]},"4390":{"h":"בְּנָא","r":"B00933","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בני\">בני</a></div>","alt":[]},"4391":{"h":"בַּנָּאָה","r":"B00934","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <a href=\"#\" data-headword=\"בַּלַּן\">בַּלְנָא</a>) </div><div class=\"sense\"><b>1)</b> <i>bather</i>. Targ. II, <span class=\"citation\">Esth. VI, 12</span> Ms. (ed. <a href=\"#\" data-headword=\"בַּאנְיָא\">בַּאנְיָא</a>).</div><div class=\"sense\"><b>—2)</b>  pr. n. m., v. <a href=\"#\" data-headword=\"בַּנַּאי II\"><span dir=\"rtl\">בַּנַּאי</span> II</a></div>","alt":[]},"4392":{"h":"בַּנַּאי","r":"B00935","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בני\">בני</a>) <i>builder, mason</i>. <span class=\"citation\">B. Mets. 118ᵇ</span>; a. fr.—<span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> top <span dir=\"rtl\">אומנתיה דהן ב׳</span> this boy’s trade should be that of a builder. <span class=\"citation\">Sabb. 156ᵇ</span> <span dir=\"rtl\">ב׳ וסתיר וכ׳</span> (shall grow to be one) who builds and destroys, destroys and builds (restless). <span class=\"citation\">Ib. 115ᵃ</span>; a. fr. V. <a href=\"#\" data-headword=\"אַרְדִּיכָל\">אַרְרִּיכָל</a>.—[V. <a href=\"#\" data-headword=\"בַּנָּאִים\">בַּנָּאִים</a>, <a href=\"#\" data-headword=\"בַּנָּאִים\">בַּנָּאִין</a>.]</div>","alt":[]},"4393":{"h":"בַּנַּאי II","r":"B00936","html":"<div class=\"sense\"> (= <span dir=\"rtl\">רב ב׳</span>) pr. n. m. <i>Bannai, Bannaah, Rabbannai</i>, name of an Amora. <span class=\"citation\">Keth. 50ᵇ</span>. <span class=\"citation\">Ber. 38ᵇ</span>. [<span class=\"citation\">Ib. 55ᵇ</span> Ms. M. <a href=\"#\" data-headword=\"נְהוֹרַאי\">נהוראי</a>. <span class=\"citation\">B. Mets. 2ᵃ</span>, a. e. <span dir=\"rtl\">רב׳</span>, Ms. M. <a href=\"#\" data-headword=\"רָבִינָא\">רבינא</a>, v. Rabb. D. S. a. l. note.]</div>","alt":["בַּנָּאָה","רַבַּנַּאי"]},"4394":{"h":"בַּנָּאִים","r":"B00937","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> sing. a. pl. (contr. of <span dir=\"rtl\">בן נאים</span>, v. <a href=\"#\" data-headword=\"נָאֶה\">נָאֶה</a>) <i>one of becoming conduct, refined, a cultured person;</i> opp. <a href=\"#\" data-headword=\"בּוּר\">בּוֹר</a>; (cmp. <span class=\"citation\">Sabb. 114ᵃ</span> top, as to a scholar’s duty to pay attention to dress). [For oth. opin., v. Sachs Beitr. II, 199; Frankel Monatsschr. 1846, p. 855.] <span class=\"citation\">Mikv. IX, 6</span>; Sabb. l. c. <span dir=\"rtl\">של ב׳ וכ׳</span> the garments of a Bannaïm, if stained with pitch on one side cannot be immersed for levitical purposes before the stain is removed (because their owner is more fastidious). <span class=\"citation\">Tosef. Mikv. VI</span> (<span class=\"citation\">VII), 14</span> (where <span dir=\"rtl\">גדולה</span> a. <a href=\"#\" data-headword=\"קָטָן\">קטנה</a> refer to the stain; as to correct vers. v. R. S. to Mikv. l. c.). Sabb. l. c. <span dir=\"rtl\">מאי ב׳</span> what does B. mean? Answer: <span dir=\"rtl\">אלו וכ׳</span> it means the scholars who are engaged in building up the world (of civilization) all their lives (as if fr. <a href=\"#\" data-headword=\"בני\">בָּנָה</a>). Ib. (dresses of the B.) <span dir=\"rtl\">אלו כלים וכ׳</span> are the court-garments imported &amp;c., v. <a href=\"#\" data-headword=\"אוֹלָרִין\">אוֹלָרִין</a>.</div>","alt":["בַּנָּאִין"]},"4395":{"h":"בנאיתא","r":"B00938","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּנְיָיתָא\">בִּנְיָיתָא</a></div>","alt":[]},"4396":{"h":"בְּנָאתָן","r":"B00939","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"בְּרַתָּא\">בְּרַתָּא</a>.</div>","alt":[]},"4397":{"h":"בָּנוֹיָא","r":"B00940","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בני\">בני</a>) <i>builder</i>. . <span class=\"citation\">Yoma 10ᵃ</span> <span dir=\"rtl\">ב׳ ביר וכ׳</span> shall the builders (of the Temple, the Persians) be delivered into the hands of the destroyers (the Romans)?</div>","alt":[]},"4398":{"h":"בָּנוֹת","r":"B00941","html":"<div class=\"sense\"> pl. of <a href=\"#\" data-headword=\"בַּת I\">בַּת</a>.</div>","alt":[]},"4399":{"h":"בני","r":"B00942","html":"<div class=\"sense\"> [<i>to combine</i>,] <i>to build</i>. <span class=\"citation\">Sabb. XII, 1</span> <span dir=\"rtl\">הַבּוֹנֶה</span> he who builds (on the Sabbath). Ib.] 102ᵇ <span dir=\"rtl\">משום בונה</span> (isguilty) because it is one of the labors classified under ‘building’; a. fr.—Metaph. <i>to educate, train</i>. <span class=\"citation\">Ber. 64ᵃ</span> (ref. to <span class=\"citation\">Is. LIV, 93</span>) <span dir=\"rtl\">א&quot;ת בָּנַיִךְ אלא בוֹנַיִּךְ</span> read not <i>banayikh</i> (thy children), but <i>bonayikh</i> (thy builders, trainers); v. <a href=\"#\" data-headword=\"בַּנָּאִים\">בַּנָּאִים</a>.—<span class=\"citation\">Ex. R. s. 23</span> (play on b’noth, <span class=\"citation\">Cant. I, 5</span>) <span dir=\"rtl\">בּוֹנוֹת וכ׳</span> the authorities directing the building of Jerusalem; v. Pi.—<span class=\"citation\">Ḥull. 78ᵇ</span> <span dir=\"rtl\">זה בנה אב</span>, v. <a href=\"#\" data-headword=\"אַבָּא I\">אָב</a>, a. <a href=\"#\" data-headword=\"בִּנְיָן\">בִּנְיָן</a>. [<span class=\"citation\">Tosef. Par. VII</span> (<span class=\"citation\">VI), 4</span> <span dir=\"rtl\">בְּנָאוֹ</span> ed. Zuck., v. <a href=\"#\" data-headword=\"כָּנַן\">כָּנַן</a>.]</div><div class=\"sense\"><b>Nif. נִבְנֶה</b> <div class=\"sense\"><b>1)</b> <i>to be built up</i>. Y. B. Bath. III, 14ᵇ, a. fr. <span dir=\"rtl\">לְהִיבָּנוֹת</span>, <span dir=\"rtl\">לִיבָּנוֹת</span>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"בֵּן\">בֵּן</a>) <i>to get children</i>. <span class=\"citation\">Gen. R. s. 71</span>.</div></div><div class=\"sense\"><b>Nithpa. נִתְבַּנֶּה</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"בֵּן\">בֵּן</a>) <i>to be adopted, naturalized</i>. <span class=\"citation\">Pesik. R. s. 43</span> <span dir=\"rtl\">נִתְבַּנּוּ בישראל</span> they became full Israelitish citizens.</div></div><div class=\"sense\"><b>Pi. בִּינָּה</b> <div class=\"sense\"><i>to lay out, plan a city, determine its limits</i>. Ex. R. l. c. the Great Sanedrin held sessions <span dir=\"rtl\">ומְבַנָּים אותה</span> (not <span dir=\"rtl\">אותם</span>) and determined the limits of Jerusalem; v. <span class=\"citation\">Snh. I, 5</span>.—Part. Pu. <a href=\"#\" data-headword=\"מְמוּנֶּה\">מְבוּנֶּה</a> <i>cultivated; built</i> (of human stature), <i>well-proportioned</i>. <span class=\"citation\">Keth. 112ᵃ</span>; <span class=\"citation\">Sot. 34ᵇ</span> <span dir=\"rtl\">היתה מְבוּנָּה על וכ׳</span> it (Hebron, in spite of the rocky nature of its soil) was seven times better cultivated than Zoan (one measure of its land yielding as much as did seven measures of the soil of Zoan). <span class=\"citation\">Ib. 42ᵇ</span> (play on <i>benayim</i>, <span class=\"citation\">I Sam. XVII, 4</span>) <span dir=\"rtl\">מב׳ מכל מום</span> his build was without blemish.</div></div>","alt":["בָּנָה"]}};
